css:
@keyframes dbh-vitals-flash { 0%, 100% { opacity: 0.35; } 50% { opacity: 1; } }
@keyframes dbh-vitals-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes dbh-vitals-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbh-vitals-blink { 50% { opacity: 0.25; } }

.dbh-vitals {
  /* re-theme with these five */
  --dbh-vitals-bg: oklch(0.17 0.012 165);
  --dbh-vitals-ink: oklch(0.94 0.012 150);
  --dbh-vitals-ecg: oklch(0.86 0.19 146);
  --dbh-vitals-pleth: oklch(0.83 0.14 70);
  --dbh-vitals-resp: oklch(0.85 0.075 228);
  --dbh-vitals-alarm: oklch(0.66 0.21 27);
  --dbh-vitals-warn: oklch(0.87 0.16 98);
  /* derived */
  --dbh-vitals-panel: color-mix(in oklch, var(--dbh-vitals-bg), var(--dbh-vitals-ink) 4%);
  --dbh-vitals-raise: color-mix(in oklch, var(--dbh-vitals-bg), var(--dbh-vitals-ink) 9%);
  --dbh-vitals-line: color-mix(in oklch, var(--dbh-vitals-ink) 10%, transparent);
  --dbh-vitals-line2: color-mix(in oklch, var(--dbh-vitals-ink) 19%, transparent);
  --dbh-vitals-muted: color-mix(in oklch, var(--dbh-vitals-ink) 58%, var(--dbh-vitals-bg));
  --dbh-vitals-faint: color-mix(in oklch, var(--dbh-vitals-ink) 34%, var(--dbh-vitals-bg));
  --dbh-vitals-ease: cubic-bezier(0.22, 0.8, 0.24, 1);
  --dbh-vitals-spring: linear(0, 0.02, 0.09 4%, 0.42 11%, 0.83 19%, 1.04 26%, 1.08 31%, 1.05 38%, 1 48%, 0.99 58%, 1);
  --dbh-vitals-mono: ui-monospace, Menlo, Consolas, monospace;

  width: 100%;
  height: var(--dbh-vitals-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dbh-vitals-bg);
  color: var(--dbh-vitals-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dbh-vitals-ecg);
  color-scheme: dark;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbh-vitals-ecg); outline-offset: 2px; border-radius: 6px; }
  & h2 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dbh-vitals-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.09em; text-transform: uppercase; color: var(--dbh-vitals-muted); }

  .dbh-vitals-app { display: grid; height: 100%; grid-template-columns: 252px minmax(0, 1fr); grid-template-areas: "side main"; }

  /* ---------- side ---------- */
  .dbh-vitals-side { grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 14px; padding: 18px 12px 14px; border-right: 1px solid var(--dbh-vitals-line); background: color-mix(in oklch, var(--dbh-vitals-bg), black 18%); }
  .dbh-vitals-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px; }
  .dbh-vitals-brand svg { flex: none; width: 30px; height: 30px; padding: 5px; border-radius: 8px; background: color-mix(in oklch, var(--dbh-vitals-ecg) 16%, transparent); fill: none; stroke: var(--dbh-vitals-ecg); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  .dbh-vitals-brand span { display: grid; line-height: 1.2; min-width: 0; }
  .dbh-vitals-brand b { font-size: 14px; font-weight: 650; letter-spacing: -0.01em; }
  .dbh-vitals-brand small { font-size: 11px; color: var(--dbh-vitals-muted); }
  .dbh-vitals-sidehead { display: flex; align-items: baseline; justify-content: space-between; padding: 0 6px; }
  .dbh-vitals-census { font: 500 11px var(--dbh-vitals-mono); color: var(--dbh-vitals-faint); font-variant-numeric: tabular-nums; }
  .dbh-vitals-beds { flex: 1; min-height: 0; overflow: auto; display: grid; align-content: start; gap: 4px; padding: 2px; scrollbar-width: thin; scrollbar-color: var(--dbh-vitals-line2) transparent; }
  .dbh-vitals-disc { padding: 0 6px; font-size: 11px; color: var(--dbh-vitals-faint); }

  .dbh-vitals-bed {
    position: relative; isolation: isolate;
    display: grid; grid-template-columns: 34px minmax(0, 1fr) auto; grid-template-rows: auto auto; column-gap: 8px; align-items: center;
    padding: 7px 10px 6px 8px; border-radius: 10px; cursor: pointer; outline-offset: -2px;
    transition: background-color 160ms, box-shadow 160ms;
    animation: dbh-vitals-rise 520ms var(--dbh-vitals-ease) both; animation-delay: calc(var(--i, 0) * 45ms);
  }
  .dbh-vitals-bed:hover { background: var(--dbh-vitals-panel); }
  .dbh-vitals-bed[aria-selected="true"] { background: var(--dbh-vitals-raise); box-shadow: inset 0 0 0 1px var(--dbh-vitals-line2); }
  .dbh-vitals-bed::before { content: ""; position: absolute; inset: 0; z-index: -1; border-radius: inherit; opacity: 0; pointer-events: none; }
  .dbh-vitals-bed[data-alarm="med"]::before { background: color-mix(in oklch, var(--dbh-vitals-warn) 22%, transparent); box-shadow: inset 3px 0 0 var(--dbh-vitals-warn); animation: dbh-vitals-flash 1.2s steps(2, jump-none) infinite; }
  .dbh-vitals-bed[data-alarm="high"]::before { background: color-mix(in oklch, var(--dbh-vitals-alarm) 30%, transparent); box-shadow: inset 3px 0 0 var(--dbh-vitals-alarm); animation: dbh-vitals-flash 0.6s steps(2, jump-none) infinite; }
  .dbh-vitals-bed[data-ack]::before { animation: none; opacity: 0.55; }
  .dbh-vitals-bn { grid-row: 1 / 3; font: 650 15px/1 var(--dbh-vitals-mono); font-variant-numeric: tabular-nums; color: var(--dbh-vitals-muted); }
  .dbh-vitals-bed[aria-selected="true"] .dbh-vitals-bn { color: var(--dbh-vitals-ink); }
  .dbh-vitals-bp { min-width: 0; display: grid; line-height: 1.25; }
  .dbh-vitals-bp b { font-weight: 600; font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dbh-vitals-bp small { font-size: 11px; color: var(--dbh-vitals-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dbh-vitals-bv { display: grid; justify-items: end; font: 600 13px/1.2 var(--dbh-vitals-mono); font-variant-numeric: tabular-nums; }
  .dbh-vitals-bv [data-k="hr"] { color: var(--dbh-vitals-ecg); }
  .dbh-vitals-bv [data-k="spo2"] { color: var(--dbh-vitals-pleth); }
  .dbh-vitals-bed[data-alarm] [data-k="spo2"] { color: var(--dbh-vitals-ink); }
  .dbh-vitals-spark { grid-column: 2 / 4; width: 100%; height: 13px; margin-top: 3px; overflow: visible; }
  .dbh-vitals-spark path { fill: none; stroke: color-mix(in oklch, var(--dbh-vitals-ecg) 55%, transparent); stroke-width: 1.2; vector-effect: non-scaling-stroke; }
  .dbh-vitals-bed[data-standby] { opacity: 0.6; }
  .dbh-vitals-bed[data-standby] .dbh-vitals-bv { color: var(--dbh-vitals-faint); font-weight: 500; }

  /* ---------- main ---------- */
  .dbh-vitals-main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); }
  .dbh-vitals-head { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 18px; padding: 14px 18px 12px; border-bottom: 1px solid var(--dbh-vitals-line); }
  .dbh-vitals-who { display: flex; align-items: center; gap: 12px; min-width: 0; flex: 1 1 260px; }
  .dbh-vitals-bedno { flex: none; display: grid; place-items: center; width: 46px; height: 46px; border-radius: 10px; background: var(--dbh-vitals-raise); font: 650 17px var(--dbh-vitals-mono); font-variant-numeric: tabular-nums; }
  .dbh-vitals-whot { min-width: 0; display: grid; gap: 2px; }
  .dbh-vitals-name { font-size: clamp(16px, 0.7rem + 1.1cqi, 21px); font-weight: 620; letter-spacing: -0.015em; line-height: 1.15; }
  .dbh-vitals-meta { font-size: 12px; color: var(--dbh-vitals-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dbh-vitals-meta b { color: var(--dbh-vitals-ecg); font-weight: 600; }
  .dbh-vitals-tabs, .dbh-vitals-seg { display: inline-flex; gap: 2px; padding: 3px; border-radius: 9px; background: var(--dbh-vitals-panel); box-shadow: inset 0 0 0 1px var(--dbh-vitals-line); }
  .dbh-vitals-tabs button, .dbh-vitals-seg button { height: 28px; padding: 0 12px; border-radius: 7px; font-size: 12.5px; font-weight: 560; color: var(--dbh-vitals-muted); transition: background-color 160ms, color 160ms; }
  .dbh-vitals-tabs button:hover, .dbh-vitals-seg button:hover { color: var(--dbh-vitals-ink); }
  .dbh-vitals-tabs [aria-selected="true"], .dbh-vitals-seg [aria-checked="true"] { background: var(--dbh-vitals-raise); color: var(--dbh-vitals-ink); box-shadow: 0 1px 0 color-mix(in oklch, var(--dbh-vitals-ink) 8%, transparent) inset; }
  .dbh-vitals-clock { display: flex; align-items: center; gap: 7px; font: 500 13px var(--dbh-vitals-mono); font-variant-numeric: tabular-nums; color: var(--dbh-vitals-muted); }
  .dbh-vitals-rec { width: 7px; height: 7px; border-radius: 50%; background: var(--dbh-vitals-ecg); box-shadow: 0 0 10px var(--dbh-vitals-ecg); animation: dbh-vitals-blink 2s steps(2, jump-none) infinite; }

  .dbh-vitals-view { min-height: 0; }

  /* ---------- live ---------- */
  .dbh-vitals-live { display: grid; grid-template-columns: minmax(0, 1fr) clamp(220px, 27cqi, 312px); }
  .dbh-vitals-waves { position: relative; display: grid; grid-template-rows: 2fr 1fr 1fr; min-height: 0; border-right: 1px solid var(--dbh-vitals-line); transition: opacity 220ms var(--dbh-vitals-ease); }
  .dbh-vitals-waves[data-swap] { opacity: 0; }
  .dbh-vitals-strip { position: relative; min-height: 0; border-bottom: 1px solid var(--dbh-vitals-line);
    background-image: linear-gradient(to right, var(--dbh-vitals-line) 1px, transparent 1px), linear-gradient(to bottom, color-mix(in oklch, var(--dbh-vitals-ink) 5%, transparent) 1px, transparent 1px);
    background-size: 20px 20px; background-position: -1px -1px; }
  .dbh-vitals-strip:last-of-type { border-bottom: 0; }
  .dbh-vitals-strip[data-w="ecg"] { color: var(--dbh-vitals-ecg); }
  .dbh-vitals-strip[data-w="pleth"] { color: var(--dbh-vitals-pleth); }
  .dbh-vitals-strip[data-w="resp"] { color: var(--dbh-vitals-resp); }
  .dbh-vitals-strip canvas { position: absolute; inset: 0; width: 100%; height: 100%; }
  .dbh-vitals-wl { position: absolute; z-index: 1; top: 6px; left: 8px; padding: 2px 6px; border-radius: 6px; background: color-mix(in oklch, var(--dbh-vitals-bg) 78%, transparent); display: flex; align-items: baseline; gap: 8px; font-size: 12px; font-weight: 650; letter-spacing: 0.02em; pointer-events: none; }
  .dbh-vitals-wl small { font: 500 10.5px var(--dbh-vitals-mono); color: var(--dbh-vitals-faint); letter-spacing: 0; }
  .dbh-vitals-standby { position: absolute; z-index: 2; inset: 0; display: grid; place-content: center; justify-items: center; gap: 8px; text-align: center; padding: 24px; background: var(--dbh-vitals-bg); color: var(--dbh-vitals-muted); }
  .dbh-vitals-standby svg { width: 34px; height: 34px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; }
  .dbh-vitals-standby b { color: var(--dbh-vitals-ink); font-size: 15px; font-weight: 600; }
  .dbh-vitals-standby span { max-width: 32ch; }

  .dbh-vitals-nums { min-height: 0; overflow: auto; display: grid; grid-template-columns: 1fr 1fr; grid-template-areas: "hr hr" "spo2 spo2" "rr temp" "nibp nibp" "alarm alarm"; grid-auto-rows: auto; align-content: start; scrollbar-width: thin; scrollbar-color: var(--dbh-vitals-line2) transparent; }
  .dbh-vitals-num { animation: dbh-vitals-rise 640ms var(--dbh-vitals-ease) both; animation-delay: calc(var(--i, 0) * 70ms + 150ms); }
  .dbh-vitals-num { position: relative; isolation: isolate; display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-rows: auto 1fr; padding: 10px 14px 12px; border-bottom: 1px solid var(--dbh-vitals-line); min-width: 0; }
  .dbh-vitals-num[data-p="hr"] { grid-area: hr; color: var(--dbh-vitals-ecg); }
  .dbh-vitals-num[data-p="spo2"] { grid-area: spo2; color: var(--dbh-vitals-pleth); }
  .dbh-vitals-num[data-p="rr"] { grid-area: rr; color: var(--dbh-vitals-resp); border-right: 1px solid var(--dbh-vitals-line); }
  .dbh-vitals-num[data-p="temp"] { grid-area: temp; }
  .dbh-vitals-num[data-p="nibp"] { grid-area: nibp; }
  .dbh-vitals-nl { grid-column: 1 / -1; display: flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 650; letter-spacing: 0.03em; }
  .dbh-vitals-nl small { font-weight: 500; color: var(--dbh-vitals-faint); letter-spacing: 0; }
  .dbh-vitals-beat { width: 13px; height: 13px; margin-left: auto; fill: currentColor; opacity: 0.45; }
  .dbh-vitals-nv { align-self: end; font-weight: 300; font-size: clamp(28px, 3.1cqi, 40px); line-height: 1; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; white-space: nowrap; }
  .dbh-vitals-num[data-p="hr"] .dbh-vitals-nv, .dbh-vitals-num[data-p="spo2"] .dbh-vitals-nv { font-size: clamp(46px, 5.6cqi, 72px); font-weight: 250; }
  .dbh-vitals-lim { align-self: end; display: grid; gap: 2px; justify-items: end; font: 500 10.5px/1 var(--dbh-vitals-mono); color: var(--dbh-vitals-faint); padding-bottom: 4px; }
  .dbh-vitals-sub { grid-column: 1 / -1; margin-top: 4px; font: 500 11px var(--dbh-vitals-mono); color: var(--dbh-vitals-faint); font-variant-numeric: tabular-nums; }
  .dbh-vitals-sub [data-v="map"] { color: var(--dbh-vitals-muted); }
  .dbh-vitals-num::before { content: ""; position: absolute; inset: 0; z-index: -1; opacity: 0; pointer-events: none; }
  .dbh-vitals-num[data-alarm="med"] { color: var(--dbh-vitals-bg); }
  .dbh-vitals-num[data-alarm="med"]::before { background: var(--dbh-vitals-warn); opacity: 1; }
  .dbh-vitals-num[data-alarm="high"] { color: var(--dbh-vitals-ink); }
  .dbh-vitals-num[data-alarm="high"]::before { background: var(--dbh-vitals-alarm); opacity: 1; }
  .dbh-vitals-num[data-alarm] :is(small, .dbh-vitals-lim) { color: inherit; opacity: 0.7; }
  .dbh-vitals-alarmbar { grid-area: alarm; display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px; padding: 12px 14px; font-size: 12px; color: var(--dbh-vitals-muted); }
  .dbh-vitals-alarmbar[data-lvl] .dbh-vitals-amsg { color: var(--dbh-vitals-ink); font-weight: 600; }
  .dbh-vitals-alarmbar[data-lvl="high"] .dbh-vitals-amsg { color: var(--dbh-vitals-alarm); }
  .dbh-vitals-alarmbar[data-lvl="med"] .dbh-vitals-amsg { color: var(--dbh-vitals-warn); }
  .dbh-vitals-ack { height: 28px; padding: 0 12px; border-radius: 7px; font-size: 12px; font-weight: 600; background: var(--dbh-vitals-raise); box-shadow: inset 0 0 0 1px var(--dbh-vitals-line2); transition: background-color 150ms; }
  .dbh-vitals-ack:hover { background: color-mix(in oklch, var(--dbh-vitals-raise), var(--dbh-vitals-ink) 8%); }

  /* ---------- trends ---------- */
  .dbh-vitals-trend { display: grid; grid-template-rows: auto minmax(0, 1fr); padding: 12px 16px 14px; gap: 10px; }
  .dbh-vitals-tbar, .dbh-vitals-ebar { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px; }
  .dbh-vitals-tchart { position: relative; min-height: 0; }
  .dbh-vitals-tsvg { width: 100%; height: 100%; overflow: visible; border-radius: 8px; }
  .dbh-vitals-tsvg:focus-visible { outline-offset: 4px; }
  .dbh-vitals-tsvg text { font: 500 10.5px var(--dbh-vitals-mono); fill: var(--dbh-vitals-faint); font-variant-numeric: tabular-nums; }
  .dbh-vitals-tsvg .dbh-vitals-plabel { font: 650 11px system-ui, sans-serif; letter-spacing: 0.04em; }
  .dbh-vitals-tsvg .dbh-vitals-grid { stroke: var(--dbh-vitals-line); }
  .dbh-vitals-tsvg .dbh-vitals-limit { stroke-dasharray: 4 4; stroke-width: 1; opacity: 0.7; }
  .dbh-vitals-tsvg .dbh-vitals-band { opacity: 0.06; }
  .dbh-vitals-tsvg .dbh-vitals-line { fill: none; stroke-width: 1.5; stroke-linejoin: round; stroke-dasharray: 1; animation: dbh-vitals-draw 1100ms var(--dbh-vitals-ease) both; animation-delay: calc(var(--i, 0) * 120ms); }
  .dbh-vitals-tsvg .dbh-vitals-bpdot { fill: var(--dbh-vitals-ink); opacity: 0.5; }
  .dbh-vitals-tsvg .dbh-vitals-xh { stroke: var(--dbh-vitals-ink); stroke-opacity: 0.4; transition: opacity 120ms; }
  .dbh-vitals-tsvg .dbh-vitals-xd { stroke: var(--dbh-vitals-bg); stroke-width: 2; }
  .dbh-vitals-tip { position: absolute; top: 0; left: 0; z-index: 3; min-width: 150px; padding: 9px 11px; border-radius: 9px; pointer-events: none;
    background: color-mix(in oklch, var(--dbh-vitals-bg), var(--dbh-vitals-ink) 12%); box-shadow: 0 0 0 1px var(--dbh-vitals-line2), 0 12px 30px oklch(0 0 0 / 0.45);
    font: 500 11.5px/1.5 var(--dbh-vitals-mono); font-variant-numeric: tabular-nums; transition: translate 90ms linear; }
  .dbh-vitals-tip b { display: block; margin-bottom: 3px; font: 650 11px system-ui, sans-serif; letter-spacing: 0.06em; text-transform: uppercase; color: var(--dbh-vitals-muted); }
  .dbh-vitals-tip span { display: flex; justify-content: space-between; gap: 14px; }
  .dbh-vitals-tip em { font-style: normal; color: var(--dbh-vitals-muted); }
  .dbh-vitals-tip [data-flag] { color: var(--dbh-vitals-warn); }

  /* ---------- events ---------- */
  .dbh-vitals-events { display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 10px; padding: 12px 16px 14px; }
  .dbh-vitals-chips { display: flex; flex-wrap: wrap; gap: 6px; }
  .dbh-vitals-chips button { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 11px; border-radius: 99px; font-size: 12px; font-weight: 560; color: var(--dbh-vitals-muted); box-shadow: inset 0 0 0 1px var(--dbh-vitals-line2); transition: background-color 150ms, color 150ms; }
  .dbh-vitals-chips button i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); opacity: 0.35; transition: opacity 150ms, scale 260ms var(--dbh-vitals-spring); }
  .dbh-vitals-chips [data-lvl="high"] { --c: var(--dbh-vitals-alarm); }
  .dbh-vitals-chips [data-lvl="med"] { --c: var(--dbh-vitals-warn); }
  .dbh-vitals-chips [data-lvl="info"] { --c: var(--dbh-vitals-resp); }
  .dbh-vitals-chips [aria-pressed="true"] { color: var(--dbh-vitals-ink); background: var(--dbh-vitals-panel); }
  .dbh-vitals-chips [aria-pressed="true"] i { opacity: 1; scale: 1.15; }
  .dbh-vitals-ecount { margin-left: auto; font: 500 11.5px var(--dbh-vitals-mono); color: var(--dbh-vitals-faint); font-variant-numeric: tabular-nums; }
  .dbh-vitals-twrap { min-height: 0; overflow: auto; border-radius: 10px; box-shadow: inset 0 0 0 1px var(--dbh-vitals-line); scrollbar-width: thin; scrollbar-color: var(--dbh-vitals-line2) transparent; }
  .dbh-vitals-table { width: 100%; border-collapse: collapse; font-size: 12.5px; }
  .dbh-vitals-table th { position: sticky; top: 0; z-index: 1; text-align: left; padding: 0; background: var(--dbh-vitals-panel); border-bottom: 1px solid var(--dbh-vitals-line2); font-size: 11px; font-weight: 650; letter-spacing: 0.06em; text-transform: uppercase; color: var(--dbh-vitals-muted); }
  .dbh-vitals-table th:not(:has(button)) { padding: 9px 12px; }
  .dbh-vitals-table th button { width: 100%; text-align: left; padding: 9px 12px; letter-spacing: inherit; text-transform: inherit; font-weight: inherit; display: flex; align-items: center; gap: 6px; }
  .dbh-vitals-table th button::after { content: ""; width: 0; height: 0; border: 4px solid transparent; border-top-color: currentColor; opacity: 0; translate: 0 2px; transition: opacity 150ms, rotate 220ms var(--dbh-vitals-ease); }
  .dbh-vitals-table th[aria-sort] button { color: var(--dbh-vitals-ink); }
  .dbh-vitals-table th[aria-sort] button::after { opacity: 1; }
  .dbh-vitals-table th[aria-sort="ascending"] button::after { rotate: 180deg; translate: 0 -2px; }
  .dbh-vitals-table td { padding: 8px 12px; border-bottom: 1px solid var(--dbh-vitals-line); vertical-align: top; }
  .dbh-vitals-table tbody tr { animation: dbh-vitals-rise 380ms var(--dbh-vitals-ease) both; animation-delay: calc(min(var(--i, 0), 14) * 22ms); }
  .dbh-vitals-table tbody tr:hover { background: var(--dbh-vitals-panel); }
  .dbh-vitals-table .dbh-vitals-tt { font-family: var(--dbh-vitals-mono); font-variant-numeric: tabular-nums; color: var(--dbh-vitals-muted); white-space: nowrap; }
