ackBtn.addEventListener('click', () => { cur().ack = true; paintTile(cur()); paintNums(); });

let tickT = 0, lastEventCount = EVENTS.length;
function tick() {
  if (!root.isConnected) { cleanup(); return; }
  tickT = setTimeout(tick, 1000);
  if (!onScreen || document.hidden) return;
  simSec += 1;
