  head.name.textContent = b.standby ? 'Bed 408 · available' : b.name;
  head.meta.innerHTML = b.standby ? 'No patient assigned · monitor in standby' : `${b.age} ${b.sex} · ${b.note} · <b>${b.rhythm}</b>`;
  if (!b.standby) {
    $('[data-l="hr1"]').textContent = b.lim.hr[1]; $('[data-l="hr0"]').textContent = b.lim.hr[0];
    $('[data-l="sp0"]').textContent = b.lim.sp;
