    strips.forEach(s => { if (s.ctx) { s.ctx.clearRect(0, 0, s.w, s.h); s.x = 0; s.frac = 0; s.t = simWave; s.y = s.mid; s.phase = 0; } });
    if (!cur().standby) resetBeats(simWave);
