}
bedsEl.addEventListener('click', e => { const t = e.target.closest('.dbh-vitals-bed'); if (t) select(BEDS.findIndex(b => b.bed === t.dataset.bed)); });
bedsEl.addEventListener('keydown', e => {
  let j = -1;
  if (e.key === 'ArrowDown' || e.key === 'ArrowRight') j = Math.min(BEDS.length - 1, sel + 1);
  else if (e.key === 'ArrowUp' || e.key === 'ArrowLeft') j = Math.max(0, sel - 1);
  else if (e.key === 'Home') j = 0;
  else if (e.key === 'End') j = BEDS.length - 1;
  if (j < 0) return;
