}

/* ---------- trends ---------- */
let range = 480, T = null, hoverI = -1;
const tsvg = $('.dbh-vitals-tsvg'), tip = $('.dbh-vitals-tip'), tbox = $('.dbh-vitals-tchart');
const PANELS = [
  { k: 'hr', label: 'HR', unit: 'bpm', lo: 40, hi: 140, ticks: [60, 90, 120], color: 'var(--dbh-vitals-ecg)', lim: b => b.lim.hr },
  { k: 'sp', label: 'SpO₂', unit: '%', lo: 82, hi: 100, ticks: [85, 90, 95, 100], color: 'var(--dbh-vitals-pleth)', lim: b => [b.lim.sp, 100] },
  { k: 'rr', label: 'RR', unit: 'rpm', lo: 0, hi: 40, ticks: [10, 20, 30], color: 'var(--dbh-vitals-resp)', lim: b => b.lim.rr }
];
roving($('.dbh-vitals-trend .dbh-vitals-seg'), '[role="radio"]', 'aria-checked', t => { range = +t.dataset.range; renderTrend(); });

function renderTrend() {
  const b = cur();
