    p.ticks.forEach(t => { out += `<line class="dbh-vitals-grid" x1="${L}" x2="${W - Rm}" y1="${y(t).toFixed(1)}" y2="${y(t).toFixed(1)}"/><text x="${L - 6}" y="${(y(t) + 3.5).toFixed(1)}" text-anchor="end">${t}</text>`; });
    lim.forEach(l => { if (l < p.hi) out += `<line class="dbh-vitals-limit" x1="${L}" x2="${W - Rm}" y1="${y(l).toFixed(1)}" y2="${y(l).toFixed(1)}" style="stroke:currentColor"/>`; });
