    out += `<path class="dbh-vitals-line" pathLength="1" d="${d}" style="stroke:currentColor;--i:${pi}"/>`;
    out += `<text class="dbh-vitals-plabel" x="${L + 8}" y="${y0 + 13}" style="fill:currentColor">${p.label} <tspan style="fill:var(--dbh-vitals-faint)">${p.unit} · limits ${lim[0]}${lim[1] < p.hi ? '–' + lim[1] : ''}</tspan></text>`;
    out += '</g>';
  });
  out += `<g class="dbh-vitals-xhg" style="opacity:0"><line class="dbh-vitals-xh" y1="${top}" y2="${Hh - bot}"/>${PANELS.map(p => `<circle class="dbh-vitals-xd" r="4" style="fill:${p.color}"/>`).join('')}</g>`;
  tsvg.innerHTML = out;
  T = { x, s0, n, L, Rm, W, Hh };
}
function hoverAt(i) {
  if (!T) return;
  const b = cur();
  i = Math.max(T.s0, Math.min(HN - 1, i));
