    <span${flag(h.sp[i], b.lim.sp, 101)}><em>SpO₂</em>${h.sp[i]} %</span>
    <span${flag(h.rr[i], b.lim.rr[0], b.lim.rr[1])}><em>RR</em>${h.rr[i]} rpm</span>
