/* ---------- events ---------- */
let scope = 'bed', sortK = 't', sortDir = -1;
const lvls = new Set(['high', 'med', 'info']);
const tbody = $('.dbh-vitals-table tbody'), ecount = $('.dbh-vitals-ecount');
roving($('.dbh-vitals-events .dbh-vitals-seg'), '[role="radio"]', 'aria-checked', t => { scope = t.dataset.scope; renderEvents(); });
$('.dbh-vitals-chips').addEventListener('click', e => {
