  rows.sort((a, c) => cmp(a, c) * sortDir);
  tbody.innerHTML = rows.length ? rows.map((e, i) => `<tr style="--i:${i}${animate ? '' : ';animation:none'}">
    <td class="dbh-vitals-tt">${hm(Math.floor(e.t / 60))}</td><td>${e.bed}</td>
    <td>${e.text}${e.val ? ` <span class="dbh-vitals-tv">${e.val}</span>` : ''}</td>
    <td><span class="dbh-vitals-pill" data-lvl="${e.lvl}">${LNAME[e.lvl]}</span></td></tr>`).join('')
