/* ---------- lifecycle ---------- */
const io = new IntersectionObserver(es => { onScreen = es[es.length - 1].isIntersecting; if (onScreen) { lastNow = 0; kick(); } });
io.observe(root);
function onVis() {
  if (!root.isConnected) { cleanup(); return; }
  if (!document.hidden) { lastNow = 0; kick(); }
}
document.addEventListener('visibilitychange', onVis);
function cleanup() {
  io.disconnect(); ro.disconnect(); clearTimeout(tickT);
