css:
@keyframes dbh-sleep-tin { from { opacity: 0; scale: 1 0.05; } }
@keyframes dbh-sleep-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes dbh-sleep-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbh-sleep-wipe { from { clip-path: inset(0 100% 0 0 round 4px); } to { clip-path: inset(0 0 0 0 round 4px); } }

.dbh-sleep {
  /* re-theme with these */
  --dbh-sleep-bg: oklch(0.205 0.026 232);
  --dbh-sleep-ink: oklch(0.95 0.012 85);
  --dbh-sleep-accent: oklch(0.86 0.11 80);
  --dbh-sleep-awake: oklch(0.86 0.11 80);
  --dbh-sleep-rem: oklch(0.72 0.15 22);
  --dbh-sleep-light: oklch(0.76 0.06 222);
  --dbh-sleep-deep: oklch(0.53 0.1 252);
  /* derived */
  --dbh-sleep-card: color-mix(in oklch, var(--dbh-sleep-bg), var(--dbh-sleep-ink) 5%);
  --dbh-sleep-sunk: color-mix(in oklch, var(--dbh-sleep-bg), black 22%);
  --dbh-sleep-line: color-mix(in oklch, var(--dbh-sleep-ink) 10%, transparent);
  --dbh-sleep-line2: color-mix(in oklch, var(--dbh-sleep-ink) 20%, transparent);
  --dbh-sleep-muted: color-mix(in oklch, var(--dbh-sleep-ink) 62%, var(--dbh-sleep-bg));
  --dbh-sleep-faint: color-mix(in oklch, var(--dbh-sleep-ink) 38%, var(--dbh-sleep-bg));
  --dbh-sleep-ease: cubic-bezier(0.2, 0.8, 0.2, 1);
  --dbh-sleep-spring: linear(0, 0.013 0.6%, 0.05 1.2%, 0.2 2.6%, 0.86 8.3%, 1.03 10.6%, 1.1 12.6%, 1.11 14.4%, 1.08 16.6%, 1.01 21.6%, 0.99 24.8%, 1 33%, 1);
  --dbh-sleep-round: ui-rounded, system-ui, -apple-system, "Segoe UI", sans-serif;
  --dbh-sleep-mono: ui-monospace, Menlo, Consolas, monospace;

  width: 100%;
  height: var(--dbh-sleep-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 16px;
  background:
    radial-gradient(120% 70% at 85% -10%, color-mix(in oklch, var(--dbh-sleep-accent) 9%, transparent), transparent 60%),
    var(--dbh-sleep-bg);
  color: var(--dbh-sleep-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dbh-sleep-accent);
  color-scheme: dark;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbh-sleep-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul, & dl, & dd { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dbh-sleep-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.1em; text-transform: uppercase; color: var(--dbh-sleep-muted); }

  .dbh-sleep-app { display: grid; height: 100%; grid-template-columns: 232px minmax(0, 1fr); grid-template-areas: "side main"; }

  /* ---------- side ---------- */
  .dbh-sleep-side { grid-area: side; min-height: 0; overflow: auto; display: flex; flex-direction: column; gap: 22px; padding: 20px 14px 16px; border-right: 1px solid var(--dbh-sleep-line); scrollbar-width: thin; }
  .dbh-sleep-brand { display: flex; align-items: center; gap: 10px; padding: 0 4px; }
  .dbh-sleep-brand svg { flex: none; width: 32px; height: 32px; padding: 6px; border-radius: 50%; background: color-mix(in oklch, var(--dbh-sleep-accent) 15%, transparent); fill: none; stroke: var(--dbh-sleep-accent); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  .dbh-sleep-brand span { display: grid; line-height: 1.2; min-width: 0; }
  .dbh-sleep-brand b { font: 650 16px/1.1 var(--dbh-sleep-round); letter-spacing: -0.01em; }
  .dbh-sleep-brand small { font-size: 11px; color: var(--dbh-sleep-muted); }
  .dbh-sleep-nav { display: grid; gap: 2px; }
  .dbh-sleep-nav button { display: flex; align-items: center; gap: 10px; height: 36px; padding: 0 10px; border-radius: 9px; font-weight: 560; color: var(--dbh-sleep-muted); transition: background-color 160ms, color 160ms; }
  .dbh-sleep-nav button:hover { color: var(--dbh-sleep-ink); background: color-mix(in oklch, var(--dbh-sleep-ink) 5%, transparent); }
  .dbh-sleep-nav [aria-selected="true"] { color: var(--dbh-sleep-ink); background: var(--dbh-sleep-card); box-shadow: inset 0 0 0 1px var(--dbh-sleep-line); }
  .dbh-sleep-nav svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  .dbh-sleep-nav [aria-selected="true"] svg { stroke: var(--dbh-sleep-accent); }
  .dbh-sleep-fort { display: grid; gap: 10px; padding: 0 4px; }
  .dbh-sleep-fort dl { display: grid; gap: 10px; }
  .dbh-sleep-fort div { display: grid; gap: 1px; }
  .dbh-sleep-fort dt { font-size: 11.5px; color: var(--dbh-sleep-muted); }
  .dbh-sleep-fort dd { font: 600 17px/1.2 var(--dbh-sleep-round); font-variant-numeric: tabular-nums; letter-spacing: -0.01em; }
  .dbh-sleep-fort dd small { font-size: 12px; font-weight: 500; color: var(--dbh-sleep-muted); }
  .dbh-sleep-foot { margin-top: auto; padding: 0 4px; font-size: 11px; color: var(--dbh-sleep-faint); }

  /* ---------- main ---------- */
  .dbh-sleep-main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); }
  .dbh-sleep-head { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 12px 20px; padding: 16px 20px 12px; }
  .dbh-sleep-title { display: flex; align-items: center; gap: 8px; min-width: 0; }
  .dbh-sleep-tt { display: grid; gap: 2px; min-width: 0; }
