const pad = n => String(Math.floor(n)).padStart(2, '0');
const E = 144, T0 = 21 * 60;                       // 144 five-minute epochs, 21:00 → 09:00
const clockE = e => { const m = (T0 + e * 5) % 1440; return pad(m / 60) + ':' + pad(m % 60); };
const dur = m => (m = Math.round(m)) >= 60 ? `${Math.floor(m / 60)}h ${pad(m % 60)}m` : `${m}m`;
const DAY = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const fmtD = d => `${DAY[d.getDay()]} ${d.getDate()} ${MON[d.getMonth()]}`;
const STAGES = ['Awake', 'REM', 'Light', 'Deep'], SVAR = ['awake', 'rem', 'light', 'deep'];

/* ---------- fourteen nights on one shared epoch grid ---------- */
function stats(st, bedE, outE) {
  let tst = 0, deep = 0, light = 0, rem = 0, first = -1, last = -1;
  for (let e = bedE; e < outE; e++) {
    const v = st[e];
    if (v >= 1) { tst++; if (first < 0) first = e; last = e; }
    if (v === 3) deep++; else if (v === 2) light++; else if (v === 1) rem++;
  }
  let waso = 0, wakes = 0, cycles = 0;
  for (let e = first; e <= last; e++) if (st[e] === 0) { waso++; if (st[e - 1] !== 0) wakes++; }
  for (let e = bedE; e < outE; e++) if (st[e] === 1 && st[e - 1] !== 1) cycles++;
  const tib = (outE - bedE) * 5;
  return { firstE: first, lastE: last, tib, tst: tst * 5, deep: deep * 5, light: light * 5, rem: rem * 5, awake: tib - tst * 5, lat: (first - bedE) * 5, waso: waso * 5, wakes, cycles, eff: tst * 5 / tib };
}
const r = rng(1709);
const nights = [];
for (let n = 0; n < 14; n++) {
  const d = new Date(2026, 8, 18 + n), d2 = new Date(2026, 8, 19 + n);
  const wknd = d.getDay() === 5 || d.getDay() === 6;
  const bedM = (wknd ? 23 * 60 + 25 : 22 * 60 + 40) + Math.round((r() - 0.5) * 56);
  const bedE = Math.round((bedM - T0) / 5);
  const lat = 1 + Math.floor(r() * 4) + (n === 9 ? 3 : 0);
  const wakeM = 24 * 60 + (wknd ? 8 * 60 + 5 : 6 * 60 + 45) + Math.round((r() - 0.5) * 36);
  const wakeE = Math.min(140, Math.round((wakeM - T0) / 5));
  const outE = Math.min(E, wakeE + 1 + Math.floor(r() * 3));
  const st = new Array(E).fill(-1);
  for (let e = bedE; e < bedE + lat; e++) st[e] = 0;
  let e = bedE + lat, k = 0;
  while (e < wakeE) {
    const len = 17 + Math.floor(r() * 5);
    const deep = k === 0 ? 5 + Math.floor(r() * 3) : k === 1 ? 3 + Math.floor(r() * 3) : k === 2 ? Math.floor(r() * 3) : (r() < 0.25 ? 1 : 0);
    const rem = k === 0 ? 1 + Math.floor(r() * 2) : k === 1 ? 3 + Math.floor(r() * 2) : k === 2 ? 4 + Math.floor(r() * 2) : 5 + Math.floor(r() * 3);
    const light = Math.max(4, len - deep - rem), pre = Math.ceil(light * 0.55);
    const seq = [].concat(Array(pre).fill(2), Array(deep).fill(3), Array(light - pre).fill(2), Array(rem).fill(1));
    for (const s of seq) { if (e >= wakeE) break; st[e++] = s; }
    if (e < wakeE && r() < 0.42) { st[e++] = 0; if (e < wakeE && r() < 0.3) st[e++] = 0; }
    k++;
  }
  if (n === 9) for (let x = bedE + lat + 52; x < bedE + lat + 59; x++) st[x] = 0;   // the 3 a.m. wake-up
  for (let x = wakeE; x < outE; x++) st[x] = 0;
