const AVG = {};
['tst', 'eff', 'lat', 'waso', 'deep', 'rem', 'light', 'awake', 'bedE', 'outE'].forEach(k => { AVG[k] = avg(k); });
const bedSD = Math.sqrt(nights.reduce((a, x) => a + ((x.bedE - AVG.bedE) * 5) ** 2, 0) / nights.length);

const f = k => $(`[data-f="${k}"]`);
