f('eff').textContent = Math.round(AVG.eff * 100) + '%';
f('sd').innerHTML = `±${Math.round(bedSD)} <small>min</small>`;
f('dr').innerHTML = `${dur(AVG.deep)} <small>/</small> ${dur(AVG.rem)}`;

let cur = nights.length - 1, view = 'night';

/* ---------- night strip (header) ---------- */
const strip = $('.dbh-sleep-strip');
