  --dbh-rings-fresh: var(--dbh-rings-train);
  --dbh-rings-risk: oklch(0.58 0.2 25);
  --dbh-rings-run: var(--dbh-rings-burn);
  --dbh-rings-ride: var(--dbh-rings-steps);
  --dbh-rings-swim: oklch(0.66 0.11 205);
