  /* ---------- side ---------- */
  .dbh-rings-side { grid-area: side; min-height: 0; overflow: auto; display: flex; flex-direction: column; gap: 20px; padding: 20px 14px 16px; border-right: 1px solid var(--dbh-rings-line); background: var(--dbh-rings-sunk); scrollbar-width: thin; }
  .dbh-rings-brand { display: flex; align-items: center; gap: 9px; padding: 0 4px; }
  .dbh-rings-brand svg { width: 28px; height: 28px; fill: none; stroke: var(--dbh-rings-burn); stroke-width: 2; }
  .dbh-rings-brand span { display: grid; line-height: 1.15; }
  .dbh-rings-brand b { font-size: 15px; font-weight: 750; letter-spacing: -0.02em; }
