  .dbh-rings-nav { display: grid; gap: 2px; }
  .dbh-rings-nav button { display: flex; align-items: center; gap: 10px; height: 36px; padding: 0 10px; border-radius: 9px; font-weight: 580; color: var(--dbh-rings-muted); transition: background-color 150ms, color 150ms; }
  .dbh-rings-nav button:hover { color: var(--dbh-rings-ink); background: color-mix(in oklch, var(--dbh-rings-ink) 5%, transparent); }
  .dbh-rings-nav [aria-selected="true"] { color: var(--dbh-rings-paper); background: var(--dbh-rings-ink); }
