const N = 182;                                            // 26 weeks ending Thu 1 Oct 2026
const dateOf = i => new Date(2026, 9, 1 - (N - 1 - i));
const fmtD = d => `${DAY[d.getDay()]} ${d.getDate()} ${MON[d.getMonth()]}`;
const fmtS = d => `${d.getDate()} ${MON[d.getMonth()]}`;
const hm = m => (m = Math.round(m)) >= 60 ? `${Math.floor(m / 60)}h ${String(m % 60).padStart(2, '0')}m` : `${m}m`;
const num = n => Math.round(n).toLocaleString('en-US');
const RACE = new Date(2026, 9, 11), TAPER = N - 10;

/* ---------- 26 weeks of sessions from a weekly template, progressive with recovery weeks ---------- */
const SP = {
  run: { name: 'Run', icon: '<circle cx="14" cy="4.5" r="1.8"/><path d="M6 21l3.5-5.5 3 2V12l-3-2-3 2.5M12.5 12l3.5 2.5 3.5-.5M9.5 10l3.5-3 2.5 3"/>' },
  ride: { name: 'Ride', icon: '<circle cx="5.5" cy="16.5" r="3.5"/><circle cx="18.5" cy="16.5" r="3.5"/><path d="M5.5 16.5l4-8h6l3 8M9.5 8.5l3 8h-7M14 5h2.5l-1 3.5"/>' },
  swim: { name: 'Swim', icon: '<path d="M2 17c2 0 2-1.5 4-1.5s2 1.5 4 1.5 2-1.5 4-1.5 2 1.5 4 1.5 2-1.5 4-1.5"/><path d="M8 13l3-5 4 2.5"/><circle cx="17" cy="7" r="1.8"/>' },
  gym: { name: 'Strength', icon: '<path d="M6.5 6.5v11M17.5 6.5v11M3.5 9v6M20.5 9v6M6.5 12h11"/>' }
};
// [sport, minutes, title, tss/min, km per min (or 0), kcal/min, avg HR]
const TPL = [
  [['gym', 40, 'Strength · lower body', 0.6, 0, 5.8, 108]],
  [['run', 55, 'Track intervals · 6 × 800 m', 1.4, 1 / 4.9, 12.4, 158]],
  [['ride', 75, 'Endurance ride', 0.82, 27.5 / 60, 9.2, 133], ['swim', 45, 'Technique swim', 0.78, 2.3 / 60, 8.6, 127]],
  [['run', 50, 'Tempo run · 3 × 10 min', 1.3, 1 / 4.6, 12.8, 162]],
  [['swim', 40, 'Easy swim', 0.74, 2.2 / 60, 8.2, 124]],
  [['run', 95, 'Long run', 1.12, 1 / 5.4, 11.6, 146]],
  [['ride', 110, 'Group ride', 0.84, 28.5 / 60, 9.4, 136]]
];
const r = rng(2611);
const DAYS = [], WO = [];
const dow0 = (dateOf(0).getDay() + 6) % 7;
for (let i = 0; i < N; i++) {
  const d = dateOf(i), dow = (d.getDay() + 6) % 7, wk = Math.floor((i + dow0) / 7);
  let f = 0.8 + 0.38 * (i / (N - 1));
  if (wk % 4 === 3) f *= 0.66;
  if (i >= TAPER) f *= 0.6;
  const day = { i, d, dow, wk, wo: [], bg: Math.round(205 + r() * 170) };
  let opts = TPL[dow];
  if (dow === 2) opts = [opts[wk % 2]];
  if (dow === 4 && r() < 0.45) opts = [];
  if (dow === 6 && wk % 2 === 0) opts = [opts[0], ['gym', 25, 'Mobility & core', 0.5, 0, 4.8, 102]];
  opts.forEach(([sp, min, title, rate, kpm, kcal, hr]) => {
    if (r() < 0.06) return;                                   // a missed session now and then
    const m = Math.round(sp === 'gym' ? min : min * f * (0.92 + r() * 0.16));
    const w = { day: i, d, sp, title, min: m, tss: Math.round(m * rate * (0.92 + r() * 0.16)), km: kpm ? +(m * kpm * (0.95 + r() * 0.1)).toFixed(1) : 0, kcal: Math.round(m * kcal), hr: Math.round(hr + (r() - 0.5) * 8) };
    day.wo.push(w); WO.push(w);
  });
  const runKm = day.wo.filter(w => w.sp === 'run').reduce((a, w) => a + w.km, 0);
  day.burn = day.bg + day.wo.reduce((a, w) => a + w.kcal, 0);
  day.train = day.wo.reduce((a, w) => a + w.min, 0);
  day.steps = Math.round(4900 + r() * 3900 + runKm * 950);
  DAYS.push(day);
}

/* ---------- state ---------- */
let range = 42, sel = N - 1, view = 'ov';
const on = new Set(['run', 'ride', 'swim', 'gym']);
const tssOf = i => DAYS[i].wo.reduce((a, w) => a + (on.has(w.sp) ? w.tss : 0), 0);
let P = [];
function computePMC() {
  const t = DAYS.map((_, i) => tssOf(i));
  const mean = n => t.slice(0, n).reduce((a, b) => a + b, 0) / n;
  let ctl = mean(42), atl = mean(7);
  P = t.map(tss => { const o = { tss, ctl, atl, tsb: ctl - atl }; ctl += (tss - ctl) / 42; atl += (tss - atl) / 7; return o; });
  // P[i].ctl/atl are the morning values; form uses them, the evening value includes the day's load
  P.forEach((p, i) => { p.ctlE = p.ctl + (p.tss - p.ctl) / 42; p.atlE = p.atl + (p.tss - p.atl) / 7; });
}
const zone = v => v > 5 ? 'fresh' : v >= -10 ? 'neutral' : v >= -30 ? 'build' : 'risk';
const ZNAME = { fresh: 'Fresh', neutral: 'Neutral', build: 'Building', risk: 'Overload risk' };
const sgn = v => (v > 0.5 ? '+' : v < -0.5 ? '−' : '') + Math.abs(Math.round(v));

/* ---------- header ---------- */
function paintHead() {
  const p = P[sel], d = DAYS[sel].d;
  const toRace = Math.round((RACE - d) / 864e5);
  const block = sel >= TAPER ? 'Taper' : DAYS[sel].wk % 4 === 3 ? 'Recovery week' : 'Build block';
  $('[data-k="sub"]').textContent = `${fmtD(d)} · ${block} · ${toRace} days to race`;
  $('[data-k="ctl"]').textContent = Math.round(p.ctlE);
  $('[data-k="tsb"]').textContent = sgn(p.tsb);
}

/* ---------- performance chart ---------- */
const chart = $('.dbh-rings-chart'), psvg = $('.dbh-rings-psvg'), tip = $('.dbh-rings-tip');
let C = null, hoverI = -1;
const nice = v => { const p = Math.pow(10, Math.floor(Math.log10(v))); return Math.ceil(v / p / 2) * 2 * p; };
function renderPMC() {
  const W = chart.clientWidth, H = chart.clientHeight;
  if (W < 80 || H < 80) { C = null; return; }
  const s0 = N - range, L = 34, Rm = 10, top = 6, bot = 20, gap = 16;
  const ph = (H - top - bot - gap) * 0.68, fh = H - top - bot - gap - ph;
  const pw = W - L - Rm, step = pw / range;
  const x = i => L + (i - s0 + 0.5) * step;
  const vis = P.slice(s0);
  const yMax = nice(Math.max(...vis.map(p => Math.max(p.ctlE, p.atlE))) * 1.08);
  const y = v => top + ph - v / yMax * ph;
  const tMax = Math.max(160, ...vis.map(p => p.tss));
  const yt = v => top + ph - v / tMax * ph * 0.42;
  const fMax = Math.max(15, ...vis.map(p => Math.abs(p.tsb))) * 1.12;
  const f0 = top + ph + gap + fh / 2;
  const yf = v => f0 - v / fMax * (fh / 2);
  const bw = Math.max(1, step - (range > 100 ? 0.6 : 1.6));
  let out = '';
  for (let k = 0; k <= 4; k++) {
    const v = yMax / 4 * k;
    out += `<line class="dbh-rings-grid" x1="${L}" x2="${W - Rm}" y1="${y(v).toFixed(1)}" y2="${y(v).toFixed(1)}"/><text x="${L - 6}" y="${(y(v) + 3.5).toFixed(1)}" text-anchor="end">${Math.round(v)}</text>`;
  }
  // form zones behind the form bars
  [[fMax, 5, 'fresh', 'var(--dbh-rings-fresh)'], [-10, -30, 'build', 'var(--dbh-rings-burn)'], [-30, -fMax, 'risk', 'var(--dbh-rings-risk)']].forEach(([a, b, z, c]) => {
    const ya = yf(Math.min(fMax, a)), yb = yf(Math.max(-fMax, b));
    if (yb - ya > 1) out += `<rect class="dbh-rings-zone" x="${L}" width="${pw}" y="${ya.toFixed(1)}" height="${(yb - ya).toFixed(1)}" style="fill:${c}"/><text class="dbh-rings-zl" x="${W - Rm - 4}" y="${(ya + 11).toFixed(1)}" text-anchor="end" style="fill:${c}">${ZNAME[z]}</text>`;
  });
  out += `<line class="dbh-rings-zero" x1="${L}" x2="${W - Rm}" y1="${f0}" y2="${f0}"/><text x="${L - 6}" y="${f0 + 3.5}" text-anchor="end">0</text>`;
  out += `<text x="${L - 6}" y="${(top + ph + gap + 9).toFixed(1)}" text-anchor="end">${'+' + Math.round(fMax)}</text>`;
  // x ticks
  const every = range <= 42 ? (W < 460 ? 14 : 7) : range <= 84 ? (W < 460 ? 28 : 14) : 0;
  for (let i = s0; i < N; i++) {
    const d = DAYS[i].d;
    if (every ? (DAYS[i].dow === 0 && (N - 1 - i) % every < 7) : d.getDate() === 1) {
      out += `<line class="dbh-rings-grid" x1="${x(i).toFixed(1)}" x2="${x(i).toFixed(1)}" y1="${top}" y2="${H - bot}" style="stroke-dasharray:2 3"/><text x="${x(i).toFixed(1)}" y="${H - 5}" text-anchor="middle">${every ? fmtS(d) : MON[d.getMonth()]}</text>`;
    }
  }
  out += vis.map((p, k) => p.tss ? `<rect class="dbh-rings-tss" style="--i:${k}" x="${(x(s0 + k) - bw / 2).toFixed(2)}" width="${bw.toFixed(2)}" y="${yt(p.tss).toFixed(1)}" height="${(top + ph - yt(p.tss)).toFixed(1)}" rx="${Math.min(1.5, bw / 3)}"/>` : '').join('');
  out += vis.map((p, k) => {
    const v = p.tsb, ya = Math.min(yf(v), f0), h = Math.abs(yf(v) - f0);
    return `<rect class="dbh-rings-tsb" data-z="${zone(v)}"${v < 0 ? ' data-neg' : ''} style="--i:${k}" x="${(x(s0 + k) - bw / 2).toFixed(2)}" width="${bw.toFixed(2)}" y="${ya.toFixed(1)}" height="${Math.max(0.5, h).toFixed(1)}"/>`;
  }).join('');
  const line = key => vis.map((p, k) => (k ? 'L' : 'M') + x(s0 + k).toFixed(1) + ',' + y(p[key]).toFixed(1)).join('');
  const ctlLine = line('ctlE');
  out += `<path class="dbh-rings-ctlarea" d="${ctlLine}L${x(N - 1).toFixed(1)},${top + ph}L${x(s0).toFixed(1)},${top + ph}Z"/>`;
  out += `<path class="dbh-rings-line" data-l="atl" pathLength="1" d="${line('atlE')}"/><path class="dbh-rings-line" data-l="ctl" pathLength="1" d="${ctlLine}"/>`;
  out += `<g class="dbh-rings-selg"><line class="dbh-rings-sel" y1="${top}" y2="${H - bot}"/><circle class="dbh-rings-seldot" r="4"/></g>`;
  out += `<g class="dbh-rings-xg" style="opacity:0"><line class="dbh-rings-xh" y1="${top}" y2="${H - bot}"/><circle class="dbh-rings-xd" r="4" style="fill:var(--dbh-rings-ctl)"/><circle class="dbh-rings-xd" r="3.5" style="fill:var(--dbh-rings-atl)"/></g>`;
  psvg.setAttribute('viewBox', `0 0 ${W} ${H}`);
  psvg.innerHTML = out;
  C = { W, H, L, Rm, s0, step, x, y, yf, top, ph };
  paintSel();
}
function paintSel() {
  if (!C) return;
  const g = $('.dbh-rings-selg', psvg);
  const inRange = sel >= C.s0;
  g.style.display = inRange ? '' : 'none';
  if (!inRange) return;
  const xi = C.x(sel).toFixed(1);
  $('line', g).setAttribute('x1', xi); $('line', g).setAttribute('x2', xi);
  const c = $('circle', g); c.setAttribute('cx', xi); c.setAttribute('cy', C.y(P[sel].ctlE).toFixed(1));
}
function hoverAt(i) {
  if (!C) return;
  i = Math.max(C.s0, Math.min(N - 1, i));
  hoverI = i;
  const p = P[i], day = DAYS[i], xi = C.x(i);
  const g = $('.dbh-rings-xg', psvg);
  g.style.opacity = 1;
  const [ln, c1, c2] = g.children;
  ln.setAttribute('x1', xi); ln.setAttribute('x2', xi);
  c1.setAttribute('cx', xi); c1.setAttribute('cy', C.y(p.ctlE));
  c2.setAttribute('cx', xi); c2.setAttribute('cy', C.y(p.atlE));
  const sess = day.wo.filter(w => on.has(w.sp));
  tip.innerHTML = `<b>${fmtD(day.d)}</b>
    <span><i style="--kc:var(--dbh-rings-ctl)"></i>Fitness<em>${Math.round(p.ctlE)}</em></span>
    <span><i style="--kc:var(--dbh-rings-atl)"></i>Fatigue<em>${Math.round(p.atlE)}</em></span>
    <span><i style="--kc:var(--dbh-rings-fresh)"></i>Form<em>${sgn(p.tsb)} · ${ZNAME[zone(p.tsb)]}</em></span>
    <span><i style="--kc:var(--dbh-rings-paper)"></i>Load<em>${p.tss}</em></span>
    <small>${sess.length ? sess.map(w => `${w.title} · ${hm(w.min)}`).join('<br>') : 'Rest day'}</small>`;
  tip.hidden = false;
  const tw = tip.offsetWidth, th = tip.offsetHeight;
  const left = xi + 14 + tw > C.W ? xi - 14 - tw : xi + 14;
  tip.style.translate = `${Math.max(0, left).toFixed(0)}px ${Math.max(0, Math.min(C.H - th, C.y(p.ctlE) - th / 2)).toFixed(0)}px`;
}
function hideHover() { hoverI = -1; tip.hidden = true; const g = $('.dbh-rings-xg', psvg); if (g) g.style.opacity = 0; }
const idxAt = e => { const rc = psvg.getBoundingClientRect(); return C.s0 + Math.floor((e.clientX - rc.left - C.L) / C.step); };
psvg.addEventListener('pointermove', e => { if (C) hoverAt(idxAt(e)); });
psvg.addEventListener('pointerleave', () => { if (document.activeElement !== psvg) hideHover(); });
psvg.addEventListener('click', e => { if (C) select(Math.max(C.s0, Math.min(N - 1, idxAt(e)))); });
psvg.addEventListener('focus', () => hoverAt(hoverI >= 0 ? hoverI : sel));
psvg.addEventListener('blur', hideHover);
psvg.addEventListener('keydown', e => {
  if (!C) return;
  let i = hoverI >= 0 ? hoverI : sel;
  if (e.key === 'ArrowLeft') i -= e.shiftKey ? 7 : 1;
  else if (e.key === 'ArrowRight') i += e.shiftKey ? 7 : 1;
  else if (e.key === 'Home') i = C.s0;
  else if (e.key === 'End') i = N - 1;
  else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); select(i); return; }
  else if (e.key === 'Escape') { hideHover(); return; }
  else return;
  e.preventDefault(); hoverAt(i);
});
new ResizeObserver(() => { if (view === 'ov' && (!C || C.W !== chart.clientWidth || C.H !== chart.clientHeight)) renderPMC(); }).observe(chart);

/* ---------- rings and counters: registered properties do the tweening ---------- */
const GOAL = { burn: 650, train: 45, steps: 10000 };
let ringsReady = false;
function paintRings() {
  const day = DAYS[sel];
  $('[data-k="dayh"]').textContent = fmtD(day.d);
  let closed = 0;
  ['burn', 'train', 'steps'].forEach(k => {
    const v = day[k], frac = v / GOAL[k];
    if (frac >= 1) closed++;
    const ring = $(`.dbh-rings-ring[data-r="${k}"]`);
    const apply = () => {
      ring.style.setProperty('--dbh-rings-a', (Math.min(1, frac) * 360).toFixed(1) + 'deg');
      ring.toggleAttribute('data-over', frac >= 1);
      const c = $(`[data-c="${k}"]`);
      if (k === 'steps') { c.style.setProperty('--dbh-rings-k', Math.floor(v / 1000)); c.style.setProperty('--dbh-rings-n', v % 1000); }
      else c.style.setProperty('--dbh-rings-n', v);
    };
    if (ringsReady) apply(); else setTimeout(() => { if (!root.isConnected) return; apply(); }, 120);
    $(`.dbh-rings-goals li[data-r="${k}"]`).setAttribute('aria-label', `${k}: ${num(v)} of ${num(GOAL[k])}`);
  });
  ringsReady = true;
  const pill = $('[data-k="closed"]');
  pill.textContent = `${closed} of 3 closed`;
  pill.toggleAttribute('data-all', closed === 3);
}

/* ---------- calendar ---------- */
const cal = $('.dbh-rings-calgrid');
let cells = [];
function renderCal() {
  const weeks = 26;
  const lastMon = N - 1 - DAYS[N - 1].dow;
  const firstMon = lastMon - (weeks - 1) * 7;
  cal.style.setProperty('--weeks', weeks);
  let out = '<span aria-hidden="true"></span>' + ['Mon', '', 'Wed', '', 'Fri', '', 'Sun'].map(t => `<span class="dbh-rings-dow" aria-hidden="true">${t}</span>`).join('');
  let k = 0;
  for (let w = 0; w < weeks; w++) {
    const m0 = firstMon + w * 7;
    const d0 = dateOf(m0);
    const hasFirst = w === 0 || [0, 1, 2, 3, 4, 5, 6].some(j => dateOf(m0 + j).getDate() === 1);
    const lbl = hasFirst ? MON[(w === 0 ? d0 : dateOf(m0 + [0, 1, 2, 3, 4, 5, 6].find(j => dateOf(m0 + j).getDate() === 1))).getMonth()] : '';
    out += `<div role="row" style="display:contents"><span class="dbh-rings-mon" aria-hidden="true">${weeks > 12 && w % 2 && !hasFirst ? '' : lbl}</span>`;
    for (let j = 0; j < 7; j++) {
      const i = m0 + j;
      if (i >= N) { out += `<span class="dbh-rings-cell" role="gridcell" aria-disabled="true"></span>`; continue; }
      const t = tssOf(i);
      out += `<span class="dbh-rings-cell" role="gridcell" tabindex="-1" data-i="${i}" aria-selected="false" style="--i:${k++};--v:${Math.min(1, Math.pow(t / 160, 0.85)).toFixed(3)}"${t ? '' : ' data-rest'} aria-label="${fmtD(DAYS[i].d)}, load ${t}" title="${fmtD(DAYS[i].d)} · load ${t}"></span>`;
    }
    out += '</div>';
  }
  cal.innerHTML = out;
  cells = $$('[data-i]', cal);
  paintCalSel();
  paintCalRange();
}
// the calendar always shows 26 weeks; the chosen range is lit, the rest recedes
function paintCalRange() { cells.forEach(c => c.toggleAttribute('data-out', +c.dataset.i < N - range)); }
function paintCalSel() {
  cells.forEach(c => { const s = +c.dataset.i === sel; c.setAttribute('aria-selected', s); c.tabIndex = s ? 0 : -1; });
}
cal.addEventListener('click', e => { const c = e.target.closest('[data-i]'); if (c) select(+c.dataset.i); });
cal.addEventListener('keydown', e => {
  const d = { ArrowUp: -1, ArrowDown: 1, ArrowLeft: -7, ArrowRight: 7 }[e.key];
  let i = sel;
  if (d) i += d; else if (e.key === 'Home') i = N - range; else if (e.key === 'End') i = N - 1; else return;
  e.preventDefault();
  i = Math.max(0, Math.min(N - 1, i));
  select(i);
  const c = cells.find(x => +x.dataset.i === i);
  if (c) c.focus();
});

/* ---------- week card ---------- */
function paintWeek() {
  const mon = sel - DAYS[sel].dow;
  const ws = WO.filter(w => w.day >= mon && w.day < mon + 7 && on.has(w.sp));
  const min = ws.reduce((a, w) => a + w.min, 0), tss = ws.reduce((a, w) => a + w.tss, 0);
  $('[data-k="weekh"]').textContent = `Week of ${fmtS(dateOf(mon))}`;
  const ramp = P[sel].ctlE - P[Math.max(0, sel - 7)].ctlE;
  $('[data-k="ramp"]').textContent = `fitness ${sgn(ramp)} / wk`;
  $('.dbh-rings-wtot').innerHTML = `<span><b>${hm(min)}</b></span><span><b>${tss}</b><small>load</small></span><span><b>${ws.length}</b><small>sessions</small></span>`;
  const sports = ['run', 'ride', 'swim', 'gym'].filter(s => on.has(s));
  const by = s => ws.filter(w => w.sp === s);
  $('.dbh-rings-wbar').innerHTML = sports.map(s => `<i data-sport="${s}" style="--v:${by(s).reduce((a, w) => a + w.min, 0)}"></i>`).join('');
  $('.dbh-rings-wlist').innerHTML = sports.map(s => {
    const l = by(s), m = l.reduce((a, w) => a + w.min, 0), km = l.reduce((a, w) => a + w.km, 0);
    return `<li data-sport="${s}"${l.length ? '' : ' data-none'}><span>${SP[s].name} <small style="display:inline">× ${l.length}</small></span><b>${hm(m)}</b><small>${km ? km.toFixed(1) + ' km' : '—'}</small></li>`;
  }).join('');
}

/* ---------- workouts table ---------- */
let sortK = 'date', sortDir = -1;
const tbody = $('.dbh-rings-table tbody'), tfoot = $('.dbh-rings-table tfoot');
function renderTable() {
  const rows = WO.filter(w => w.day >= N - range && on.has(w.sp));
  const key = { date: w => w.day * 10 + (w.sp === 'gym' ? 1 : 0), sport: w => w.sp + w.title, min: w => w.min, km: w => w.km, tss: w => w.tss, hr: w => w.hr }[sortK];
  rows.sort((a, b) => { const A = key(a), B = key(b); return (A < B ? -1 : A > B ? 1 : 0) * sortDir; });
  const maxT = Math.max(1, ...rows.map(w => w.tss));
  tbody.innerHTML = rows.length ? rows.map((w, i) => `<tr style="--i:${i}" data-day="${w.day}" tabindex="-1">
      <td>${fmtD(w.d)}</td>
      <td><span class="dbh-rings-sess" data-sport="${w.sp}"><svg viewBox="0 0 24 24" aria-hidden="true">${SP[w.sp].icon}</svg><span>${w.title} <small>· ${SP[w.sp].name}</small></span></span></td>
      <td class="dbh-rings-num">${hm(w.min)}</td>
      <td class="dbh-rings-num">${w.km ? w.km.toFixed(1) + ' km' : '—'}</td>
      <td class="dbh-rings-num"><i class="dbh-rings-tbar" style="--v:${(w.tss / maxT).toFixed(3)}"></i>${w.tss}</td>
      <td class="dbh-rings-num">${w.hr}</td></tr>`).join('')
    : `<tr><td colspan="6" class="dbh-rings-empty">No sessions for the selected sports in this range.</td></tr>`;
  const tm = rows.reduce((a, w) => a + w.min, 0);
  const hrW = tm ? rows.reduce((a, w) => a + w.hr * w.min, 0) / tm : 0;
  tfoot.innerHTML = `<tr><td>${rows.length} sessions</td><td></td><td class="dbh-rings-num">${hm(tm)}</td><td class="dbh-rings-num">${rows.reduce((a, w) => a + w.km, 0).toFixed(1)} km</td><td class="dbh-rings-num">${num(rows.reduce((a, w) => a + w.tss, 0))}</td><td class="dbh-rings-num">${hrW ? Math.round(hrW) : '—'}</td></tr>`;
  $$('.dbh-rings-table th').forEach(th => {
    const b = $('[data-sort]', th);
    if (b.dataset.sort === sortK) th.setAttribute('aria-sort', sortDir > 0 ? 'ascending' : 'descending'); else th.removeAttribute('aria-sort');
  });
}
$('.dbh-rings-table thead').addEventListener('click', e => {
  const b = e.target.closest('[data-sort]');
  if (!b) return;
  sortDir = b.dataset.sort === sortK ? -sortDir : (b.dataset.sort === 'sport' ? 1 : -1);
  sortK = b.dataset.sort;
  renderTable();
});
tbody.addEventListener('click', e => { const tr = e.target.closest('tr[data-day]'); if (tr) { select(+tr.dataset.day); pickTab($('[data-view="ov"]')); } });

/* ---------- sidebar counts, filters, range, tabs ---------- */
function paintCounts() {
  $$('.dbh-rings-sports label').forEach(l => { $('small', l).textContent = WO.filter(w => w.sp === l.dataset.sport && w.day >= N - range).length; });
}
$('.dbh-rings-sports').addEventListener('change', e => {
  const t = e.target;
  if (t.checked) on.add(t.value); else on.delete(t.value);
  computePMC(); renderCal(); paintAll();
});
function roving(group, sel, attr, onPick) {
  const items = $$(sel, group);
  const pick = t => { items.forEach(x => { const o = x === t; x.setAttribute(attr, o); x.tabIndex = o ? 0 : -1; }); onPick(t); };
  group.addEventListener('click', e => { const t = e.target.closest(sel); if (t) pick(t); });
  group.addEventListener('keydown', e => {
    const i = items.indexOf(document.activeElement);
    if (i < 0) return;
    let j = -1;
    if (e.key === 'ArrowRight' || e.key === 'ArrowDown') j = (i + 1) % items.length;
    else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') j = (i - 1 + items.length) % items.length;
    if (j < 0) return;
    e.preventDefault(); items[j].focus(); pick(items[j]);
  });
  return pick;
}
roving($('.dbh-rings-seg'), '[role="radio"]', 'aria-checked', t => {
  range = +t.dataset.range;
  if (sel < N - range) sel = N - 1;
  paintCalRange(); paintCalSel(); paintAll();
});
const pickTab = roving($('.dbh-rings-nav'), '[role="tab"]', 'aria-selected', t => {
  view = t.dataset.view;
  $('.dbh-rings-ov').hidden = view !== 'ov';
  $('.dbh-rings-wo').hidden = view !== 'wo';
  if (view === 'ov') renderPMC(); else renderTable();
});

function select(i) {
  sel = i;
  paintHead(); paintSel(); paintCalSel(); paintRings(); paintWeek();
  if (hoverI >= 0) hoverAt(hoverI);
}
function paintAll() {
  paintHead(); paintCounts(); paintRings(); paintWeek();
  if (view === 'ov') renderPMC(); else renderTable();
}
computePMC();
renderCal();
paintAll();

css:
@property --dbh-clinic-t { syntax: "<number>"; inherits: true; initial-value: 670; }
@keyframes dbh-clinic-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbh-clinic-wipe { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes dbh-clinic-grow { from { scale: 1 0; } }
@keyframes dbh-clinic-pop { from { opacity: 0; scale: 0; } }

.dbh-clinic {
  /* re-theme with these */
  --dbh-clinic-paper: oklch(0.978 0.005 205);
  --dbh-clinic-ink: oklch(0.27 0.035 228);
  --dbh-clinic-accent: oklch(0.6 0.11 188);
  --dbh-clinic-wait: oklch(0.81 0.13 76);
  --dbh-clinic-late: oklch(0.6 0.19 30);
  /* derived */
  --dbh-clinic-card: color-mix(in oklch, var(--dbh-clinic-paper), white 75%);
  --dbh-clinic-sunk: color-mix(in oklch, var(--dbh-clinic-paper), var(--dbh-clinic-ink) 5%);
  --dbh-clinic-line: color-mix(in oklch, var(--dbh-clinic-ink) 10%, transparent);
  --dbh-clinic-line2: color-mix(in oklch, var(--dbh-clinic-ink) 20%, transparent);
  --dbh-clinic-muted: color-mix(in oklch, var(--dbh-clinic-ink) 62%, var(--dbh-clinic-paper));
  --dbh-clinic-faint: color-mix(in oklch, var(--dbh-clinic-ink) 42%, var(--dbh-clinic-paper));
  --dbh-clinic-room: color-mix(in oklch, var(--dbh-clinic-accent) 32%, var(--dbh-clinic-card));
  --dbh-clinic-out: color-mix(in oklch, var(--dbh-clinic-ink) 22%, var(--dbh-clinic-card));
  --dbh-clinic-ease: cubic-bezier(0.22, 0.8, 0.22, 1);
  --dbh-clinic-spring: linear(0, 0.02, 0.08 4%, 0.45 12%, 0.86 20%, 1.04 27%, 1.07 32%, 1.04 39%, 1 50%, 0.995 62%, 1);
  --dbh-clinic-mono: ui-monospace, Menlo, Consolas, monospace;

  width: 100%;
  height: var(--dbh-clinic-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 16px;
  background: var(--dbh-clinic-paper);
  color: var(--dbh-clinic-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dbh-clinic-accent);
  box-shadow: inset 0 0 0 1px var(--dbh-clinic-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbh-clinic-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul, & ol, & dl, & dd { list-style: none; margin: 0; padding: 0; }
  & fieldset { border: 0; margin: 0; padding: 0; min-width: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dbh-clinic-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.09em; text-transform: uppercase; color: var(--dbh-clinic-muted); }
  .dbh-clinic-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  .dbh-clinic-app { display: grid; height: 100%; grid-template-columns: 218px minmax(0, 1fr); grid-template-areas: "side main"; }

  /* ---------- side ---------- */
  .dbh-clinic-side { grid-area: side; min-height: 0; overflow: auto; display: flex; flex-direction: column; gap: 20px; padding: 20px 14px 16px; border-right: 1px solid var(--dbh-clinic-line); scrollbar-width: thin; }
  .dbh-clinic-brand { display: flex; align-items: center; gap: 10px; padding: 0 4px; }
  .dbh-clinic-brand svg { flex: none; width: 32px; height: 32px; padding: 6px; border-radius: 9px; background: var(--dbh-clinic-ink); fill: none; stroke: var(--dbh-clinic-paper); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  .dbh-clinic-brand span { display: grid; line-height: 1.2; }
  .dbh-clinic-brand b { font-size: 15px; font-weight: 700; letter-spacing: -0.015em; }
  .dbh-clinic-brand small { font-size: 11px; color: var(--dbh-clinic-muted); }
  .dbh-clinic-nav { display: grid; gap: 2px; }
  .dbh-clinic-nav button { display: flex; align-items: center; gap: 10px; height: 36px; padding: 0 10px; border-radius: 9px; font-weight: 580; color: var(--dbh-clinic-muted); transition: background-color 150ms, color 150ms; }
  .dbh-clinic-nav button:hover { color: var(--dbh-clinic-ink); background: var(--dbh-clinic-sunk); }
  .dbh-clinic-nav [aria-selected="true"] { color: var(--dbh-clinic-ink); background: var(--dbh-clinic-card); box-shadow: 0 0 0 1px var(--dbh-clinic-line), 0 1px 2px color-mix(in oklch, var(--dbh-clinic-ink) 8%, transparent); }
  .dbh-clinic-nav svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; }
  .dbh-clinic-nav [aria-selected="true"] svg { stroke: var(--dbh-clinic-accent); }
  .dbh-clinic-provs { display: grid; gap: 4px; }
  .dbh-clinic-provs legend { margin-bottom: 6px; padding: 0 4px; }
  .dbh-clinic-provs label { display: grid; grid-template-columns: 16px 1fr auto; align-items: center; gap: 8px; padding: 7px 8px; border-radius: 9px; cursor: pointer; transition: background-color 150ms, opacity 150ms; }
  .dbh-clinic-provs label:hover { background: var(--dbh-clinic-sunk); }
  .dbh-clinic-provs label:has(input:not(:checked)) { opacity: 0.5; }
  .dbh-clinic-provs label:has(:focus-visible) { outline: 2px solid var(--dbh-clinic-accent); outline-offset: 1px; }
  .dbh-clinic-provs input { margin: 0; width: 15px; height: 15px; }
  .dbh-clinic-provs input:focus-visible { outline: none; }
  .dbh-clinic-provs span { display: grid; line-height: 1.25; min-width: 0; }
  .dbh-clinic-provs b { font-size: 12.5px; font-weight: 600; line-height: 1.2; }
  .dbh-clinic-provs label { align-items: start; }
  .dbh-clinic-provs input, .dbh-clinic-lag { margin-top: 1px; }
  .dbh-clinic-provs small { font-size: 11px; color: var(--dbh-clinic-muted); }
  .dbh-clinic-lag { font: 600 11px var(--dbh-clinic-mono); font-variant-numeric: tabular-nums; padding: 2px 6px; border-radius: 6px; background: var(--dbh-clinic-sunk); color: var(--dbh-clinic-muted); transition: background-color 200ms, color 200ms; }
  .dbh-clinic-lag[data-tone="warn"] { background: color-mix(in oklch, var(--dbh-clinic-wait) 35%, var(--dbh-clinic-card)); color: var(--dbh-clinic-ink); }
  .dbh-clinic-lag[data-tone="late"] { background: var(--dbh-clinic-late); color: var(--dbh-clinic-card); }
  .dbh-clinic-legend { margin-top: auto; display: grid; gap: 6px; padding: 0 4px; font-size: 11.5px; color: var(--dbh-clinic-muted); }
  .dbh-clinic-legend li { display: flex; align-items: center; gap: 8px; }
  .dbh-clinic-legend li::before { content: ""; width: 18px; height: 9px; border-radius: 3px; }
  .dbh-clinic-legend [data-k="w"]::before { background: repeating-linear-gradient(135deg, var(--dbh-clinic-wait) 0 3px, color-mix(in oklch, var(--dbh-clinic-wait) 45%, var(--dbh-clinic-card)) 3px 6px); }
  .dbh-clinic-legend [data-k="r"]::before { background: var(--dbh-clinic-room); }
  .dbh-clinic-legend [data-k="p"]::before { background: var(--dbh-clinic-accent); }
  .dbh-clinic-legend [data-k="o"]::before { background: var(--dbh-clinic-out); }
  .dbh-clinic-legend [data-k="g"]::before { box-shadow: inset 0 0 0 1px var(--dbh-clinic-line2); background: repeating-linear-gradient(90deg, transparent 0 3px, var(--dbh-clinic-sunk) 3px 4px); }

  /* ---------- main ---------- */
  .dbh-clinic-main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto auto minmax(0, 1fr); }
  .dbh-clinic-head { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 12px 24px; padding: 18px 20px 12px; }
  .dbh-clinic-title { display: grid; gap: 4px; }
  .dbh-clinic-h { font-size: clamp(19px, 0.8rem + 1.3cqi, 26px); font-weight: 680; letter-spacing: -0.025em; line-height: 1.05; }
  .dbh-clinic-kpis { display: flex; flex-wrap: wrap; gap: 6px 22px; }
  .dbh-clinic-kpis div { display: grid; gap: 1px; animation: dbh-clinic-rise 520ms var(--dbh-clinic-ease) both; animation-delay: calc(var(--i) * 50ms); }
  .dbh-clinic-kpis dt { font-size: 11px; color: var(--dbh-clinic-muted); white-space: nowrap; }
  .dbh-clinic-kpis dd { font-size: 20px; font-weight: 700; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; line-height: 1.15; }
  .dbh-clinic-kpis dd small { font-size: 12px; font-weight: 500; color: var(--dbh-clinic-faint); margin-left: 2px; }
  .dbh-clinic-kpis dd[data-tone="warn"] { color: color-mix(in oklch, var(--dbh-clinic-wait), var(--dbh-clinic-ink) 45%); }
  .dbh-clinic-kpis dd[data-tone="late"] { color: var(--dbh-clinic-late); }

  .dbh-clinic-bar { display: flex; align-items: center; gap: 12px; margin: 0 20px 12px; padding: 8px 10px 8px 8px; border-radius: 14px; background: var(--dbh-clinic-card); box-shadow: 0 0 0 1px var(--dbh-clinic-line); }
  .dbh-clinic-play { flex: none; display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; background: var(--dbh-clinic-ink); color: var(--dbh-clinic-paper); transition: scale 220ms var(--dbh-clinic-spring), background-color 150ms; }
  .dbh-clinic-play:hover { background: color-mix(in oklch, var(--dbh-clinic-ink), var(--dbh-clinic-accent) 30%); }
  .dbh-clinic-play:active { scale: 0.9; }
  .dbh-clinic-play svg { width: 16px; height: 16px; fill: currentColor; }
  .dbh-clinic-play .dbh-clinic-i-pause, .dbh-clinic-play[aria-pressed="true"] .dbh-clinic-i-play { display: none; }
  .dbh-clinic-play[aria-pressed="true"] .dbh-clinic-i-pause { display: inline; }
  .dbh-clinic-scrub { flex: 1; min-width: 0; display: flex; }
  .dbh-clinic-scrub input { width: 100%; margin: 0; height: 22px; cursor: pointer; }
  .dbh-clinic-clock { min-width: 50px; font: 650 15px var(--dbh-clinic-mono); font-variant-numeric: tabular-nums; }
  .dbh-clinic-jumps { display: flex; gap: 2px; padding: 2px; border-radius: 9px; background: var(--dbh-clinic-sunk); }
  .dbh-clinic-jumps button { height: 26px; padding: 0 9px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--dbh-clinic-muted); transition: background-color 150ms, color 150ms; }
  .dbh-clinic-jumps button:hover { background: var(--dbh-clinic-card); color: var(--dbh-clinic-ink); }

  .dbh-clinic-view { min-height: 0; padding: 0 20px 18px; }
  .dbh-clinic-card { position: relative; min-width: 0; min-height: 0; border-radius: 14px; background: var(--dbh-clinic-card); box-shadow: 0 0 0 1px var(--dbh-clinic-line), 0 1px 2px color-mix(in oklch, var(--dbh-clinic-ink) 5%, transparent); }
  .dbh-clinic-cardhead { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 6px 12px; margin-bottom: 8px; }
  .dbh-clinic-cardhead h3 { font-size: 13px; font-weight: 680; }
  .dbh-clinic-note { font-size: 11.5px; color: var(--dbh-clinic-faint); }

  /* ---------- flow ---------- */
  .dbh-clinic-flow { display: grid; gap: 12px; grid-template-columns: minmax(0, 1fr) clamp(220px, 23cqi, 264px); }
  .dbh-clinic-gcard { display: grid; padding: 8px 12px 10px 4px; }
  .dbh-clinic-gscroll { min-height: 0; overflow: auto hidden; scrollbar-width: thin; scrollbar-color: var(--dbh-clinic-line2) transparent; }
  .dbh-clinic-gantt { --t0: 465; --span: 600; position: relative; height: 100%; min-width: 560px; display: grid; grid-template-columns: 118px minmax(0, 1fr); grid-template-rows: 24px repeat(var(--rows, 4), minmax(52px, 1fr)); }
  .dbh-clinic-gantt[data-glide] { transition: --dbh-clinic-t 900ms var(--dbh-clinic-ease); }
  .dbh-clinic-axis { grid-column: 2; grid-row: 1; position: relative; }
  .dbh-clinic-axis span { position: absolute; top: 4px; translate: -50% 0; font: 500 10.5px var(--dbh-clinic-mono); color: var(--dbh-clinic-faint); }
  .dbh-clinic-axis i { position: absolute; top: 22px; height: 1000px; border-left: 1px dashed var(--dbh-clinic-line); pointer-events: none; }
  .dbh-clinic-axis { overflow: visible; }
  .dbh-clinic-gantt { overflow: hidden; }
  .dbh-clinic-prow { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; align-items: stretch; border-top: 1px solid var(--dbh-clinic-line); animation: dbh-clinic-rise 520ms var(--dbh-clinic-ease) both; animation-delay: calc(var(--i) * 70ms); }
  .dbh-clinic-plabel { grid-column: 1; align-self: center; display: grid; padding: 0 10px; line-height: 1.25; min-width: 0; }
  .dbh-clinic-plabel b { font-size: 12.5px; font-weight: 650; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dbh-clinic-plabel small { font: 500 10.5px var(--dbh-clinic-mono); color: var(--dbh-clinic-faint); }
  .dbh-clinic-track { grid-column: 2; position: relative; animation: dbh-clinic-wipe 900ms var(--dbh-clinic-ease) both; animation-delay: calc(var(--i) * 70ms + 120ms); }
  .dbh-clinic-lunch { position: absolute; top: 0; bottom: 0; left: calc((720 - var(--t0)) * 100% / var(--span)); width: calc(60 * 100% / var(--span)); background: repeating-linear-gradient(135deg, transparent 0 5px, var(--dbh-clinic-line) 5px 6px); }

  .dbh-clinic-v {
    --st: min(var(--a), var(--s)); --en: max(var(--o), calc(var(--s) + var(--d))); --len: calc(var(--en) - var(--st));
    position: absolute; z-index: 1; top: calc(4px + var(--lane) * 50%); height: calc(50% - 6px);
    left: calc((var(--st) - var(--t0)) * 100% / var(--span)); width: calc(var(--len) * 100% / var(--span));
    border-radius: 4px; outline-offset: 1px;
  }
  .dbh-clinic-v > i { position: absolute; top: 0; bottom: 0; border-radius: 3px; left: calc((var(--from) - var(--st)) * 100% / var(--len)); width: calc(max(0, min(var(--to), var(--dbh-clinic-t)) - var(--from)) * 100% / var(--len)); }
  .dbh-clinic-v .dbh-clinic-sg { --from: var(--s); width: calc(var(--d) * 100% / var(--len)); box-shadow: inset 0 0 0 1px var(--dbh-clinic-line2); background: repeating-linear-gradient(90deg, transparent 0 3px, var(--dbh-clinic-sunk) 3px 4px); opacity: 0; transition: opacity 200ms; }
  .dbh-clinic-v:is([data-state="sched"], [data-state="wait"], [data-state="room"]) .dbh-clinic-sg { opacity: 1; }
  .dbh-clinic-v[data-state="noshow"] .dbh-clinic-sg { opacity: 1; box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dbh-clinic-late) 70%, transparent); background: repeating-linear-gradient(135deg, transparent 0 4px, color-mix(in oklch, var(--dbh-clinic-late) 25%, transparent) 4px 5px); }
  .dbh-clinic-v .dbh-clinic-sw { --from: var(--a); --to: var(--r); background: repeating-linear-gradient(135deg, var(--dbh-clinic-wait) 0 3px, color-mix(in oklch, var(--dbh-clinic-wait) 45%, var(--dbh-clinic-card)) 3px 6px); }
  .dbh-clinic-v .dbh-clinic-sr2 { --from: var(--r); --to: var(--p); background: var(--dbh-clinic-room); }
  .dbh-clinic-v .dbh-clinic-sp { --from: var(--p); --to: var(--e); background: var(--dbh-clinic-accent); }
  .dbh-clinic-v .dbh-clinic-so { --from: var(--e); --to: var(--o); background: var(--dbh-clinic-out); }
  .dbh-clinic-v[data-late] .dbh-clinic-sp { box-shadow: inset 0 2.5px 0 var(--dbh-clinic-late); }
  .dbh-clinic-v[data-tele] .dbh-clinic-sp { background: repeating-linear-gradient(90deg, var(--dbh-clinic-accent) 0 4px, color-mix(in oklch, var(--dbh-clinic-accent) 60%, var(--dbh-clinic-card)) 4px 6px); }
  .dbh-clinic-v:hover, .dbh-clinic-v:focus-visible { z-index: 3; box-shadow: 0 0 0 2px var(--dbh-clinic-card), 0 0 0 3.5px var(--dbh-clinic-ink); }
  .dbh-clinic-v:focus-visible { outline: none; }

  .dbh-clinic-nowwrap { grid-column: 2; grid-row: 1 / -1; position: relative; z-index: 2; pointer-events: none; }
  .dbh-clinic-now { position: absolute; top: 0; bottom: 0; left: calc((var(--dbh-clinic-t) - var(--t0)) * 100% / var(--span)); width: 0; border-left: 2px solid var(--dbh-clinic-ink); }
  .dbh-clinic-now span { position: absolute; top: 2px; left: 0; translate: -50% 0; padding: 1px 6px; border-radius: 6px; background: var(--dbh-clinic-ink); color: var(--dbh-clinic-paper); font: 650 10.5px var(--dbh-clinic-mono); font-variant-numeric: tabular-nums; }
  .dbh-clinic-future { position: absolute; top: 24px; bottom: 0; right: 0; left: calc((var(--dbh-clinic-t) - var(--t0)) * 100% / var(--span)); background: color-mix(in oklch, var(--dbh-clinic-paper) 55%, transparent); }

  .dbh-clinic-tip { position: absolute; top: 0; left: 0; z-index: 6; width: 236px; padding: 10px 12px; border-radius: 11px; pointer-events: none; background: var(--dbh-clinic-ink); color: var(--dbh-clinic-paper); box-shadow: 0 18px 40px color-mix(in oklch, var(--dbh-clinic-ink) 30%, transparent); font-size: 12px; line-height: 1.5; }
  .dbh-clinic-tip b { display: block; font-size: 12.5px; }
  .dbh-clinic-tip small { display: block; margin-bottom: 6px; color: color-mix(in oklch, var(--dbh-clinic-paper) 70%, transparent); }
  .dbh-clinic-tip dl { display: grid; grid-template-columns: auto 1fr; gap: 1px 10px; font: 500 11.5px var(--dbh-clinic-mono); font-variant-numeric: tabular-nums; }
  .dbh-clinic-tip dt { color: color-mix(in oklch, var(--dbh-clinic-paper) 65%, transparent); }
  .dbh-clinic-tip dd { text-align: right; }
  .dbh-clinic-tip em { display: block; margin-top: 6px; padding-top: 6px; border-top: 1px solid color-mix(in oklch, var(--dbh-clinic-paper) 18%, transparent); font-style: normal; font-weight: 600; }

  /* waiting list */
  .dbh-clinic-wait { display: grid; grid-template-rows: auto minmax(0, 1fr); padding: 14px 10px 10px 14px; }
  .dbh-clinic-wlist { position: relative; min-height: 0; overflow: auto; display: grid; align-content: start; gap: 4px; padding-right: 4px; scrollbar-width: thin; scrollbar-color: var(--dbh-clinic-line2) transparent; }
