const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const uid = Math.random().toString(36).slice(2, 7);
$$('[id]').forEach(el => { el.id += '-' + uid; });
$$('[aria-controls], [aria-labelledby]').forEach(el => ['aria-controls', 'aria-labelledby'].forEach(a => {
  if (el.hasAttribute(a)) el.setAttribute(a, el.getAttribute(a) + '-' + uid);
}));

const rng = seed => () => {
  seed |= 0; seed = seed + 0x6D2B79F5 | 0;
  let t = Math.imul(seed ^ seed >>> 15, 1 | seed);
