const pad = n => String(Math.floor(n)).padStart(2, '0');
const hm = m => pad(m / 60) + ':' + pad(m % 60);
const T0 = 465, T1 = 1065, ROOMS = 6;

/* ---------- one simulated Tuesday: bookings, then a pass that shares 6 rooms and 4 clinicians ---------- */
const TYPES = { fu: ['Follow-up', 20], ann: ['Annual physical', 35], new: ['New patient', 40], sick: ['Same-day', 15], proc: ['Procedure', 30], tele: ['Telehealth', 15] };
const PROV = [
  { id: 'al', name: 'Dr. Amara Lindqvist', short: 'Lindqvist', role: 'Family medicine', slot: 20, mix: ['fu', 'fu', 'ann', 'sick', 'new', 'tele', 'fu'] },
  { id: 'fo', name: 'Dr. Felix Oduya', short: 'Oduya', role: 'Family medicine', slot: 15, mix: ['fu', 'sick', 'sick', 'fu', 'tele', 'fu'] },
  { id: 'ra', name: 'NP Rosalind Achebe-Marsh', short: 'Achebe-Marsh', role: 'Nurse practitioner', slot: 20, mix: ['fu', 'sick', 'ann', 'fu', 'sick'] },
  { id: 'tw', name: 'Dr. Tomasz Weir', short: 'Weir', role: 'Minor procedures', slot: 30, mix: ['proc', 'new', 'fu', 'proc'] }
];
const FIRST = ['Hollis', 'Priya', 'Mateo', 'Yara', 'Colm', 'Ingrid', 'Tobias', 'Nkechi', 'Reuben', 'Saanvi', 'Elif', 'Gideon', 'Marisol', 'Anouk', 'Kwame', 'Linnea', 'Dario', 'Fenna', 'Omar', 'Tamsin', 'Ravi', 'Beatrix', 'Joaquin', 'Mei', 'Lorcan', 'Zainab', 'Henrik', 'Odette', 'Bashir', 'Clementine', 'Rafferty', 'Imani', 'Soren', 'Pilar', 'Wendell', 'Ayesha', 'Caspian', 'Noor', 'Ezra', 'Greta', 'Ines', 'Tariq', 'Wren', 'Solveig', 'Emeka', 'Lucia', 'Bram', 'Hana'];
const LET = 'ABCDEFGHJKLMNOPRSTVWY';
const r = rng(2909);
const V = [];
PROV.forEach((p, pi) => {
  for (const [a, b] of [[480, 720], [780, 1020]]) {
    for (let s = a; s + p.slot <= b; s += p.slot) {
      if (r() < 0.13) continue;                                  // unbooked slot
      const type = p.mix[Math.floor(r() * p.mix.length)];
      const len = Math.ceil(TYPES[type][1] / p.slot) * p.slot;   // booked minutes
      if (s + len > b) continue;
      V.push({ prov: pi, s, d: len, type });
      s += len - p.slot;
    }
  }
});
V.sort((x, y) => x.s - y.s || x.prov - y.prov);
const provFree = PROV.map(() => 0), roomFree = Array(ROOMS).fill(0);
V.forEach((v, k) => {
  v.id = k;
  v.name = FIRST[(k * 7 + 3) % FIRST.length] + ' ' + LET[Math.floor(r() * LET.length)] + '.';
  v.tele = v.type === 'tele';
  v.noshow = !v.tele && r() < 0.07;
  if (v.noshow) { v.a = v.r = v.p = v.e = v.o = v.s; return; }
  const work = TYPES[v.type][1] * (0.7 + r() * 0.42);
  if (v.tele) {
    v.a = v.s - 3; v.r = v.a; v.p = Math.max(v.s, provFree[v.prov]); v.e = v.p + work; v.o = v.e; v.room = 0;
  } else {
    v.a = v.s - 14 + r() * 24;
    if (r() < 0.12) v.a += 10 + r() * 12;                        // a late arrival
    const want = Math.max(v.a + 3, provFree[v.prov] - 6, v.s - 8);
    let ri = 0;
    for (let j = 1; j < ROOMS; j++) if (roomFree[j] < roomFree[ri]) ri = j;
    v.r = Math.max(want, roomFree[ri]) + r() * 3;
    v.room = ri + 1;
    v.p = Math.max(v.r + 2 + r() * 6, provFree[v.prov]);
    v.e = v.p + work;
    v.o = v.e + 3 + r() * 6;
    roomFree[ri] = v.e + 4;
  }
  provFree[v.prov] = v.e + 1;
});
// lanes alternate within each clinician so a waiting patient never hides the one being seen
PROV.forEach((p, pi) => V.filter(v => v.prov === pi).forEach((v, k) => { v.lane = k % 2; }));

function stateAt(v, t) {
  if (v.noshow) return t >= v.s + 15 ? 'noshow' : 'sched';
  if (t < v.a) return 'sched';
  if (t < v.r) return 'wait';
  if (t < v.p) return 'room';
  if (t < v.e) return 'prov';
  if (t < v.o) return 'out';
  return 'done';
}
const on = new Set(PROV.map(p => p.id));
const shown = () => V.filter(v => on.has(PROV[v.prov].id));
const median = a => { if (!a.length) return NaN; const s = a.slice().sort((x, y) => x - y), m = s.length >> 1; return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };
const quant = (a, q) => { const s = a.slice().sort((x, y) => x - y); const i = (s.length - 1) * q, lo = Math.floor(i); return s[lo] + (s[Math.ceil(i)] - s[lo]) * (i - lo); };

/* ---------- sidebar clinicians ---------- */
const provBox = $('.dbh-clinic-provs');
provBox.insertAdjacentHTML('beforeend', PROV.map(p => `<label data-p="${p.id}"><input type="checkbox" value="${p.id}" checked><span><b>${p.name}</b><small>${p.role} · ${V.filter(v => v.prov === PROV.indexOf(p)).length} booked</small></span><em class="dbh-clinic-lag" data-lag="${p.id}">—</em></label>`).join(''));

/* ---------- gantt ---------- */
const gantt = $('.dbh-clinic-gantt'), gcard = $('.dbh-clinic-gcard'), tip = $('.dbh-clinic-tip', gcard);
const axis = $('.dbh-clinic-axis');
for (let m = 480; m <= 1020; m += 60) axis.insertAdjacentHTML('beforeend', `<span style="left:${((m - T0) / (T1 - T0) * 100).toFixed(2)}%">${pad(m / 60)}:00</span><i style="left:${((m - T0) / (T1 - T0) * 100).toFixed(2)}%"></i>`);
let btns = new Map();
function buildGantt() {
  $$('.dbh-clinic-prow', gantt).forEach(el => el.remove());
  const vp = PROV.filter(p => on.has(p.id));
  gantt.style.setProperty('--rows', Math.max(1, vp.length));
  $('.dbh-clinic-nowwrap').style.gridRow = `1 / ${vp.length + 2}`;
  btns = new Map();
  vp.forEach((p, k) => {
    const pi = PROV.indexOf(p);
    const row = document.createElement('div');
    row.className = 'dbh-clinic-prow';
    row.style.cssText = `grid-row:${k + 2};--i:${k}`;
    row.dataset.p = p.id;
    row.innerHTML = `<div class="dbh-clinic-plabel"><b>${p.short}</b><small>${p.slot}-min slots</small></div><div class="dbh-clinic-track" style="--i:${k}"><div class="dbh-clinic-lunch"></div>${
      V.filter(v => v.prov === pi).map(v => `<button type="button" class="dbh-clinic-v" data-id="${v.id}" data-state="sched" tabindex="-1"${v.tele ? ' data-tele' : ''}
        style="--s:${v.s};--d:${v.d};--a:${v.a.toFixed(2)};--r:${v.r.toFixed(2)};--p:${v.p.toFixed(2)};--e:${v.e.toFixed(2)};--o:${v.o.toFixed(2)};--lane:${v.lane}"
        aria-label="${v.name}, ${TYPES[v.type][0]} with ${p.short}, booked ${hm(v.s)}"><i class="dbh-clinic-sg"></i><i class="dbh-clinic-sw"></i><i class="dbh-clinic-sr2"></i><i class="dbh-clinic-sp"></i><i class="dbh-clinic-so"></i></button>`).join('')
    }</div>`;
    gantt.appendChild(row);
  });
  $$('.dbh-clinic-v', gantt).forEach(b => btns.set(+b.dataset.id, b));
  const firstBtn = btns.values().next().value;
  if (firstBtn) firstBtn.tabIndex = 0;
  lastStates.clear();
}

function tipFor(v) {
  const p = PROV[v.prov], f = x => x <= T ? hm(x) : '—';
  if (v.noshow) return `<b>${v.name}</b><small>${TYPES[v.type][0]} · ${p.short}</small><dl><dt>Booked</dt><dd>${hm(v.s)} · ${v.d} min</dd></dl><em>${T >= v.s + 15 ? 'No-show · slot released at ' + hm(v.s + 15) : 'Not arrived yet'}</em>`;
  const rows = v.tele
    ? `<dt>Booked</dt><dd>${hm(v.s)} · ${v.d} min</dd><dt>Joined call</dt><dd>${f(v.a)}</dd><dt>Clinician</dt><dd>${v.p <= T ? hm(v.p) + '–' + (v.e <= T ? hm(v.e) : 'now') : '—'}</dd>`
    : `<dt>Booked</dt><dd>${hm(v.s)} · ${v.d} min</dd><dt>Arrived</dt><dd>${f(v.a)}</dd><dt>Roomed</dt><dd>${v.r <= T ? hm(v.r) + ' · room ' + v.room : '—'}</dd><dt>Clinician</dt><dd>${v.p <= T ? hm(v.p) + '–' + (v.e <= T ? hm(v.e) : 'now') : '—'}</dd><dt>Left</dt><dd>${f(v.o)}</dd>`;
  let em = 'Not arrived yet';
  if (v.p <= T) em = v.tele ? `${Math.round(v.p - v.s)} min past booked time` : `${Math.round(v.p - v.a)} min door to clinician${v.p - v.s > 15 ? ' · started ' + Math.round(v.p - v.s) + ' min late' : ''}`;
  else if (v.a <= T) em = `Waiting ${Math.round(T - v.a)} min so far`;
  return `<b>${v.name}</b><small>${TYPES[v.type][0]} · ${p.short}</small><dl>${rows}</dl><em>${em}</em>`;
}
let tipFor_ = null;
function showTip(btn) {
  const v = V[+btn.dataset.id];
  tipFor_ = btn;
  tip.innerHTML = tipFor(v);
  tip.hidden = false;
  const cr = gcard.getBoundingClientRect(), br = btn.getBoundingClientRect();
  const tw = tip.offsetWidth, th = tip.offsetHeight;
  let x = br.left - cr.left + br.width / 2 - tw / 2;
  x = Math.max(6, Math.min(cr.width - tw - 6, x));
  let y = br.top - cr.top - th - 8;
  if (y < 4) y = br.bottom - cr.top + 8;
  tip.style.translate = `${x.toFixed(0)}px ${y.toFixed(0)}px`;
}
function hideTip() { tip.hidden = true; tipFor_ = null; }
gantt.addEventListener('pointerover', e => { const b = e.target.closest('.dbh-clinic-v'); if (b) showTip(b); });
gantt.addEventListener('pointerout', e => { const b = e.target.closest('.dbh-clinic-v'); if (b && !b.contains(e.relatedTarget) && document.activeElement !== b) hideTip(); });
gantt.addEventListener('focusin', e => { const b = e.target.closest('.dbh-clinic-v'); if (b) showTip(b); });
gantt.addEventListener('focusout', hideTip);
gantt.addEventListener('keydown', e => {
  const b = e.target.closest('.dbh-clinic-v');
  if (!b) return;
  if (e.key === 'Escape') { hideTip(); return; }
  const v = V[+b.dataset.id];
  const rowIds = [...btns.keys()].map(id => V[id]);
  const vp = PROV.map((p, i) => i).filter(i => on.has(PROV[i].id));
  let target = null;
  const same = rowIds.filter(x => x.prov === v.prov);
  const k = same.indexOf(v);
  if (e.key === 'ArrowRight') target = same[k + 1];
  else if (e.key === 'ArrowLeft') target = same[k - 1];
  else if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
    const pr = vp[vp.indexOf(v.prov) + (e.key === 'ArrowDown' ? 1 : -1)];
    if (pr != null) target = rowIds.filter(x => x.prov === pr).reduce((best, x) => !best || Math.abs(x.s - v.s) < Math.abs(best.s - v.s) ? x : best, null);
  } else if (e.key === 'Home') target = same[0];
  else if (e.key === 'End') target = same[same.length - 1];
  if (!target) return;
  e.preventDefault();
  b.tabIndex = -1;
  const nb = btns.get(target.id);
  nb.tabIndex = 0;
  nb.focus({ preventScroll: true });
  const sc = $('.dbh-clinic-gscroll'), br = nb.getBoundingClientRect(), sr = sc.getBoundingClientRect();
  if (br.left < sr.left + 120) sc.scrollLeft -= sr.left + 120 - br.left; else if (br.right > sr.right) sc.scrollLeft += br.right - sr.right + 8;
});

/* ---------- waiting list: keyed, enters with @starting-style, survivors FLIP ---------- */
const wl = $('.dbh-clinic-wlist');
const live = new Map();
function paintWait(list, animate) {
  const items = list.filter(v => { const s = stateAt(v, T); return s === 'wait' || s === 'room'; }).sort((x, y) => x.a - y.a || x.id - y.id);
  const first = new Map();
  if (animate && !reduce) live.forEach((li, id) => first.set(id, li.getBoundingClientRect().top));
  const keep = new Set(items.map(v => v.id));
  live.forEach((li, id) => { if (!keep.has(id)) { li.remove(); live.delete(id); } });
  $('.dbh-clinic-wempty', wl)?.remove();
  items.forEach((v, k) => {
    let li = live.get(v.id);
    if (!li) {
      li = document.createElement('li');
      li.className = 'dbh-clinic-wi';
      const ini = v.name.split(' ').map(x => x[0]).join('');
      li.innerHTML = `<span class="dbh-clinic-wav" aria-hidden="true">${ini}</span><span class="dbh-clinic-wn"><b>${v.name}</b><small>${TYPES[v.type][0]} · ${PROV[v.prov].short}</small></span><span class="dbh-clinic-wt"><span></span><small></small></span>`;
      const next = items.slice(k + 1).map(x => live.get(x.id)).find(Boolean);
