      live.set(v.id, li);
    }
    const st = stateAt(v, T), mins = Math.max(0, Math.floor(T - v.a));
    li.dataset.where = st;
    const tone = mins > 40 ? 'late' : mins > 25 ? 'warn' : '';
    if (tone) li.dataset.tone = tone; else delete li.dataset.tone;
    const tEl = $('.dbh-clinic-wt > span', li), wEl = $('.dbh-clinic-wt small', li);
    const tt = mins + 'm', wt = v.tele ? 'virtual' : st === 'room' ? 'room ' + v.room : 'lobby';
    if (tEl.textContent !== tt) tEl.textContent = tt;
    if (wEl.textContent !== wt) wEl.textContent = wt;
  });
  if (!items.length) wl.insertAdjacentHTML('beforeend', `<li class="dbh-clinic-wempty">${T < 480 ? 'Doors open at 08:00.' : T > 1030 ? 'Everyone has been seen.' : 'Nobody is waiting right now.'}</li>`);
  $('[data-k="waitn"]').textContent = `${items.filter(v => stateAt(v, T) === 'wait').length} lobby · ${items.filter(v => stateAt(v, T) === 'room').length} roomed`;
  first.forEach((top, id) => {
    const li = live.get(id);
    if (!li) return;
    const dy = top - li.getBoundingClientRect().top;
    if (Math.abs(dy) > 1) li.animate([{ transform: `translateY(${dy}px)` }, { transform: 'none' }], { duration: 380, easing: 'cubic-bezier(.2,.8,.2,1)' });
