}

/* ---------- the clock: one custom property drives every bar ---------- */
let T = 670, playing = false;
const slider = $('.dbh-clinic-scrub input'), clockOut = $('.dbh-clinic-clock'), nowLbl = $('.dbh-clinic-now span');
const lastStates = new Map();
const kpi = k => $(`[data-k="${k}"]`);
