  const st = list.map(v => stateAt(v, T));
  const lobby = list.filter((v, i) => st[i] === 'wait' && !v.tele).length;
  const rooms = list.filter((v, i) => (st[i] === 'room' || st[i] === 'prov') && !v.tele).length;
  const done = st.filter(s => s === 'done').length;
  const started = list.filter(v => !v.noshow && v.p <= T);
  const d2p = median(started.filter(v => !v.tele).map(v => v.p - v.a));
  const ontime = started.length ? started.filter(v => v.p - v.s <= 10).length / started.length : NaN;
  kpi('lobby').textContent = lobby;
  kpi('rooms').innerHTML = `${rooms}<small>/ ${ROOMS}</small>`;
  kpi('done').innerHTML = `${done}<small>/ ${list.length}</small>`;
  const dd = kpi('d2p');
  dd.innerHTML = isNaN(d2p) ? '—' : `${Math.round(d2p)}<small>min</small>`;
  dd.dataset.tone = d2p > 30 ? 'late' : d2p > 20 ? 'warn' : '';
  kpi('ontime').innerHTML = isNaN(ontime) ? '—' : `${Math.round(ontime * 100)}<small>%</small>`;
  const ns = st.filter(s => s === 'noshow').length;
  $('.dbh-clinic-title .dbh-clinic-eyebrow').textContent = `Day replay · ${ROOMS} exam rooms · ${ns} no-show${ns === 1 ? '' : 's'} so far`;
  // how late each clinician is running, from their latest started visit
  PROV.forEach((p, pi) => {
    const last = V.filter(v => v.prov === pi && !v.noshow && v.p <= T).pop();
    const el = $(`[data-lag="${p.id}"]`);
    if (!last) { el.textContent = '—'; delete el.dataset.tone; return; }
    const lag = Math.round(last.p - last.s);
    el.textContent = lag <= 5 ? 'on time' : '+' + lag + 'm';
    el.dataset.tone = lag > 20 ? 'late' : lag > 5 ? 'warn' : '';
  });
  if (view === 'flow') paintWait(list, opts.animate !== false);
  else if (Math.floor(T) !== lastChartT) { lastChartT = Math.floor(T); renderCharts(); }
}
slider.addEventListener('input', () => { stop(); setT(+slider.value, { fromSlider: true }); });
$('.dbh-clinic-jumps').addEventListener('click', e => { const b = e.target.closest('[data-jump]'); if (b) { stop(); setT(+b.dataset.jump, { glide: true, animate: false }); } });

/* ---------- playback ---------- */
const playBtn = $('.dbh-clinic-play');
let raf = 0, lastNow = 0, onScreen = true;
function frame(now) {
  if (!root.isConnected) return;
  raf = 0;
  if (!playing) return;
  if (!onScreen || document.hidden) { lastNow = 0; return; }
  const dt = lastNow ? Math.min(0.1, (now - lastNow) / 1000) : 0;
  lastNow = now;
  setT(T + dt * 8);
  if (T >= T1) { stop(); return; }
  raf = requestAnimationFrame(frame);
}
function play() {
  if (T >= T1) setT(T0);
