}
playBtn.addEventListener('click', () => playing ? stop() : play());
const io = new IntersectionObserver(es => { onScreen = es[es.length - 1].isIntersecting; if (onScreen && playing && !raf) raf = requestAnimationFrame(frame); });
io.observe(root);
