    const cen = [];
    for (let m = T0; m <= Math.min(T, T1); m += 5) cen.push([m, real.filter(v => !v.tele && v.a <= m && v.o > m).length]);
    bins.forEach(b => { b.peak = Math.max(0, ...cen.filter(([m]) => m >= b.h * 60 && m < b.h * 60 + 60).map(c => c[1])); });
    const yMax = Math.max(6, ...bins.map(b => Math.max(b.booked, b.arr, b.dep)), ...cen.map(c => c[1])) + 1;
    const pw = W - L - Rm, ph = H - top - bot, bw = pw / hours.length;
    const y = v => top + ph - v / yMax * ph;
    const xm = m => L + (m - 480) / 600 * pw;
    let out = '';
    for (let k = 0; k <= yMax; k += yMax > 12 ? 4 : 2) out += `<line class="dbh-clinic-grid" x1="${L}" x2="${W - Rm}" y1="${y(k).toFixed(1)}" y2="${y(k).toFixed(1)}"/><text x="${L - 6}" y="${(y(k) + 3.5).toFixed(1)}" text-anchor="end">${k}</text>`;
    bins.forEach((b, k) => {
      const x0 = L + k * bw, w = Math.max(3, (bw - 10) / 2);
      out += `<rect class="dbh-clinic-ghostbar" x="${(x0 + 4).toFixed(1)}" width="${(bw - 8).toFixed(1)}" y="${y(b.booked).toFixed(1)}" height="${(top + ph - y(b.booked)).toFixed(1)}" rx="3"/>`;
      if (b.arr) out += `<rect class="dbh-clinic-barA" style="--i:${k}" x="${(x0 + 5).toFixed(1)}" width="${w.toFixed(1)}" y="${y(b.arr).toFixed(1)}" height="${(top + ph - y(b.arr)).toFixed(1)}" rx="2"/>`;
      if (b.dep) out += `<rect class="dbh-clinic-barD" style="--i:${k}" x="${(x0 + 5 + w).toFixed(1)}" width="${w.toFixed(1)}" y="${y(b.dep).toFixed(1)}" height="${(top + ph - y(b.dep)).toFixed(1)}" rx="2"/>`;
      out += `<text x="${(x0 + bw / 2).toFixed(1)}" y="${H - 6}" text-anchor="middle">${pad(b.h)}</text>`;
    });
    if (cen.length > 1) out += `<path class="dbh-clinic-cen" d="${cen.map(([m, c], k) => (k ? 'L' : 'M') + xm(m).toFixed(1) + ',' + y(c).toFixed(1)).join('')}"/>`;
    bins.forEach((b, k) => { out += `<rect class="dbh-clinic-hcol" data-h="${k}" x="${(L + k * bw).toFixed(1)}" width="${bw.toFixed(1)}" y="${top}" height="${ph}"/>`; });
    svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
    svg.innerHTML = out;
    svg._bins = bins;
  }
  // door-to-clinician strips
  const box2 = $('[data-c="d2p"]'), svg2 = $('svg', box2);
  W = box2.clientWidth; H = box2.clientHeight;
  if (W > 60 && H > 60) {
    const vp = PROV.map((p, i) => i).filter(i => on.has(PROV[i].id));
    const L = 92, Rm = 10, top = 6, bot = 22;
    const started = list.filter(v => !v.noshow && !v.tele && v.p <= T);
    const xMax = Math.max(50, Math.ceil((Math.max(0, ...started.map(v => v.p - v.a)) + 5) / 10) * 10);
    const pw = W - L - Rm, rowH = (H - top - bot) / Math.max(1, vp.length);
    const x = m => L + m / xMax * pw;
    let out = '';
    for (let m = 0; m <= xMax; m += 10) out += `<line class="dbh-clinic-grid" x1="${x(m).toFixed(1)}" x2="${x(m).toFixed(1)}" y1="${top}" y2="${H - bot}"/><text x="${x(m).toFixed(1)}" y="${H - 6}" text-anchor="middle">${m}</text>`;
    out += `<line class="dbh-clinic-target" x1="${x(20).toFixed(1)}" x2="${x(20).toFixed(1)}" y1="${top}" y2="${H - bot}"/>`;
    let di = 0;
    vp.forEach((pi, k) => {
      const cy = top + rowH * k + rowH / 2;
      const vals = started.filter(v => v.prov === pi);
      out += `<text class="dbh-clinic-lbl" x="${L - 12}" y="${(cy + 4).toFixed(1)}" text-anchor="end">${PROV[pi].short}</text>`;
      if (vals.length >= 2) {
        const w = vals.map(v => v.p - v.a), q1 = quant(w, 0.25), q3 = quant(w, 0.75), md = median(w);
        out += `<rect class="dbh-clinic-iqr" x="${x(q1).toFixed(1)}" width="${Math.max(2, x(q3) - x(q1)).toFixed(1)}" y="${(cy - rowH * 0.3).toFixed(1)}" height="${(rowH * 0.6).toFixed(1)}" rx="5"/>`;
        out += `<line class="dbh-clinic-med" x1="${x(md).toFixed(1)}" x2="${x(md).toFixed(1)}" y1="${(cy - rowH * 0.32).toFixed(1)}" y2="${(cy + rowH * 0.32).toFixed(1)}"/>`;
      }
      vals.forEach(v => {
        const jit = ((v.id * 37) % 11 - 5) / 5 * rowH * 0.22, w = v.p - v.a;
        out += `<circle class="dbh-clinic-dot" data-id="${v.id}" style="--i:${di++}"${w > 30 ? ' data-tone="late"' : ''} cx="${x(w).toFixed(1)}" cy="${(cy + jit).toFixed(1)}" r="4"/>`;
      });
      if (!vals.length) out += `<text x="${L}" y="${(cy + 4).toFixed(1)}">no visits started yet</text>`;
    });
    svg2.setAttribute('viewBox', `0 0 ${W} ${H}`);
    svg2.innerHTML = out;
  }
}
function placeTip2(e, html) {
  tip2.innerHTML = html;
  tip2.hidden = false;
  const tr = thru.getBoundingClientRect(), tw = tip2.offsetWidth, th = tip2.offsetHeight;
  let x = e.clientX - tr.left + 14, y = e.clientY - tr.top - th - 10;
  if (x + tw > tr.width) x = e.clientX - tr.left - tw - 14;
  if (y < 0) y = e.clientY - tr.top + 16;
  tip2.style.translate = `${Math.max(0, x).toFixed(0)}px ${y.toFixed(0)}px`;
}
thru.addEventListener('pointermove', e => {
  const col = e.target.closest('.dbh-clinic-hcol'), dot = e.target.closest('.dbh-clinic-dot');
  if (col) {
    const b = col.ownerSVGElement._bins[+col.dataset.h];
    placeTip2(e, `<b>${pad(b.h)}:00–${pad(b.h + 1)}:00</b><dl><dt>Booked</dt><dd>${b.booked}</dd><dt>Arrived</dt><dd>${b.arr}</dd><dt>Completed</dt><dd>${b.dep}</dd><dt>Peak in clinic</dt><dd>${b.h * 60 > T ? '—' : b.peak}</dd></dl>`);
  } else if (dot) {
    const v = V[+dot.dataset.id];
    placeTip2(e, `<b>${v.name}</b><small>${TYPES[v.type][0]} · ${PROV[v.prov].short}</small><dl><dt>Arrived</dt><dd>${hm(v.a)}</dd><dt>Clinician</dt><dd>${hm(v.p)}</dd></dl><em>${Math.round(v.p - v.a)} min door to clinician</em>`);
