roving($('.dbh-clinic-nav'), '[role="tab"]', 'aria-selected', t => {
  view = t.dataset.view;
  $('.dbh-clinic-flow').hidden = view !== 'flow';
  thru.hidden = view !== 'thru';
  lastChartT = -1;
  setT(T, { animate: false });
});
provBox.addEventListener('change', e => {
  const t = e.target;
  if (t.checked) on.add(t.value); else on.delete(t.value);
  buildGantt();
  live.forEach(li => li.remove()); live.clear();
  lastChartT = -1;
  setT(T, { animate: false });
});

buildGantt();
setT(T, { animate: false });

