@keyframes dbh-labs-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes dbh-labs-pop { from { opacity: 0; scale: 0.2; } }
@keyframes dbh-labs-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbh-labs-reveal { from { opacity: 0; transform: translateY(10px); } }
@keyframes dbh-labs-band { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes dbh-labs-out { to { opacity: 0; } }

.dbh-labs {
  /* re-theme with these */
  --dbh-labs-paper: oklch(0.982 0.012 88);
  --dbh-labs-ink: oklch(0.25 0.028 165);
  --dbh-labs-accent: oklch(0.5 0.1 165);
  --dbh-labs-high: oklch(0.6 0.19 38);
  --dbh-labs-low: oklch(0.54 0.14 258);
  /* derived */
  --dbh-labs-card: color-mix(in oklch, var(--dbh-labs-paper), white 70%);
  --dbh-labs-sunk: color-mix(in oklch, var(--dbh-labs-paper), var(--dbh-labs-ink) 5%);
  --dbh-labs-band: color-mix(in oklch, var(--dbh-labs-accent) 13%, var(--dbh-labs-card));
  --dbh-labs-line: color-mix(in oklch, var(--dbh-labs-ink) 10%, transparent);
  --dbh-labs-line2: color-mix(in oklch, var(--dbh-labs-ink) 20%, transparent);
  --dbh-labs-muted: color-mix(in oklch, var(--dbh-labs-ink) 62%, var(--dbh-labs-paper));
  --dbh-labs-faint: color-mix(in oklch, var(--dbh-labs-ink) 42%, var(--dbh-labs-paper));
  --dbh-labs-ease: cubic-bezier(0.2, 0.8, 0.2, 1);
  --dbh-labs-spring: linear(0, 0.03, 0.12 5%, 0.55 14%, 0.94 23%, 1.06 30%, 1.07 35%, 1.03 44%, 1 56%, 1);
  --dbh-labs-serif: ui-serif, "Iowan Old Style", Georgia, serif;
  --dbh-labs-mono: ui-monospace, Menlo, Consolas, monospace;

  width: 100%;
  height: var(--dbh-labs-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dbh-labs-paper);
  color: var(--dbh-labs-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dbh-labs-accent);
  box-shadow: inset 0 0 0 1px var(--dbh-labs-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbh-labs-accent); outline-offset: 2px; border-radius: 6px; }
  & h2 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dbh-labs-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.1em; text-transform: uppercase; color: var(--dbh-labs-muted); }
  .dbh-labs-app { display: grid; height: 100%; grid-template-columns: 276px minmax(0, 1fr); grid-template-areas: "side main"; }

  /* ---------- side ---------- */
  .dbh-labs-side { grid-area: side; min-height: 0; display: grid; grid-template-rows: auto auto minmax(0, 1fr); gap: 14px; padding: 18px 0 0; border-right: 1px solid var(--dbh-labs-line); background: var(--dbh-labs-sunk); }
  .dbh-labs-brand { display: flex; align-items: center; gap: 10px; padding: 0 18px; }
  .dbh-labs-brand svg { flex: none; width: 30px; height: 30px; padding: 5px; border-radius: 8px; background: var(--dbh-labs-accent); fill: none; stroke: var(--dbh-labs-card); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  .dbh-labs-brand span { display: grid; line-height: 1.2; }
  .dbh-labs-brand b { font: 600 16px/1.1 var(--dbh-labs-serif); letter-spacing: -0.01em; }
  .dbh-labs-brand small { font-size: 11px; color: var(--dbh-labs-muted); }
  .dbh-labs-filters { display: grid; gap: 8px; padding: 0 14px; }
  .dbh-labs-search { display: flex; align-items: center; gap: 8px; height: 34px; padding: 0 10px; border-radius: 9px; background: var(--dbh-labs-card); box-shadow: inset 0 0 0 1px var(--dbh-labs-line2); transition: box-shadow 150ms; }
  .dbh-labs-search:has(input:focus-visible) { box-shadow: inset 0 0 0 1.5px var(--dbh-labs-accent), 0 0 0 3px color-mix(in oklch, var(--dbh-labs-accent) 18%, transparent); }
  .dbh-labs-search svg { flex: none; width: 15px; height: 15px; fill: none; stroke: var(--dbh-labs-faint); stroke-width: 2; stroke-linecap: round; }
  .dbh-labs-search input { flex: 1; min-width: 0; border: 0; background: none; outline: none; font: inherit; color: inherit; }
  .dbh-labs-search input::placeholder { color: var(--dbh-labs-faint); }
  .dbh-labs-switch { display: flex; align-items: center; gap: 8px; padding: 2px 2px; cursor: pointer; font-size: 12.5px; font-weight: 550; }
  .dbh-labs-switch input { appearance: none; position: relative; flex: none; width: 30px; height: 18px; margin: 0; border-radius: 99px; background: var(--dbh-labs-line2); cursor: pointer; transition: background-color 180ms; }
  .dbh-labs-switch input::after { content: ""; position: absolute; top: 2px; left: 2px; width: 14px; height: 14px; border-radius: 50%; background: var(--dbh-labs-card); box-shadow: 0 1px 2px color-mix(in oklch, var(--dbh-labs-ink) 25%, transparent); transition: translate 260ms var(--dbh-labs-spring); }
  .dbh-labs-switch input:checked { background: var(--dbh-labs-high); }
  .dbh-labs-switch input:checked::after { translate: 12px 0; }
  .dbh-labs-switch em { margin-left: auto; font: 600 11px var(--dbh-labs-mono); font-style: normal; padding: 1px 7px; border-radius: 99px; background: color-mix(in oklch, var(--dbh-labs-high) 16%, var(--dbh-labs-card)); color: color-mix(in oklch, var(--dbh-labs-high), var(--dbh-labs-ink) 30%); }
  .dbh-labs-list { min-height: 0; overflow: auto; padding: 0 8px 14px; scrollbar-width: thin; scrollbar-color: var(--dbh-labs-line2) transparent; }
  .dbh-labs-group { display: grid; gap: 1px; margin-bottom: 8px; }
  .dbh-labs-ghead { position: sticky; top: 0; z-index: 1; padding: 6px 10px 4px; background: var(--dbh-labs-sunk); font-size: 10.5px; font-weight: 650; letter-spacing: 0.1em; text-transform: uppercase; color: var(--dbh-labs-faint); }
  .dbh-labs-opt { display: grid; grid-template-columns: minmax(0, 1fr) auto 20px; grid-template-rows: auto auto; align-items: center; column-gap: 8px; row-gap: 4px; padding: 7px 10px; border-radius: 9px; cursor: pointer; outline-offset: -2px; transition: background-color 140ms; animation: dbh-labs-rise 420ms var(--dbh-labs-ease) both; animation-delay: calc(var(--i) * 22ms); }
  .dbh-labs-opt:hover { background: color-mix(in oklch, var(--dbh-labs-ink) 4%, transparent); }
