const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const uid = Math.random().toString(36).slice(2, 7);
$$('[id]').forEach(el => { el.id += '-' + uid; });
$$('[aria-controls], [aria-labelledby]').forEach(el => ['aria-controls', 'aria-labelledby'].forEach(a => {
  if (el.hasAttribute(a)) el.setAttribute(a, el.getAttribute(a) + '-' + uid);
}));

/* ---------- ten draws; every value is stored once, in conventional units ---------- */
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const DRAWS = ['2023-01-17', '2023-07-11', '2024-01-23', '2024-06-04', '2024-11-19', '2025-03-04', '2025-08-26', '2026-01-13', '2026-05-05', '2026-09-22'].map(s => { const [y, m, d] = s.split('-').map(Number); return new Date(y, m - 1, d); });
const LAB = i => i < 5 ? 'Northgate Diagnostics' : 'Fairmont Clinical Lab';
const fmtD = d => `${d.getDate()} ${MON[d.getMonth()]} ${d.getFullYear()}`;
const fmtShort = d => `${d.getDate()} ${MON[d.getMonth()]} ${String(d.getFullYear()).slice(2)}`;
const A = [
  { id: 'glu', panel: 'Metabolic', name: 'Glucose, fasting', u: 'mg/dL', su: 'mmol/L', k: v => v / 18.016, d: [0, 1], lo: 70, hi: 99, v: [94, 97, 103, 106, 112, 109, 104, 101, 99, 101] },
  { id: 'a1c', panel: 'Metabolic', name: 'Hemoglobin A1c', u: '%', su: 'mmol/mol', k: v => (v - 2.15) * 10.929, d: [1, 0], lo: 4.0, hi: 5.6, v: [5.5, null, 5.8, null, 6.2, 6.1, 5.9, 5.8, null, 5.7] },
  { id: 'cre', panel: 'Metabolic', name: 'Creatinine', u: 'mg/dL', su: 'µmol/L', k: v => v * 88.42, d: [2, 0], lo: 0.74, hi: 1.35, v: [0.98, null, 1.02, 1.05, null, 1.08, null, 1.06, 1.04, 1.07] },
  { id: 'egfr', panel: 'Metabolic', name: 'eGFR', u: 'mL/min/1.73m²', su: 'mL/min/1.73m²', k: v => v, d: [0, 0], lo: 60, hi: null, v: [86, null, 83, 80, null, 78, null, 79, 80, 78] },
  { id: 'k', panel: 'Metabolic', name: 'Potassium', u: 'mmol/L', su: 'mmol/L', k: v => v, d: [1, 1], lo: 3.5, hi: 5.1, v: [4.3, 4.1, 4.6, null, 4.4, 5.3, 4.5, 4.2, null, 4.4] },
