    if (e.key === 'ArrowRight' || e.key === 'ArrowDown') j = (i + 1) % items.length;
    else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') j = (i - 1 + items.length) % items.length;
    if (j < 0) return;
    e.preventDefault(); items[j].focus(); pick(items[j]);
  });
  return pick;
}
const [segU, segR] = $$('.dbh-labs-seg');
roving(segU, '[role="radio"]', 'aria-checked', t => {
  if (st.unit === t.dataset.unit) return;
  st.unit = t.dataset.unit;
  renderList(); paintSummary(); renderTable(); relabelChart();
  if (st.view === 'sheet') renderSheet();
});
roving(segR, '[role="radio"]', 'aria-checked', t => {
  st.years = +t.dataset.range;
  paintSummary(); renderTable();
  if (st.view === 'trend') renderChart(); else renderSheet();
});
const pickTab = roving($('.dbh-labs-tabs'), '[role="tab"]', 'aria-selected', t => {
  st.view = t.dataset.view;
  $('.dbh-labs-trend').hidden = st.view !== 'trend';
  $('.dbh-labs-sheet').hidden = st.view !== 'sheet';
  if (st.view === 'trend') renderChart(); else renderSheet();
});

function select(id) {
  st.sel = id;
  $$('.dbh-labs-opt', list).forEach(o => { const s = o.dataset.id === id; o.setAttribute('aria-selected', s); o.tabIndex = s ? 0 : -1; });
  paintSummary(); renderTable();
  if (st.view === 'trend') renderChart();
}

renderList();
paintSummary();
renderTable();

css:
@keyframes dbh-meds-in { from { opacity: 0; scale: 0.3; } }
@keyframes dbh-meds-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbh-meds-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes dbh-meds-grow { from { transform: scaleY(0); } }
@keyframes dbh-meds-fillin { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }

.dbh-meds {
  /* re-theme with these */
  --dbh-meds-bg: oklch(0.205 0.017 55);
  --dbh-meds-ink: oklch(0.94 0.016 80);
  --dbh-meds-accent: oklch(0.79 0.1 155);
  --dbh-meds-miss: oklch(0.66 0.19 27);
  /* one colour per medicine */
  --dbh-meds-thy: oklch(0.86 0.12 92);
  --dbh-meds-ost: oklch(0.76 0.09 232);
  --dbh-meds-cor: oklch(0.7 0.14 42);
  --dbh-meds-glu: oklch(0.78 0.1 155);
  --dbh-meds-lum: oklch(0.76 0.1 355);
  /* derived */
  --dbh-meds-card: color-mix(in oklch, var(--dbh-meds-bg), var(--dbh-meds-ink) 5%);
  --dbh-meds-raise: color-mix(in oklch, var(--dbh-meds-bg), var(--dbh-meds-ink) 10%);
  --dbh-meds-sunk: color-mix(in oklch, var(--dbh-meds-bg), black 20%);
  --dbh-meds-line: color-mix(in oklch, var(--dbh-meds-ink) 10%, transparent);
  --dbh-meds-line2: color-mix(in oklch, var(--dbh-meds-ink) 22%, transparent);
  --dbh-meds-muted: color-mix(in oklch, var(--dbh-meds-ink) 60%, var(--dbh-meds-bg));
  --dbh-meds-faint: color-mix(in oklch, var(--dbh-meds-ink) 38%, var(--dbh-meds-bg));
  --dbh-meds-ease: cubic-bezier(0.2, 0.8, 0.2, 1);
  --dbh-meds-spring: linear(0, 0.02, 0.08 3%, 0.5 11%, 0.92 18%, 1.08 24%, 1.11 28%, 1.06 35%, 0.99 45%, 0.995 58%, 1);
  --dbh-meds-round: ui-rounded, system-ui, -apple-system, "Segoe UI", sans-serif;
  --dbh-meds-mono: ui-monospace, Menlo, Consolas, monospace;

  width: 100%;
  height: var(--dbh-meds-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 18px;
  background: var(--dbh-meds-bg);
  color: var(--dbh-meds-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dbh-meds-accent);
  color-scheme: dark;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbh-meds-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul, & dl, & dd { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  [data-med="thy"] { --mc: var(--dbh-meds-thy); }
  [data-med="ost"] { --mc: var(--dbh-meds-ost); }
  [data-med="cor"] { --mc: var(--dbh-meds-cor); }
  [data-med="glu"] { --mc: var(--dbh-meds-glu); }
  [data-med="lum"] { --mc: var(--dbh-meds-lum); }

  .dbh-meds-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.1em; text-transform: uppercase; color: var(--dbh-meds-muted); }
  .dbh-meds-app { display: grid; height: 100%; grid-template-columns: 216px minmax(0, 1fr); grid-template-areas: "side main"; }

  /* ---------- side ---------- */
  .dbh-meds-side { grid-area: side; min-height: 0; overflow: auto; display: flex; flex-direction: column; gap: 18px; padding: 20px 14px 16px; border-right: 1px solid var(--dbh-meds-line); background: var(--dbh-meds-sunk); scrollbar-width: thin; }
  .dbh-meds-brand { display: flex; align-items: center; gap: 10px; padding: 0 4px; }
  .dbh-meds-brand svg { flex: none; width: 30px; height: 30px; padding: 4px; border-radius: 9px; background: color-mix(in oklch, var(--dbh-meds-accent) 16%, transparent); fill: none; stroke: var(--dbh-meds-accent); stroke-width: 1.7; stroke-linecap: round; }
  .dbh-meds-brand span { display: grid; line-height: 1.2; }
  .dbh-meds-brand b { font: 700 15.5px/1.1 var(--dbh-meds-round); letter-spacing: -0.01em; }
  .dbh-meds-brand small { font-size: 11px; color: var(--dbh-meds-muted); }
  .dbh-meds-person { display: flex; align-items: center; gap: 10px; padding: 10px; border-radius: 12px; background: var(--dbh-meds-card); }
  .dbh-meds-av { flex: none; display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; background: linear-gradient(135deg, var(--dbh-meds-cor), var(--dbh-meds-thy)); color: var(--dbh-meds-bg); font-size: 12px; font-weight: 750; }
  .dbh-meds-person > span:last-child { display: grid; line-height: 1.25; min-width: 0; }
  .dbh-meds-person b { font-size: 12.5px; font-weight: 640; }
  .dbh-meds-person small { font-size: 11px; color: var(--dbh-meds-muted); }
  .dbh-meds-nav { display: grid; gap: 2px; }
  .dbh-meds-nav button { display: flex; align-items: center; gap: 10px; height: 36px; padding: 0 10px; border-radius: 9px; font-weight: 580; color: var(--dbh-meds-muted); transition: background-color 150ms, color 150ms; }
  .dbh-meds-nav button:hover { color: var(--dbh-meds-ink); background: color-mix(in oklch, var(--dbh-meds-ink) 5%, transparent); }
  .dbh-meds-nav [aria-selected="true"] { color: var(--dbh-meds-ink); background: var(--dbh-meds-raise); }
  .dbh-meds-nav svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  .dbh-meds-nav [aria-selected="true"] svg { stroke: var(--dbh-meds-accent); }
  .dbh-meds-legend { display: grid; gap: 7px; padding: 0 6px; font-size: 11.5px; color: var(--dbh-meds-muted); }
  .dbh-meds-legend li { display: flex; align-items: center; gap: 9px; }
  .dbh-meds-legend li::before { content: ""; width: 9px; height: 16px; border-radius: 99px; }
  .dbh-meds-legend [data-s="taken"]::before { background: var(--dbh-meds-accent); }
  .dbh-meds-legend [data-s="late"]::before { background: repeating-linear-gradient(135deg, var(--dbh-meds-accent) 0 2.5px, color-mix(in oklch, var(--dbh-meds-accent) 30%, transparent) 2.5px 5px); }
  .dbh-meds-legend [data-s="missed"]::before { background: color-mix(in oklch, var(--dbh-meds-miss) 20%, transparent); box-shadow: inset 0 0 0 1.5px var(--dbh-meds-miss); }
  .dbh-meds-legend [data-s="up"]::before { border: 1.5px dashed var(--dbh-meds-line2); }
  .dbh-meds-foot { margin-top: auto; padding: 0 6px; font-size: 11px; color: var(--dbh-meds-faint); }

  /* ---------- main ---------- */
  .dbh-meds-main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); }
  .dbh-meds-head { display: flex; flex-wrap: wrap; align-items: center; gap: 12px 28px; padding: 18px 20px 14px; }
  .dbh-meds-hero { display: flex; align-items: center; gap: 16px; min-width: 0; flex: 1 1 340px; }
  .dbh-meds-odo { display: flex; align-items: flex-start; font: 300 clamp(46px, 1.6rem + 3cqi, 66px)/1 var(--dbh-meds-round); letter-spacing: -0.04em; font-variant-numeric: tabular-nums; color: var(--dbh-meds-accent); }
  .dbh-meds-odow { display: flex; height: 1em; overflow: hidden; }
  .dbh-meds-dcol { display: flex; flex-direction: column; translate: 0 calc(var(--d, 0) * -1em); transition: translate 1000ms var(--dbh-meds-spring), width 400ms var(--dbh-meds-ease), opacity 300ms; transition-delay: calc(var(--k) * 80ms); width: 0.6em; }
  .dbh-meds-dcol span { display: block; height: 1em; text-align: center; }
  .dbh-meds-dcol[data-off] { width: 0; opacity: 0; }
  .dbh-meds-pct { font-size: 0.42em; margin: 0.12em 0 0 0.06em; color: var(--dbh-meds-muted); }
  .dbh-meds-herot { display: grid; gap: 4px; min-width: 0; }
  .dbh-meds-h { font-size: clamp(14px, 0.6rem + 0.8cqi, 17px); font-weight: 560; line-height: 1.3; color: var(--dbh-meds-ink); }
  .dbh-meds-h em { font-style: normal; color: var(--dbh-meds-accent); }
  .dbh-meds-kpis { display: flex; gap: 22px; }
  .dbh-meds-kpis div { display: grid; gap: 1px; }
  .dbh-meds-kpis dt { font-size: 11px; color: var(--dbh-meds-muted); white-space: nowrap; }
  .dbh-meds-kpis dd { font: 650 20px/1.15 var(--dbh-meds-round); font-variant-numeric: tabular-nums; letter-spacing: -0.02em; }
  .dbh-meds-kpis dd small { font-size: 12px; font-weight: 500; color: var(--dbh-meds-faint); margin-left: 2px; }
  .dbh-meds-kpis dd[data-tone="bad"] { color: var(--dbh-meds-miss); }
  .dbh-meds-seg { display: inline-flex; gap: 2px; padding: 3px; border-radius: 10px; background: var(--dbh-meds-sunk); }
  .dbh-meds-seg button { height: 28px; padding: 0 11px; border-radius: 7px; font-size: 12.5px; font-weight: 600; color: var(--dbh-meds-muted); transition: background-color 150ms, color 150ms; }
  .dbh-meds-seg button:hover { color: var(--dbh-meds-ink); }
  .dbh-meds-seg [aria-checked="true"] { background: var(--dbh-meds-raise); color: var(--dbh-meds-ink); }

  .dbh-meds-view { min-height: 0; padding: 0 20px 18px; }
  .dbh-meds-card { position: relative; min-width: 0; min-height: 0; border-radius: 14px; background: var(--dbh-meds-card); box-shadow: inset 0 0 0 1px var(--dbh-meds-line); padding: 14px 16px; }
  .dbh-meds-cardhead { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px 12px; margin-bottom: 10px; }
  .dbh-meds-cardhead h3 { font-size: 13px; font-weight: 650; }
  .dbh-meds-note { font-size: 11.5px; color: var(--dbh-meds-faint); }

  /* ---------- dose grid ---------- */
  .dbh-meds-log { display: grid; gap: 12px; grid-template-columns: minmax(0, 1fr) clamp(208px, 22cqi, 250px); }
  .dbh-meds-gcard { display: grid; padding: 12px 10px 12px 14px; }
  .dbh-meds-gscroll { min-height: 0; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dbh-meds-line2) transparent; }
  .dbh-meds-grid { display: grid; grid-template-columns: 128px repeat(var(--n, 28), minmax(13px, 1fr)); column-gap: 3px; row-gap: 6px; align-content: start; min-width: calc(128px + var(--n, 28) * 16px); padding: 2px 4px 2px 2px; }
  .dbh-meds-row { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; align-items: center; border-radius: 10px; transition: opacity 220ms var(--dbh-meds-ease); }
  .dbh-meds-grid[data-focus] .dbh-meds-row[data-med]:not([data-focus]) { opacity: 0.28; }
  .dbh-meds-dh { display: grid; justify-items: center; line-height: 1.1; padding-bottom: 2px; font: 500 10px var(--dbh-meds-mono); color: var(--dbh-meds-faint); font-variant-numeric: tabular-nums; }
  .dbh-meds-dh b { font-weight: 600; color: var(--dbh-meds-muted); font-size: 10.5px; }
  .dbh-meds-dh[data-we] b { color: var(--dbh-meds-ink); }
  .dbh-meds-dh[data-today] { color: var(--dbh-meds-accent); }
  .dbh-meds-dh[data-today] b { color: var(--dbh-meds-bg); background: var(--dbh-meds-accent); border-radius: 5px; padding: 0 3px; }
  .dbh-meds-rh { position: sticky; left: 0; z-index: 2; align-self: stretch; display: grid; grid-template-columns: 4px 1fr; column-gap: 8px; align-content: center; align-items: center; line-height: 1.2; min-width: 0; padding-right: 8px; background: var(--dbh-meds-card); }
  .dbh-meds-row:first-child > :first-child { position: sticky; left: 0; z-index: 2; align-self: stretch; background: var(--dbh-meds-card); }
  .dbh-meds-rh::before { content: ""; grid-row: 1 / 3; width: 4px; height: 26px; border-radius: 2px; background: var(--mc); }
  .dbh-meds-rh b { font-size: 12.5px; font-weight: 620; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dbh-meds-rh small { font: 500 10.5px var(--dbh-meds-mono); color: var(--dbh-meds-faint); white-space: nowrap; }
  .dbh-meds-cell { position: relative; height: 28px; border-radius: 99px; outline-offset: 1px; cursor: default; animation: dbh-meds-in 420ms var(--dbh-meds-spring) both; animation-delay: calc(var(--c) * 14ms + var(--r) * 40ms); transition: background-color 200ms, box-shadow 200ms, scale 220ms var(--dbh-meds-spring); }
  .dbh-meds-cell[data-s="taken"] { background: var(--mc); }
  .dbh-meds-cell[data-s="late"] { background: repeating-linear-gradient(135deg, var(--mc) 0 3px, color-mix(in oklch, var(--mc) 28%, transparent) 3px 6px); }
  .dbh-meds-cell[data-s="missed"] { background: color-mix(in oklch, var(--dbh-meds-miss) 20%, transparent); box-shadow: inset 0 0 0 1.5px var(--dbh-meds-miss); }
  .dbh-meds-cell[data-s="up"] { background: transparent; box-shadow: inset 0 0 0 1.5px var(--dbh-meds-line2); }
  .dbh-meds-drow { margin-top: 10px; padding-top: 12px; border-top: 1px dashed var(--dbh-meds-line2); border-radius: 0; align-items: end; }
  .dbh-meds-drow .dbh-meds-rh::before { background: var(--dbh-meds-accent); }
  .dbh-meds-dbar { position: relative; height: clamp(64px, 14cqi, 150px); display: flex; flex-direction: column-reverse; border-radius: 5px; overflow: hidden; background: color-mix(in oklch, var(--dbh-meds-miss) 16%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dbh-meds-miss) 30%, transparent); cursor: default; }
  .dbh-meds-dbar[data-full] { background: var(--dbh-meds-line); box-shadow: none; }
  .dbh-meds-dbar i { flex: none; width: 100%; transform-origin: bottom; transition: height 600ms var(--dbh-meds-spring); animation: dbh-meds-grow 700ms var(--dbh-meds-ease) both; animation-delay: calc(var(--c) * 16ms + 320ms); }
  .dbh-meds-dbar i[data-k="t"] { height: calc(var(--t, 0) * 100%); background: var(--dbh-meds-accent); }
  .dbh-meds-dbar i[data-k="l"] { height: calc(var(--l, 0) * 100%); background: repeating-linear-gradient(135deg, var(--dbh-meds-accent) 0 3px, color-mix(in oklch, var(--dbh-meds-accent) 25%, transparent) 3px 6px); }
  .dbh-meds-dbar:hover { box-shadow: 0 0 0 2px var(--dbh-meds-ink); }
  .dbh-meds-grid[data-focus] .dbh-meds-drow { opacity: 0.28; }
  .dbh-meds-cell[data-s="none"] { background: radial-gradient(circle, var(--dbh-meds-line2) 1.5px, transparent 2px); }
  .dbh-meds-cell:is([data-s="taken"], [data-s="late"], [data-s="missed"]) { cursor: pointer; }
  .dbh-meds-cell:is([data-s="taken"], [data-s="late"], [data-s="missed"]):hover { scale: 1.12; }
  .dbh-meds-cell[data-edited]::after { content: ""; position: absolute; top: -2px; right: -2px; width: 6px; height: 6px; border-radius: 50%; background: var(--dbh-meds-ink); box-shadow: 0 0 0 2px var(--dbh-meds-card); }
  .dbh-meds-cell:focus-visible { outline-offset: 2px; border-radius: 99px; }
  .dbh-meds-tip { position: absolute; top: 0; left: 0; z-index: 5; min-width: 180px; max-width: 240px; padding: 9px 12px; border-radius: 10px; pointer-events: none; background: color-mix(in oklch, var(--dbh-meds-bg), var(--dbh-meds-ink) 14%); box-shadow: 0 0 0 1px var(--dbh-meds-line2), 0 16px 34px oklch(0 0 0 / 0.45); font-size: 12px; line-height: 1.45; }
  .dbh-meds-tip b { display: flex; align-items: center; gap: 7px; font-weight: 650; }
  .dbh-meds-tip b::before { content: ""; width: 8px; height: 14px; border-radius: 99px; background: var(--mc); }
  .dbh-meds-tip span { display: block; font: 500 11px var(--dbh-meds-mono); color: var(--dbh-meds-muted); font-variant-numeric: tabular-nums; }
  .dbh-meds-tip em { display: block; margin-top: 4px; font-style: normal; font-weight: 600; }
  .dbh-meds-tip em[data-s="late"] { color: var(--dbh-meds-thy); }
  .dbh-meds-tip em[data-s="missed"] { color: var(--dbh-meds-miss); }
  .dbh-meds-tip small { display: block; margin-top: 4px; font-size: 10.5px; color: var(--dbh-meds-faint); }

  /* per-medicine summary */
  .dbh-meds-sum { display: grid; grid-template-rows: auto minmax(0, 1fr); }
  .dbh-meds-mlist { min-height: 0; overflow: auto; display: grid; align-content: start; gap: 4px; scrollbar-width: thin; }
  .dbh-meds-mlist li { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 5px 8px; padding: 9px 10px; border-radius: 10px; cursor: pointer; transition: background-color 150ms; animation: dbh-meds-rise 500ms var(--dbh-meds-ease) both; animation-delay: calc(var(--i) * 60ms + 200ms); }
  .dbh-meds-mlist li:hover, .dbh-meds-mlist li:focus-visible { background: var(--dbh-meds-raise); }
  .dbh-meds-mlist li > span { display: grid; line-height: 1.2; min-width: 0; }
  .dbh-meds-mlist b { font-size: 12.5px; font-weight: 640; }
  .dbh-meds-mlist small { font-size: 11px; color: var(--dbh-meds-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dbh-meds-mlist strong { display: grid; justify-items: end; font: 650 15px var(--dbh-meds-round); font-variant-numeric: tabular-nums; text-align: right; }
  .dbh-meds-mlist strong small { display: block; font: 500 10.5px var(--dbh-meds-mono); text-align: right; }
  .dbh-meds-mbar { grid-column: 1 / -1; display: flex; height: 6px; border-radius: 99px; overflow: hidden; background: color-mix(in oklch, var(--dbh-meds-miss) 30%, var(--dbh-meds-sunk)); }
  .dbh-meds-mbar i { flex: 0 0 auto; width: calc(var(--v) * 100%); transition: width 700ms var(--dbh-meds-spring); }
  .dbh-meds-mbar i:first-child { background: var(--mc); }
  .dbh-meds-mbar i:last-child { background: repeating-linear-gradient(135deg, var(--mc) 0 3px, color-mix(in oklch, var(--mc) 30%, var(--dbh-meds-sunk)) 3px 6px); }

  /* ---------- timing ---------- */
  .dbh-meds-time { display: grid; }
  .dbh-meds-tcard { display: grid; grid-template-rows: auto minmax(0, 1fr); }
  .dbh-meds-chips { display: flex; flex-wrap: wrap; gap: 4px; }
  .dbh-meds-chips button { display: inline-flex; align-items: center; gap: 7px; height: 28px; padding: 0 11px 0 9px; border-radius: 99px; font-size: 12px; font-weight: 580; color: var(--dbh-meds-muted); box-shadow: inset 0 0 0 1px var(--dbh-meds-line); transition: background-color 150ms, color 150ms, box-shadow 150ms; }
  .dbh-meds-chips button::before { content: ""; width: 7px; height: 13px; border-radius: 99px; background: var(--mc); }
  .dbh-meds-chips button:hover { color: var(--dbh-meds-ink); }
  .dbh-meds-chips [aria-checked="true"] { color: var(--dbh-meds-ink); background: var(--dbh-meds-raise); box-shadow: inset 0 0 0 1px var(--dbh-meds-line2); }
  .dbh-meds-tchart { position: relative; min-height: 0; }
  .dbh-meds-tchart svg { width: 100%; height: 100%; overflow: visible; }
  .dbh-meds-tchart text { font: 500 10.5px var(--dbh-meds-mono); fill: var(--dbh-meds-faint); font-variant-numeric: tabular-nums; }
