const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const uid = Math.random().toString(36).slice(2, 7);
$$('[id]').forEach(el => { el.id += '-' + uid; });
$$('[aria-controls], [aria-labelledby]').forEach(el => ['aria-controls', 'aria-labelledby'].forEach(a => {
  if (el.hasAttribute(a)) el.setAttribute(a, el.getAttribute(a) + '-' + uid);
}));

const rng = seed => () => {
  seed |= 0; seed = seed + 0x6D2B79F5 | 0;
  let t = Math.imul(seed ^ seed >>> 15, 1 | seed);
  t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
  return ((t ^ t >>> 14) >>> 0) / 4294967296;
};
const pad = n => String(Math.floor(n)).padStart(2, '0');
const hm = m => pad(((m % 1440) + 1440) % 1440 / 60) + ':' + pad(((m % 60) + 60) % 60);
const DAY = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const N = 28, TODAY = 27, NOW = 14 * 60 + 20;                       // Fri 4 Sep → Thu 1 Oct, 14:20
const dateOf = d => new Date(2026, 8, 4 + d);
const fmtD = d => `${DAY[dateOf(d).getDay()]} ${dateOf(d).getDate()} ${MON[dateOf(d).getMonth()]}`;
const late = m => m >= 60 ? `${Math.floor(m / 60)} h ${pad(m % 60)} min` : `${m} min`;

/* ---------- medicines (invented) and their dose slots ---------- */
const MEDS = [
  { id: 'thy', name: 'Thyrovane', dose: '50 mcg', note: 'before breakfast', times: [390], carry: 87, fills: [], miss: [0.03], late: [0.07] },
  { id: 'ost', name: 'Ostavel', dose: '70 mg', note: 'weekly, Mondays', times: [420], weekly: 1, carry: 4, fills: [], miss: [0], late: [0.25] },
  { id: 'cor', name: 'Corvalex', dose: '10 mg', note: 'with breakfast', times: [480], carry: 17, fills: [{ d: 20, qty: 30 }], miss: [0.03], late: [0.06] },
  { id: 'glu', name: 'Glucatrin', dose: '500 mg', note: 'with breakfast and dinner', times: [480, 1200], carry: 46, fills: [{ d: 23, qty: 60 }], miss: [0.04, 0.13], late: [0.08, 0.2] },
  { id: 'lum', name: 'Lumirest', dose: '5 mg', note: 'at bedtime', times: [1320], carry: 6, fills: [{ d: 6, qty: 30 }], miss: [0.05], late: [0.28] }
];
const SLOTS = [];
MEDS.forEach(m => m.times.forEach((t, k) => SLOTS.push({ id: m.id + k, med: m, t, k })));
SLOTS.sort((a, b) => a.t - b.t || MEDS.indexOf(a.med) - MEDS.indexOf(b.med));
const scheduled = (slot, d) => !slot.med.weekly || dateOf(d).getDay() === slot.med.weekly;

const r = rng(904);
const LOG = new Map();
for (let d = 0; d < N; d++) {
  const dow = dateOf(d).getDay();
  SLOTS.forEach(slot => {
    const key = slot.id + ':' + d;
    if (!scheduled(slot, d)) { LOG.set(key, { s: 'none' }); return; }
    if (d === TODAY && slot.t > NOW) { LOG.set(key, { s: 'up' }); return; }
    let pm = slot.med.miss[slot.k], pl = slot.med.late[slot.k];
    if (slot.t >= 1200 && (dow === 5 || dow === 6)) pm += 0.18;
    let s = r() < pm ? 'missed' : r() < pl ? 'late' : 'taken';
    if ((d === 14 || d === 15) && slot.t >= 1200) s = 'missed';          // weekend away, evening doses left at home
    const off = s === 'late' ? Math.round(65 + r() * 150) : Math.round(-20 + r() * 70);
    LOG.set(key, { s, off });
  });
}
// supply: a dose cannot have been taken with nothing on hand
MEDS.forEach(m => {
  let pills = m.carry;
  for (let d = 0; d < N; d++) {
    m.fills.forEach(f => { if (f.d === d) pills += f.qty; });
    SLOTS.filter(s => s.med === m).forEach(slot => {
      const e = LOG.get(slot.id + ':' + d);
      if (e.s !== 'taken' && e.s !== 'late') return;
      if (pills > 0) pills--; else { e.s = 'missed'; e.why = 'none on hand'; }
    });
  }
});
LOG.forEach(e => { e.orig = e.s; e.origOff = e.off; });
const due = s => s === 'taken' || s === 'late' || s === 'missed';

/* ---------- metrics, all from LOG ---------- */
let range = 28;
function metrics() {
  const d0 = N - range;
  const tally = () => ({ taken: 0, late: 0, missed: 0 });
  const all = tally(), bySlot = {}, byMed = {};
  SLOTS.forEach(s => { bySlot[s.id] = tally(); byMed[s.med.id] = byMed[s.med.id] || tally(); });
  for (let d = d0; d < N; d++) SLOTS.forEach(slot => {
    const s = LOG.get(slot.id + ':' + d).s;
    if (!due(s)) return;
    all[s]++; bySlot[slot.id][s]++; byMed[slot.med.id][s]++;
  });
  let streak = 0;
  for (let d = TODAY; d >= 0; d--) {
    const day = SLOTS.map(sl => LOG.get(sl.id + ':' + d).s).filter(due);
    if (day.includes('missed')) break;
    if (day.length) streak++;
  }
  return { all, bySlot, byMed, streak };
}

/* ---------- odometer ---------- */
const odow = $('.dbh-meds-odow');
odow.innerHTML = [0, 1, 2].map(k => `<span class="dbh-meds-dcol" style="--k:${k}">${'0123456789'.split('').map(n => `<span>${n}</span>`).join('')}</span>`).join('');
const cols = $$('.dbh-meds-dcol', odow);
let odoReady = false;
function setOdo(v) {
  const apply = () => {
    const s = String(v).padStart(3, '0');
    cols.forEach((c, k) => { c.style.setProperty('--d', s[k]); c.toggleAttribute('data-off', (k === 0 && v < 100) || (k === 1 && v < 10)); });
  };
  $('.dbh-meds-odo').setAttribute('aria-label', `Adherence ${v} percent`);
  if (odoReady || reduce) apply(); else setTimeout(() => { if (!root.isConnected) return; apply(); }, 150);
  odoReady = true;
}

/* ---------- head ---------- */
const K = k => $(`[data-k="${k}"]`);
function paintHead(m) {
  const a = m.all, n = a.taken + a.late + a.missed;
  const pct = n ? Math.round((a.taken + a.late) / n * 100) : 0;
  setOdo(pct);
  K('range').textContent = `Doses taken · ${fmtD(N - range)} – ${fmtD(TODAY)}`;
  const worst = SLOTS.map(s => [s, m.bySlot[s.id].missed]).sort((x, y) => y[1] - x[1])[0];
  K('headline').innerHTML = `<em>${a.taken + a.late}</em> of ${n} due doses taken, ${a.late} more than an hour late.` +
    (worst[1] ? ` ${worst[0].t >= 1080 ? 'Evening' : 'Morning'} ${worst[0].med.name} is missed most often (${worst[1]}×).` : ' Nothing missed in this window.');
  K('ontime').innerHTML = n ? `${Math.round(a.taken / n * 100)}<small>%</small>` : '—';
  const md = K('missed');
  md.textContent = a.missed;
  md.dataset.tone = a.missed > 0 ? 'bad' : '';
  K('streak').innerHTML = `${m.streak}<small>${m.streak === 1 ? 'day' : 'days'}</small>`;
}

/* ---------- dose grid ---------- */
const grid = $('.dbh-meds-grid'), gcard = $('.dbh-meds-gcard'), tip = $('.dbh-meds-tip', gcard);
let focus = { r: SLOTS.length - 1, c: N - 1 };
function cellLabel(slot, d, e) {
  const base = `${slot.med.name} ${slot.med.dose}, ${fmtD(d)} ${hm(slot.t)}`;
  return e.s === 'taken' ? `${base}: taken` : e.s === 'late' ? `${base}: taken late` : e.s === 'missed' ? `${base}: missed` : e.s === 'up' ? `${base}: due later today` : `${base}: not scheduled`;
}
function renderGrid() {
  const d0 = N - range;
  grid.style.setProperty('--n', range);
  let out = `<div class="dbh-meds-row" role="row"><span role="columnheader" class="dbh-meds-dh" style="justify-items:start;padding-left:2px"><b>${MON[dateOf(d0).getMonth()]}${dateOf(d0).getMonth() !== dateOf(TODAY).getMonth() ? ' – ' + MON[dateOf(TODAY).getMonth()] : ''}</b>&nbsp;</span>`;
  for (let d = d0; d < N; d++) {
    const dt = dateOf(d), we = dt.getDay() === 0 || dt.getDay() === 6;
    out += `<span role="columnheader" class="dbh-meds-dh"${we ? ' data-we' : ''}${d === TODAY ? ' data-today' : ''} aria-label="${fmtD(d)}"><b>${dt.getDate()}</b>${DAY[dt.getDay()][0]}</span>`;
  }
  out += '</div>';
  SLOTS.forEach((slot, ri) => {
    out += `<div class="dbh-meds-row" role="row" data-med="${slot.med.id}" data-slot="${slot.id}"><span class="dbh-meds-rh" role="rowheader"><b>${slot.med.name}<span class="dbh-meds-rdose"> ${slot.med.dose}</span></b><small>${slot.med.weekly ? 'Mon ' : ''}${hm(slot.t)}</small></span>`;
    for (let d = d0; d < N; d++) {
      const e = LOG.get(slot.id + ':' + d);
      out += `<span class="dbh-meds-cell" role="gridcell" data-r="${ri}" data-d="${d}" data-s="${e.s}"${e.s !== e.orig ? ' data-edited' : ''} tabindex="-1" style="--c:${d - d0};--r:${ri}" aria-label="${cellLabel(slot, d, e)}"></span>`;
    }
    out += '</div>';
  });
  /* one more subgrid row: each day's share of due doses taken, on the same columns as the dots above */
  out += `<div class="dbh-meds-row dbh-meds-drow" role="row"><span class="dbh-meds-rh" role="rowheader"><b>Each day</b><small>taken of due</small></span>`;
  for (let d = d0; d < N; d++) out += `<span class="dbh-meds-dbar" role="gridcell" data-day="${d}" style="--c:${d - d0}"><i data-k="t"></i><i data-k="l"></i></span>`;
  out += '</div>';
  grid.innerHTML = out;
  paintDaily();
  const sc = $('.dbh-meds-gscroll');
  sc.scrollLeft = sc.scrollWidth;                     // the most recent days sit at the right edge
  focus.c = Math.max(d0, Math.min(N - 1, focus.c));
  const fc = cellAt(focus.r, focus.c);
  if (fc) fc.tabIndex = 0;
}
function dayCount(d) {
  const c = { taken: 0, late: 0, missed: 0, up: 0, miss: [] };
  SLOTS.forEach(sl => { const s = LOG.get(sl.id + ':' + d).s; if (c[s] === undefined) return; c[s]++; if (s === 'missed') c.miss.push(sl); });
  c.n = c.taken + c.late + c.missed;
  return c;
}
function paintDaily() {
  $$('.dbh-meds-dbar', grid).forEach(el => {
    const d = +el.dataset.day, c = dayCount(d);
    el.style.setProperty('--t', c.n ? (c.taken / c.n).toFixed(3) : 0);
    el.style.setProperty('--l', c.n ? (c.late / c.n).toFixed(3) : 0);
    el.toggleAttribute('data-full', c.n > 0 && c.missed === 0);
    el.setAttribute('aria-label', `${fmtD(d)}: ${c.taken + c.late} of ${c.n} due doses taken, ${c.late} late, ${c.missed} missed${c.up ? `, ${c.up} due later` : ''}`);
  });
}
function showDayTip(el) {
  const d = +el.dataset.day, c = dayCount(d);
  delete tip.dataset.med;
  tip.innerHTML = `<b>${fmtD(d)}${d === TODAY ? ' · today' : ''}</b><span>${c.taken + c.late} of ${c.n} due doses taken${c.up ? ` · ${c.up} still to come` : ''}</span>` +
    (c.late ? `<em data-s="late">${c.late} more than an hour late</em>` : '') +
    (c.missed ? `<em data-s="missed">Missed: ${c.miss.map(sl => `${sl.med.name} ${hm(sl.t)}`).join(', ')}</em>` : `<em data-s="taken">Nothing missed</em>`);
  tip.hidden = false;
  const cr = gcard.getBoundingClientRect(), br = el.getBoundingClientRect(), tw = tip.offsetWidth, th = tip.offsetHeight;
  let x = br.left - cr.left + br.width / 2 - tw / 2, y = br.top - cr.top - th - 8;
  x = Math.max(6, Math.min(cr.width - tw - 6, x));
  tip.style.translate = `${x.toFixed(0)}px ${y.toFixed(0)}px`;
}
const cellAt = (ri, d) => $(`.dbh-meds-cell[data-r="${ri}"][data-d="${d}"]`, grid);
function tipHTML(slot, d, e) {
  let em, extra = '';
  if (e.s === 'taken') em = `Taken ${hm(slot.t + e.off)} · ${e.off < 0 ? Math.abs(e.off) + ' min early' : e.off === 0 ? 'on the dot' : e.off + ' min after'}`;
  else if (e.s === 'late') em = `Taken ${hm(slot.t + e.off)} · ${late(e.off)} late`;
  else if (e.s === 'missed') em = 'Missed' + (e.why ? ' · none on hand' : '');
  else if (e.s === 'up') em = `Due at ${hm(slot.t)}`;
  else em = 'Not scheduled · taken on Mondays';
  if (due(e.s)) extra = `<small>${e.s !== e.orig ? 'Corrected in this session · ' : ''}Enter or click to change</small>`;
  return `<b>${slot.med.name} ${slot.med.dose}</b><span>${fmtD(d)} · scheduled ${hm(slot.t)}</span><em data-s="${e.s}">${em}</em>${extra}`;
}
function showTip(cell) {
  const slot = SLOTS[+cell.dataset.r], d = +cell.dataset.d, e = LOG.get(slot.id + ':' + d);
  tip.dataset.med = slot.med.id;
  tip.innerHTML = tipHTML(slot, d, e);
  tip.hidden = false;
  const cr = gcard.getBoundingClientRect(), br = cell.getBoundingClientRect(), tw = tip.offsetWidth, th = tip.offsetHeight;
  let x = br.left - cr.left + br.width / 2 - tw / 2, y = br.top - cr.top - th - 8;
  x = Math.max(6, Math.min(cr.width - tw - 6, x));
  if (y < 4) y = br.bottom - cr.top + 8;
  tip.style.translate = `${x.toFixed(0)}px ${y.toFixed(0)}px`;
}
const hideTip = () => { tip.hidden = true; };
grid.addEventListener('pointerover', e => { const c = e.target.closest('.dbh-meds-cell'); if (c) showTip(c); else { const b = e.target.closest('.dbh-meds-dbar'); if (b) showDayTip(b); } });
grid.addEventListener('pointerleave', () => { if (!grid.contains(document.activeElement)) hideTip(); });
grid.addEventListener('focusin', e => { const c = e.target.closest('.dbh-meds-cell'); if (c) showTip(c); });
grid.addEventListener('focusout', hideTip);
const CYCLE = { taken: 'late', late: 'missed', missed: 'taken' };
function edit(cell) {
  const slot = SLOTS[+cell.dataset.r], d = +cell.dataset.d, e = LOG.get(slot.id + ':' + d);
  if (!due(e.s)) return;
  e.s = CYCLE[e.s];
  if (e.s === 'taken') e.off = e.origOff != null && e.origOff < 60 ? e.origOff : 10;
  if (e.s === 'late') e.off = e.origOff != null && e.origOff >= 60 ? e.origOff : 95;
  if (e.s !== 'missed') delete e.why; else if (e.orig === 'missed' && e.origWhy) e.why = e.origWhy;
  cell.dataset.s = e.s;
  cell.toggleAttribute('data-edited', e.s !== e.orig);
  cell.setAttribute('aria-label', cellLabel(slot, d, e));
  if (!reduce) cell.animate([{ scale: 0.6 }, { scale: 1 }], { duration: 420, easing: 'cubic-bezier(.3,1.6,.5,1)' });
  showTip(cell);
  refresh();
}
LOG.forEach(e => { e.origWhy = e.why; });
grid.addEventListener('click', e => { const c = e.target.closest('.dbh-meds-cell'); if (c) { moveFocus(+c.dataset.r, +c.dataset.d, false); edit(c); } });
function moveFocus(ri, d, doFocus = true) {
  const old = cellAt(focus.r, focus.c);
  if (old) old.tabIndex = -1;
  focus = { r: ri, c: d };
  const c = cellAt(ri, d);
  if (!c) return;
  c.tabIndex = 0;
