grid.addEventListener('keydown', e => {
  const c = e.target.closest('.dbh-meds-cell');
  if (!c) return;
  const d0 = N - range;
  let { r: ri, c: d } = { r: +c.dataset.r, c: +c.dataset.d };
  if (e.key === 'ArrowRight') d++; else if (e.key === 'ArrowLeft') d--;
