mlist.innerHTML = MEDS.map((med, i) => `<li data-med="${med.id}" tabindex="0" style="--i:${i}">
  <span><b>${med.name} ${med.dose}</b><small>${med.times.map(hm).join(' · ')} · ${med.note}</small></span>
  <strong><span data-p></span><small data-n></small></strong>
  <span class="dbh-meds-mbar" aria-hidden="true"><i></i><i></i></span></li>`).join('');
function paintList(m) {
