  $$('.dbh-meds-row[data-med]', grid).forEach(r => r.toggleAttribute('data-focus', r.dataset.med === id));
}

/* ---------- timing ---------- */
let tslot = 'glu1';
const chips = $('.dbh-meds-chips');
chips.innerHTML = SLOTS.map(s => `<button type="button" role="radio" data-med="${s.med.id}" data-slot="${s.id}" aria-checked="${s.id === tslot}" tabindex="${s.id === tslot ? 0 : -1}">${s.med.name} ${hm(s.t)}</button>`).join('');
const tchart = $('.dbh-meds-tchart'), tsvg = $('svg', tchart), tip2 = $('.dbh-meds-tip2'), tcard = $('.dbh-meds-tcard');
function renderTiming() {
  const slot = SLOTS.find(s => s.id === tslot), d0 = N - range;
  tcard.dataset.med = slot.med.id;
  const W = tchart.clientWidth, H = tchart.clientHeight;
  if (W < 60 || H < 60) return;
  const L = 52, Rm = 14, top = 10, bot = 46;
  const days = [];
  for (let d = d0; d < N; d++) if (scheduled(slot, d)) days.push(d);
  const pts = days.map(d => ({ d, e: LOG.get(slot.id + ':' + d) }));
  const taken = pts.filter(p => p.e.s === 'taken' || p.e.s === 'late');
  const yMax = Math.max(180, Math.ceil((Math.max(0, ...taken.map(p => p.e.off)) + 30) / 60) * 60), yMin = -60;
  const pw = W - L - Rm, ph = H - top - bot;
  const x = d => L + (d - d0 + 0.5) / range * pw;
  const y = v => top + (yMax - v) / (yMax - yMin) * ph;
  let out = `<rect class="dbh-meds-win" x="${L}" width="${pw}" y="${y(60).toFixed(1)}" height="${(y(-60) - y(60)).toFixed(1)}" rx="6"/>`;
  out += `<text class="dbh-meds-tl" x="${W - Rm - 6}" y="${(y(60) + 13).toFixed(1)}" text-anchor="end" style="fill:var(--dbh-meds-accent)">within the hour</text>`;
  for (let v = yMin; v <= yMax; v += 60) out += `<line class="dbh-meds-grid2" x1="${L}" x2="${W - Rm}" y1="${y(v).toFixed(1)}" y2="${y(v).toFixed(1)}"/><text x="${L - 8}" y="${(y(v) + 3.5).toFixed(1)}" text-anchor="end">${hm(slot.t + v)}</text>`;
  out += `<line class="dbh-meds-zero" x1="${L}" x2="${W - Rm}" y1="${y(0).toFixed(1)}" y2="${y(0).toFixed(1)}"/>`;
  const step = range <= 7 ? 1 : range <= 14 ? 2 : 4;
  days.forEach((d, k) => { if (slot.med.weekly || (N - 1 - d) % step === 0) out += `<text x="${x(d).toFixed(1)}" y="${H - 6}" text-anchor="middle">${dateOf(d).getDate()} ${MON[dateOf(d).getMonth()]}</text>`; });
  const missY = top + ph + 18;
  out += `<text class="dbh-meds-tl" x="${L - 8}" y="${missY + 3.5}" text-anchor="end" style="fill:var(--dbh-meds-miss)">missed</text>`;
  if (taken.length > 1) out += `<path class="dbh-meds-tline" pathLength="1" d="${taken.map((p, k) => (k ? 'L' : 'M') + x(p.d).toFixed(1) + ',' + y(p.e.off).toFixed(1)).join('')}"/>`;
  pts.forEach((p, k) => {
    if (p.e.s === 'missed') out += `<g data-d="${p.d}"><rect class="dbh-meds-xhit" x="${(x(p.d) - 8).toFixed(1)}" y="${missY - 8}" width="16" height="16"/><path class="dbh-meds-x" d="M${(x(p.d) - 4).toFixed(1)},${missY - 4}l8,8m0,-8l-8,8"/></g>`;
    else if (p.e.s === 'taken' || p.e.s === 'late') out += `<circle class="dbh-meds-dot" data-d="${p.d}" data-s="${p.e.s}" style="--i:${k}" cx="${x(p.d).toFixed(1)}" cy="${y(p.e.off).toFixed(1)}" r="5"/>`;
  });
  tsvg.setAttribute('viewBox', `0 0 ${W} ${H}`);
