  const offs = taken.map(p => p.e.off).sort((a, b) => a - b);
  const med = offs.length ? offs[offs.length >> 1] : 0;
  const within = taken.filter(p => p.e.off <= 60 && p.e.off >= -60).length;
  K('tstat').textContent = offs.length ? `typically ${Math.abs(med)} min ${med < 0 ? 'early' : 'after'} · ${Math.round(within / pts.filter(p => due(p.e.s)).length * 100)}% within the hour` : 'no doses taken in this window';
}
tsvg.addEventListener('pointerover', e => {
  const t = e.target.closest('[data-d]');
  if (!t) { tip2.hidden = true; return; }
  const slot = SLOTS.find(s => s.id === tslot), d = +t.dataset.d;
  tip2.dataset.med = slot.med.id;
  tip2.innerHTML = tipHTML(slot, d, LOG.get(slot.id + ':' + d)).replace(/<small>.*<\/small>/, '');
  tip2.hidden = false;
