tsvg.addEventListener('pointerleave', () => { tip2.hidden = true; });

/* ---------- refills: on-hand supply, past from the log and projected forward ---------- */
const flist = $('.dbh-meds-flist');
const SPAN = 58;                                            // 4 Sep → 31 Oct
function supply(m) {
  const slots = SLOTS.filter(s => s.med === m);
  const start = [], gap = [];
  let pills = m.carry, out = -1;
  for (let d = 0; d < SPAN; d++) {
    m.fills.forEach(f => { if (f.d === d) pills += f.qty; });
    const need = slots.filter(s => scheduled(s, d)).length;
    start.push(pills);
    if (d < N && need && pills < need) gap.push(d);
    slots.forEach(s => {
      if (!scheduled(s, d)) return;
      const st = d < N ? LOG.get(s.id + ':' + d).s : 'up';
      const takes = st === 'taken' || st === 'late' || (st === 'up');
      if (!takes) return;
      if (pills > 0) pills--; else if (out < 0 && (d > TODAY || st === 'up')) out = d;
