    m.fills.forEach(f => { if (f.d === d) now += f.qty; });
    slots.forEach(s => { const st = LOG.get(s.id + ':' + d).s; if ((st === 'taken' || st === 'late') && now > 0) now--; });
  }
  const covered = (() => { let c = 0; for (let d = N - range; d < N; d++) if (!gap.includes(d)) c++; return c; })();
