  const lis = $$('li', flist);
  const widths = lis.map(li => $('svg', li).getBoundingClientRect().width);
  lis.forEach((li, i) => {
    const m = MEDS[i], s = supply(m), svg = $('svg', li), W = Math.max(120, widths[i]), H = 54;
    const top = 6, base = H - 16, max = Math.max(...s.start, 1);
    const x = d => d / (SPAN - 1) * W, y = v => base - v / max * (base - top);
    let past = `M0,${base}`, line = '';
    for (let d = 0; d <= TODAY; d++) { past += `L${x(d).toFixed(1)},${y(s.start[d]).toFixed(1)}L${x(d + 1).toFixed(1)},${y(s.start[d]).toFixed(1)}`; line += `${d ? 'L' : 'M'}${x(d).toFixed(1)},${y(s.start[d]).toFixed(1)}L${x(d + 1).toFixed(1)},${y(s.start[d]).toFixed(1)}`; }
    past += `L${x(TODAY + 1).toFixed(1)},${base}Z`;
    let proj = '';
    for (let d = TODAY + 1; d < SPAN; d++) proj += `${d === TODAY + 1 ? 'M' : 'L'}${x(d).toFixed(1)},${y(s.start[d]).toFixed(1)}L${x(d + 1).toFixed(1)},${y(s.start[d]).toFixed(1)}`;
    let out = s.gap.map(d => `<rect class="dbh-meds-fgap" x="${x(d).toFixed(1)}" width="${(x(1)).toFixed(1)}" y="${top}" height="${base - top}"/>`).join('');
    out += `<path class="dbh-meds-farea" d="${past}"/><path class="dbh-meds-fpast" d="${line}"/><path class="dbh-meds-fproj" d="${proj}"/>`;
    out += `<line x1="0" x2="${W}" y1="${base}" y2="${base}" style="stroke:var(--dbh-meds-line)"/>`;
    m.fills.forEach(f => { out += `<path class="dbh-meds-fevent" d="M${x(f.d).toFixed(1)},${top - 2}l-4,-5h8z"/><text x="${(x(f.d) + 6).toFixed(1)}" y="${top + 2}">+${f.qty}</text>`; });
    out += `<line class="dbh-meds-ftoday" x1="${x(TODAY + 0.6).toFixed(1)}" x2="${x(TODAY + 0.6).toFixed(1)}" y1="${top - 4}" y2="${base + 3}"/>`;
    if (s.out >= 0) out += `<circle class="dbh-meds-fout" cx="${x(s.out).toFixed(1)}" cy="${base}" r="4"/>`;
    out += `<text x="0" y="${H - 2}">4 Sep</text><text x="${x(TODAY + 0.6).toFixed(1)}" y="${H - 2}" text-anchor="middle">today</text><text x="${W}" y="${H - 2}" text-anchor="end">31 Oct</text>`;
    svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
