    const perDay = m.weekly ? 1 / 7 : m.times.length;
    const daysLeft = s.out >= 0 ? s.out - TODAY : Infinity;
    const when = s.out >= 0 ? `${s.now ? 'runs out' : 'needed by'} ${fmtD(s.out)}` : 'covered past 31 Oct';
    const tone = s.out >= 0 && daysLeft <= 5 ? 'bad' : s.out >= 0 && daysLeft <= 12 ? 'warn' : '';
    $('.dbh-meds-fs', li).innerHTML = `<b>${s.now} on hand</b><small>${s.now ? Math.floor(s.now / perDay) + ' days of supply · ' : ''}${when}</small><em${tone ? ` data-tone="${tone}"` : ''}>${tone === 'bad' ? (s.now ? 'Refill now' : 'Out · refill now') : tone === 'warn' ? 'Refill this week' : `Covered ${Math.round(s.pdc * 100)}% of ${range} d`}</em>`;
