}
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  if (view === 'fill') renderFills();
  if (view === 'time') renderTiming();
});
ro.observe($('.dbh-meds-main'));

/* ---------- controls ---------- */
let view = 'log';
function roving(group, sel, attr, onPick) {
  const items = $$(sel, group);
  const pick = t => { items.forEach(x => { const o = x === t; x.setAttribute(attr, o); x.tabIndex = o ? 0 : -1; }); onPick(t); };
  group.addEventListener('click', e => { const t = e.target.closest(sel); if (t) pick(t); });
  group.addEventListener('keydown', e => {
    const i = items.indexOf(document.activeElement);
    if (i < 0) return;
    let j = -1;
    if (e.key === 'ArrowRight' || e.key === 'ArrowDown') j = (i + 1) % items.length;
    else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') j = (i - 1 + items.length) % items.length;
    if (j < 0) return;
    e.preventDefault(); items[j].focus(); pick(items[j]);
  });
