}
roving($('.dbh-meds-seg'), '[role="radio"]', 'aria-checked', t => { range = +t.dataset.n; renderGrid(); refresh(); });
const pickChip = roving(chips, '[role="radio"]', 'aria-checked', t => { tslot = t.dataset.slot; renderTiming(); });
const pickTab = roving($('.dbh-meds-nav'), '[role="tab"]', 'aria-selected', t => {
  view = t.dataset.view;
  $('.dbh-meds-log').hidden = view !== 'log';
  $('.dbh-meds-time').hidden = view !== 'time';
  $('.dbh-meds-fill').hidden = view !== 'fill';
  if (view === 'time') renderTiming();
  if (view === 'fill') renderFills();
});
function openTiming(medId) {
