}

renderGrid();
refresh();

css:
@keyframes dbh-beds-mop { to { background-position: 34px 0; } }
@keyframes dbh-beds-in { from { opacity: 0; scale: 0.6; } }
@keyframes dbh-beds-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbh-beds-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes dbh-beds-blink { 50% { opacity: 0.35; } }
@keyframes dbh-beds-cand { 0%, 100% { box-shadow: inset 0 0 0 1.5px var(--dbh-beds-avail), 0 0 0 0 color-mix(in oklch, var(--dbh-beds-avail) 60%, transparent); } 60% { box-shadow: inset 0 0 0 1.5px var(--dbh-beds-avail), 0 0 0 7px transparent; } }

.dbh-beds {
  /* re-theme with these */
  --dbh-beds-bg: oklch(0.2 0.013 170);
  --dbh-beds-ink: oklch(0.94 0.01 160);
  --dbh-beds-occ: oklch(0.62 0.065 240);
  --dbh-beds-dc: oklch(0.85 0.14 88);
  --dbh-beds-dirty: oklch(0.66 0.16 38);
  --dbh-beds-avail: oklch(0.8 0.16 150);
  /* derived */
  --dbh-beds-card: color-mix(in oklch, var(--dbh-beds-bg), var(--dbh-beds-ink) 5%);
  --dbh-beds-raise: color-mix(in oklch, var(--dbh-beds-bg), var(--dbh-beds-ink) 10%);
  --dbh-beds-sunk: color-mix(in oklch, var(--dbh-beds-bg), black 22%);
  --dbh-beds-line: color-mix(in oklch, var(--dbh-beds-ink) 10%, transparent);
  --dbh-beds-line2: color-mix(in oklch, var(--dbh-beds-ink) 20%, transparent);
  --dbh-beds-muted: color-mix(in oklch, var(--dbh-beds-ink) 60%, var(--dbh-beds-bg));
  --dbh-beds-faint: color-mix(in oklch, var(--dbh-beds-ink) 38%, var(--dbh-beds-bg));
  --dbh-beds-ease: cubic-bezier(0.2, 0.8, 0.2, 1);
  --dbh-beds-spring: linear(0, 0.02, 0.09 4%, 0.48 12%, 0.88 19%, 1.06 26%, 1.09 31%, 1.05 38%, 0.99 49%, 1);
  --dbh-beds-mono: ui-monospace, Menlo, Consolas, monospace;

  width: 100%;
  height: var(--dbh-beds-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dbh-beds-bg);
  color: var(--dbh-beds-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dbh-beds-avail);
  color-scheme: dark;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbh-beds-avail); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ol, & dl, & dd { list-style: none; margin: 0; padding: 0; }
  & fieldset { border: 0; margin: 0; padding: 0; min-width: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  [data-s="occ"] { --sc: var(--dbh-beds-occ); }
  [data-s="dc"] { --sc: var(--dbh-beds-dc); }
  [data-s="dirty"], [data-s="clean"] { --sc: var(--dbh-beds-dirty); }
  [data-s="avail"], [data-s="inbound"] { --sc: var(--dbh-beds-avail); }
  [data-s="block"] { --sc: var(--dbh-beds-faint); }

  .dbh-beds-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: 0.1em; text-transform: uppercase; color: var(--dbh-beds-muted); }
  .dbh-beds-app { display: grid; height: 100%; grid-template-columns: 214px minmax(0, 1fr); grid-template-areas: "side main"; }

  /* ---------- side ---------- */
  .dbh-beds-side { grid-area: side; min-height: 0; overflow: auto; display: flex; flex-direction: column; gap: 18px; padding: 18px 12px 14px; border-right: 1px solid var(--dbh-beds-line); background: var(--dbh-beds-sunk); scrollbar-width: thin; }
  .dbh-beds-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px; }
  .dbh-beds-brand svg { flex: none; width: 30px; height: 30px; padding: 5px; border-radius: 8px; background: color-mix(in oklch, var(--dbh-beds-avail) 15%, transparent); fill: none; stroke: var(--dbh-beds-avail); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  .dbh-beds-brand span { display: grid; line-height: 1.2; }
  .dbh-beds-brand b { font-size: 14.5px; font-weight: 680; letter-spacing: -0.01em; }
  .dbh-beds-brand small { font-size: 11px; color: var(--dbh-beds-muted); }
  .dbh-beds-units { display: grid; gap: 2px; }
  .dbh-beds-units button { display: grid; grid-template-columns: 1fr auto; gap: 4px 8px; padding: 8px 10px; border-radius: 9px; text-align: left; color: var(--dbh-beds-muted); transition: background-color 150ms, color 150ms; }
  .dbh-beds-units button:hover { color: var(--dbh-beds-ink); background: color-mix(in oklch, var(--dbh-beds-ink) 5%, transparent); }
  .dbh-beds-units [aria-selected="true"] { color: var(--dbh-beds-ink); background: var(--dbh-beds-raise); }
  .dbh-beds-units b { font-weight: 600; font-size: 12.5px; }
  .dbh-beds-units em { font: 500 11px var(--dbh-beds-mono); font-style: normal; font-variant-numeric: tabular-nums; }
  .dbh-beds-ubar { grid-column: 1 / -1; display: flex; height: 4px; border-radius: 2px; overflow: hidden; background: var(--dbh-beds-line); }
  .dbh-beds-ubar i { width: calc(var(--v) * 100%); background: var(--sc); transition: width 500ms var(--dbh-beds-spring); }
  .dbh-beds-filter { display: grid; gap: 1px; }
  .dbh-beds-filter legend { margin-bottom: 6px; padding: 0 6px; }
  .dbh-beds-filter label { display: grid; grid-template-columns: 14px 1fr auto; align-items: center; gap: 9px; padding: 5px 8px; border-radius: 8px; cursor: pointer; font-size: 12.5px; transition: background-color 150ms, opacity 150ms; }
  .dbh-beds-filter label:hover { background: color-mix(in oklch, var(--dbh-beds-ink) 5%, transparent); }
