  D('acts').innerHTML = acts.map(([label, , primary], i) => `<button type="button" data-a="${i}"${primary ? ' data-primary' : ''}${i === 0 && noMatch ? ' disabled' : ''}>${typeof label === 'function' ? label(b) : label}</button>`).join('') + (noMatch ? `<p>No ED patient is waiting for ${b.unit.type}.</p>` : '');
  paintQueue(b.s === 'avail' ? b.unit.need : null);
}
D('acts').addEventListener('click', e => {
  const btn = e.target.closest('[data-a]');
  if (!btn || !openBed) return;
  ACTIONS[openBed.s][+btn.dataset.a][1](openBed);
  const first = $('[data-a]:not(:disabled)', D('acts'));
  if (first) first.focus(); else $('.dbh-beds-x', drawer).focus();
});
function openDrawer(b, el) {
  openBed = b; opener = el;
  $$('.dbh-beds-bed[aria-pressed="true"]', board).forEach(x => x.setAttribute('aria-pressed', 'false'));
  el.setAttribute('aria-pressed', 'true');
  paintDrawer();
  drawer.inert = false;
  drawer.dataset.open = '';
  D('title').focus({ preventScroll: true });
}
function closeDrawer() {
  if (!openBed) return;
  delete drawer.dataset.open;
  drawer.inert = true;
  const el = $(`.dbh-beds-bed[data-id="${openBed.id}"]`, board);
  if (el) { el.setAttribute('aria-pressed', 'false'); el.focus({ preventScroll: true }); }
  openBed = null;
  paintQueue(null);
}
$('.dbh-beds-x', drawer).addEventListener('click', closeDrawer);
scrim.addEventListener('click', closeDrawer);
root.addEventListener('keydown', e => {
  if (e.key !== 'Escape') return;
  if (openBed) { e.preventDefault(); closeDrawer(); }
  else if (qPick) { e.preventDefault(); qPick = null; paintQueue(null); }
});
board.addEventListener('click', e => { const el = e.target.closest('.dbh-beds-bed'); if (el) openDrawer(BEDS.find(b => b.id === el.dataset.id), el); });
board.addEventListener('keydown', e => {
  const el = e.target.closest('.dbh-beds-bed');
  if (!el || !['ArrowRight', 'ArrowLeft', 'ArrowDown', 'ArrowUp'].includes(e.key)) return;
  const all = $$('.dbh-beds-bed', board), i = all.indexOf(el);
  const rc = el.getBoundingClientRect();
  let target = null;
  if (e.key === 'ArrowRight') target = all[i + 1];
  else if (e.key === 'ArrowLeft') target = all[i - 1];
  else {
    const down = e.key === 'ArrowDown';
    target = all.filter(x => { const q = x.getBoundingClientRect(); return down ? q.top > rc.bottom - 2 : q.bottom < rc.top + 2; })
      .sort((a, b) => { const A = a.getBoundingClientRect(), B = b.getBoundingClientRect(); return (down ? A.top - B.top : B.top - A.top) || Math.abs(A.left - rc.left) - Math.abs(B.left - rc.left); })
      .filter((x, _, arr) => Math.abs(x.getBoundingClientRect().top - arr[0].getBoundingClientRect().top) < 4)
      .sort((a, b) => Math.abs(a.getBoundingClientRect().left - rc.left) - Math.abs(b.getBoundingClientRect().left - rc.left))[0];
  }
  if (target) { e.preventDefault(); target.focus(); }
});

function update(b) {
  paintBed(b, true);
  paintUnits(); paintKPIs(); renderCensus();
  if (openBed) paintDrawer(); else paintQueue(null);
}

/* ---------- unit tabs ---------- */
const utabs = $$('button', unitsEl);
function pickUnit(btn) {
  utabs.forEach(x => { const o = x === btn; x.setAttribute('aria-selected', o); x.tabIndex = o ? 0 : -1; });
  unitSel = btn.dataset.u;
  closeDrawer();
  renderBoard();
  board.scrollTop = 0;
}
unitsEl.addEventListener('click', e => { const b = e.target.closest('button'); if (b) pickUnit(b); });
unitsEl.addEventListener('keydown', e => {
  const i = utabs.indexOf(document.activeElement);
  if (i < 0) return;
  const j = ['ArrowDown', 'ArrowRight'].includes(e.key) ? (i + 1) % utabs.length : ['ArrowUp', 'ArrowLeft'].includes(e.key) ? (i - 1 + utabs.length) % utabs.length : -1;
  if (j < 0) return;
  e.preventDefault(); utabs[j].focus(); pickUnit(utabs[j]);
});

renderBoard();
paintUnits();
paintKPIs();
paintQueue(null);

