@property --dbh-fuel-a { syntax: "<percentage>"; inherits: false; initial-value: 0%; }
@property --dbh-fuel-b { syntax: "<percentage>"; inherits: false; initial-value: 0%; }
@keyframes dbh-fuel-rise { from { opacity: 0; transform: translateY(10px); } }
@keyframes dbh-fuel-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes dbh-fuel-fly { from { opacity: 0; transform: translate(var(--dx), var(--dy)) scale(0.2); } }
@keyframes dbh-fuel-wipe { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes dbh-fuel-fade { from { opacity: 0; } }
@keyframes dbh-fuel-reveal { from { opacity: 0; transform: translateY(14px) scale(0.97); } }

.dbh-fuel {
  /* re-theme with these five */
  --dbh-fuel-paper: oklch(0.975 0.011 92);
  --dbh-fuel-ink: oklch(0.25 0.026 45);
  --dbh-fuel-p: oklch(0.65 0.18 33);
  --dbh-fuel-c: oklch(0.84 0.15 88);
  --dbh-fuel-f: oklch(0.66 0.13 132);
  /* derived */
  --dbh-fuel-card: color-mix(in oklch, var(--dbh-fuel-paper), white 72%);
  --dbh-fuel-sunk: color-mix(in oklch, var(--dbh-fuel-paper), var(--dbh-fuel-ink) 5%);
  --dbh-fuel-edge: color-mix(in oklch, var(--dbh-fuel-ink) 84%, var(--dbh-fuel-paper));
  --dbh-fuel-line: color-mix(in oklch, var(--dbh-fuel-ink) 11%, transparent);
  --dbh-fuel-line2: color-mix(in oklch, var(--dbh-fuel-ink) 22%, transparent);
  --dbh-fuel-muted: color-mix(in oklch, var(--dbh-fuel-ink) 64%, var(--dbh-fuel-paper));
  --dbh-fuel-faint: color-mix(in oklch, var(--dbh-fuel-ink) 44%, var(--dbh-fuel-paper));
  --dbh-fuel-hover: color-mix(in oklch, var(--dbh-fuel-ink) 6%, transparent);
  --dbh-fuel-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --dbh-fuel-spring: linear(0, 0.03 2%, 0.13 5%, 0.53 13%, 0.9 21%, 1.06 28%, 1.09 33%, 1.05 41%, 1.01 51%, 0.995 62%, 1);
  --dbh-fuel-round: ui-rounded, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dbh-fuel-mono: ui-monospace, Menlo, Consolas, monospace;

  width: 100%;
  height: var(--dbh-fuel-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 16px;
  background: var(--dbh-fuel-paper);
  color: var(--dbh-fuel-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: light;
  accent-color: var(--dbh-fuel-p);
  box-shadow: inset 0 0 0 1px var(--dbh-fuel-line2);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbh-fuel-p); outline-offset: 2px; border-radius: 7px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul, & ol { list-style: none; margin: 0; padding: 0; }
  & dl, & dd { margin: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  [data-m="p"] { --m: var(--dbh-fuel-p); }
  [data-m="c"] { --m: var(--dbh-fuel-c); }
  [data-m="f"] { --m: var(--dbh-fuel-f); }

  .dbh-fuel-eyebrow { font-size: 10.5px; font-weight: 680; letter-spacing: 0.11em; text-transform: uppercase; color: var(--dbh-fuel-muted); }
  .dbh-fuel-meta { font: 500 11px var(--dbh-fuel-mono); color: var(--dbh-fuel-faint); font-variant-numeric: tabular-nums; }
  .dbh-fuel-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

  /* ---------- shell ---------- */
  .dbh-fuel-app { display: grid; height: 100%; grid-template-columns: 206px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "side top" "side main"; }
  .dbh-fuel-side { grid-area: side; min-height: 0; overflow: auto; display: flex; flex-direction: column; gap: 20px; padding: 18px 12px 16px; border-right: 1px solid var(--dbh-fuel-line2); background: var(--dbh-fuel-sunk); scrollbar-width: thin; scrollbar-color: var(--dbh-fuel-line2) transparent; }
  .dbh-fuel-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px; }
  .dbh-fuel-brand svg { flex: none; width: 32px; height: 32px; padding: 5px; border-radius: 10px; background: var(--dbh-fuel-c); fill: none; stroke: var(--dbh-fuel-ink); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; box-shadow: inset 0 0 0 1px var(--dbh-fuel-edge); }
  .dbh-fuel-brand span { display: grid; line-height: 1.15; min-width: 0; }
  .dbh-fuel-brand b { font: 800 17px/1.1 var(--dbh-fuel-round); letter-spacing: -0.02em; }
  .dbh-fuel-brand small { font-size: 11px; color: var(--dbh-fuel-muted); white-space: nowrap; }

  .dbh-fuel-nav { display: grid; gap: 3px; }
  .dbh-fuel-nav button { display: flex; align-items: center; gap: 10px; width: 100%; padding: 8px 10px; border-radius: 10px; font-weight: 600; color: var(--dbh-fuel-muted); transition: background-color 160ms, color 160ms; }
  .dbh-fuel-nav svg { flex: none; width: 19px; height: 19px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  .dbh-fuel-nav button:hover { color: var(--dbh-fuel-ink); background: var(--dbh-fuel-hover); }
  .dbh-fuel-nav [aria-current="page"] { color: var(--dbh-fuel-paper); background: var(--dbh-fuel-ink); }
  .dbh-fuel-nav [aria-current="page"] svg circle { fill: var(--dbh-fuel-c); stroke: var(--dbh-fuel-c); }

  .dbh-fuel-who { display: grid; gap: 12px; margin-top: auto; padding: 12px; border-radius: 12px; background: var(--dbh-fuel-card); box-shadow: inset 0 0 0 1px var(--dbh-fuel-line2); }
  .dbh-fuel-person { display: flex; align-items: center; gap: 10px; min-width: 0; }
  .dbh-fuel-person > span:last-child { display: grid; line-height: 1.25; min-width: 0; }
  .dbh-fuel-person b { font-weight: 650; font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dbh-fuel-person small { font-size: 11px; color: var(--dbh-fuel-muted); }
  .dbh-fuel-avatar { flex: none; display: grid; place-items: center; width: 32px; height: 32px; border-radius: 50%; background: var(--dbh-fuel-p); color: var(--dbh-fuel-ink); font: 750 11.5px var(--dbh-fuel-round); box-shadow: inset 0 0 0 1px var(--dbh-fuel-edge); }
  .dbh-fuel-targets { display: grid; gap: 3px; font-size: 12px; }
  .dbh-fuel-targets div { display: flex; align-items: center; gap: 7px; }
  .dbh-fuel-targets div::before { content: ""; width: 7px; height: 7px; border-radius: 2px; background: var(--m, var(--dbh-fuel-line2)); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dbh-fuel-ink) 30%, transparent); }
  .dbh-fuel-targets dt { color: var(--dbh-fuel-muted); }
  .dbh-fuel-targets dd { margin-left: auto; font: 550 11.5px var(--dbh-fuel-mono); font-variant-numeric: tabular-nums; }
  .dbh-fuel-fine { font-size: 11px; line-height: 1.45; color: var(--dbh-fuel-faint); padding: 0 4px; }

  /* ---------- header ---------- */
  .dbh-fuel-top { grid-area: top; display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 10px 18px; padding: 18px 20px 14px; }
  .dbh-fuel-title { display: grid; gap: 4px; min-width: 0; }
  .dbh-fuel-h { font: 800 clamp(21px, 0.9rem + 1.5cqi, 30px)/1.02 var(--dbh-fuel-round); letter-spacing: -0.03em; }
  .dbh-fuel-tools { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
  .dbh-fuel-step { display: flex; align-items: center; height: 34px; border-radius: 99px; box-shadow: inset 0 0 0 1px var(--dbh-fuel-edge); background: var(--dbh-fuel-card); }
  .dbh-fuel-step button { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; transition: background-color 150ms, opacity 150ms; }
  .dbh-fuel-step button:hover:not(:disabled) { background: var(--dbh-fuel-hover); }
  .dbh-fuel-step button:disabled { opacity: 0.3; cursor: default; }
  .dbh-fuel-step svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  .dbh-fuel-step span { min-width: 7.2em; text-align: center; font-weight: 650; font-variant-numeric: tabular-nums; }
  .dbh-fuel-range, .dbh-fuel-chips { display: flex; padding: 3px; gap: 2px; border-radius: 99px; box-shadow: inset 0 0 0 1px var(--dbh-fuel-edge); background: var(--dbh-fuel-card); }
  .dbh-fuel-range button, .dbh-fuel-chips button { height: 28px; padding: 0 12px; border-radius: 99px; font-weight: 600; font-size: 12.5px; color: var(--dbh-fuel-muted); font-variant-numeric: tabular-nums; transition: background-color 160ms, color 160ms; }
  .dbh-fuel-range button:hover, .dbh-fuel-chips button:hover { color: var(--dbh-fuel-ink); }
  .dbh-fuel-range [aria-checked="true"], .dbh-fuel-chips [aria-checked="true"] { background: var(--dbh-fuel-ink); color: var(--dbh-fuel-paper); }
  .dbh-fuel-chips [data-m][aria-checked="true"] { background: var(--m); color: var(--dbh-fuel-ink); box-shadow: inset 0 0 0 1px var(--dbh-fuel-edge); }
  /* the range only matters to the multi-day views */
  &:has(.dbh-fuel-nav [data-view="day"][aria-current]) .dbh-fuel-range { display: none; }

  /* ---------- views and panels ---------- */
  .dbh-fuel-main { grid-area: main; min-width: 0; min-height: 0; padding: 0 20px 18px; overflow: hidden; }
  .dbh-fuel-view { height: 100%; display: grid; gap: 14px; transition: opacity 300ms var(--dbh-fuel-ease), translate 420ms var(--dbh-fuel-ease); @starting-style { opacity: 0; translate: 0 10px; } }
  .dbh-fuel-day { grid-template-columns: minmax(0, 1.08fr) minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "log energy" "log pace"; }
  .dbh-fuel-bal { grid-template-columns: minmax(0, 1.12fr) minmax(0, 1fr); grid-template-areas: "tern days"; }
  .dbh-fuel-foods { grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr); grid-template-areas: "rank meal"; }
  .dbh-fuel-log { grid-area: log; }
  .dbh-fuel-energy { grid-area: energy; }
  .dbh-fuel-pace { grid-area: pace; }
  .dbh-fuel-tern { grid-area: tern; }
  .dbh-fuel-days { grid-area: days; }
  .dbh-fuel-flist { grid-area: rank; }
  .dbh-fuel-bymeal { grid-area: meal; }

  .dbh-fuel-panel { position: relative; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); border-radius: 14px; background: var(--dbh-fuel-card); box-shadow: inset 0 0 0 1px var(--dbh-fuel-edge); animation: dbh-fuel-rise 560ms var(--dbh-fuel-ease) both; animation-delay: calc(var(--i, 0) * 80ms); }
  .dbh-fuel-ph { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 6px 12px; padding: 12px 14px 8px; }
  .dbh-fuel-ph h3 { font-size: 13px; font-weight: 720; letter-spacing: -0.005em; }
  .dbh-fuel-key { display: flex; flex-wrap: wrap; gap: 4px 12px; font-size: 11.5px; color: var(--dbh-fuel-muted); }
  .dbh-fuel-key li { display: flex; align-items: center; gap: 6px; }
  .dbh-fuel-key i { width: 14px; height: 0; border-top: 2px solid var(--dbh-fuel-ink); }
  .dbh-fuel-key [data-k="typ"] i { border-top: 2px dotted var(--dbh-fuel-muted); }
  .dbh-fuel-key [data-k="tgt"] i { border-top: 1.5px dashed var(--dbh-fuel-p); }
  .dbh-fuel-key [data-k="in"] i, .dbh-fuel-key [data-k="out"] i { width: 9px; height: 9px; border: 0; border-radius: 50%; background: var(--dbh-fuel-ink); }
  .dbh-fuel-key [data-k="out"] i { background: var(--dbh-fuel-card); box-shadow: inset 0 0 0 1.5px var(--dbh-fuel-ink); }
  .dbh-fuel-key [data-k="avg"] i { width: 9px; height: 9px; border: 0; rotate: 45deg; background: var(--dbh-fuel-p); box-shadow: 0 0 0 1.5px var(--dbh-fuel-ink); }

  /* ---------- meal log, one subgrid so every column lines up across meals ---------- */
  .dbh-fuel-meals { min-height: 0; overflow: auto; display: grid; grid-template-columns: minmax(0, 1fr) auto 3.3em 50px; column-gap: 10px; align-content: start; padding: 0 14px 12px; scrollbar-width: thin; scrollbar-color: var(--dbh-fuel-line2) transparent; }
  .dbh-fuel-meal { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; padding: 9px 0 4px; border-top: 1px dashed var(--dbh-fuel-line2); animation: dbh-fuel-rise 460ms var(--dbh-fuel-ease) both; animation-delay: calc(var(--i, 0) * 55ms); }
  .dbh-fuel-meal:first-child { border-top: 0; padding-top: 2px; }
  .dbh-fuel-mhead { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; align-items: baseline; margin-bottom: 2px; }
  .dbh-fuel-mhead b { font: 750 13px var(--dbh-fuel-round); letter-spacing: -0.01em; }
  .dbh-fuel-mhead time { margin-left: 8px; font: 500 11px var(--dbh-fuel-mono); color: var(--dbh-fuel-faint); }
  .dbh-fuel-mhead em { grid-column: 3; font: 700 12.5px var(--dbh-fuel-mono); font-style: normal; text-align: right; font-variant-numeric: tabular-nums; }
  .dbh-fuel-mhead .dbh-fuel-split { grid-column: 4; align-self: center; }
  .dbh-fuel-items { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; }
  .dbh-fuel-item { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; align-items: center; min-height: 34px; padding: 3px 0; border-radius: 8px; transition: background-color 200ms; }
  .dbh-fuel-item:hover { background: color-mix(in oklch, var(--dbh-fuel-ink) 3.5%, transparent); }
  .dbh-fuel-iname { display: grid; line-height: 1.25; min-width: 0; padding-left: 4px; }
  .dbh-fuel-iname b { font-weight: 560; font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dbh-fuel-iname small { font-size: 11px; color: var(--dbh-fuel-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dbh-fuel-qty { display: flex; align-items: center; height: 26px; border-radius: 99px; box-shadow: inset 0 0 0 1px var(--dbh-fuel-line2); }
  .dbh-fuel-qty button { display: grid; place-items: center; width: 26px; height: 26px; border-radius: 50%; color: var(--dbh-fuel-muted); transition: background-color 150ms, color 150ms, scale 220ms var(--dbh-fuel-spring); }
  .dbh-fuel-qty button:hover:not(:disabled) { color: var(--dbh-fuel-ink); background: var(--dbh-fuel-hover); }
  .dbh-fuel-qty button:active:not(:disabled) { scale: 0.86; }
  .dbh-fuel-qty button:disabled { opacity: 0.3; cursor: default; }
  .dbh-fuel-qty svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
  .dbh-fuel-qty output { min-width: 2.1em; text-align: center; font: 650 12px var(--dbh-fuel-mono); font-variant-numeric: tabular-nums; }
  .dbh-fuel-ik { font: 500 12px var(--dbh-fuel-mono); text-align: right; font-variant-numeric: tabular-nums; }
  .dbh-fuel-split { display: flex; gap: 1.5px; height: 7px; border-radius: 3px; overflow: hidden; }
  .dbh-fuel-split i { flex: var(--w) 1 0; min-width: 0; background: var(--m); transition: flex-grow 500ms var(--dbh-fuel-ease); }
  .dbh-fuel-item:has(button:hover) .dbh-fuel-ik, .dbh-fuel-item:has(:focus-visible) .dbh-fuel-ik { font-weight: 700; }
  .dbh-fuel-item[data-edited] .dbh-fuel-iname b::after { content: " · edited"; font-weight: 500; font-size: 11px; color: var(--dbh-fuel-p); }
  @supports (animation-timeline: view()) {
    .dbh-fuel-item { animation: dbh-fuel-reveal linear both; animation-timeline: view(); animation-range: entry 0% entry 90%; }
  }

  /* ---------- energy + bullets ---------- */
  .dbh-fuel-energy { grid-template-rows: auto auto; align-content: start; padding: 14px 16px 12px; gap: 12px; }
  .dbh-fuel-big { display: flex; align-items: center; justify-content: space-between; gap: 14px; }
  .dbh-fuel-kcal p { display: flex; align-items: baseline; gap: 6px; margin-top: 2px; }
  .dbh-fuel-kcal b { font: 800 clamp(34px, 1rem + 3cqi, 50px)/0.95 var(--dbh-fuel-round); letter-spacing: -0.045em; font-variant-numeric: tabular-nums; }
  .dbh-fuel-kcal small { font-size: 12.5px; color: var(--dbh-fuel-muted); font-variant-numeric: tabular-nums; }
  .dbh-fuel-left { display: inline-block; margin-top: 6px; padding: 2px 8px; border-radius: 99px; font: 600 11.5px var(--dbh-fuel-mono); background: var(--dbh-fuel-sunk); font-variant-numeric: tabular-nums; }
  .dbh-fuel-left[data-over] { background: color-mix(in oklch, var(--dbh-fuel-p) 22%, var(--dbh-fuel-card)); }
  .dbh-fuel-pie { position: relative; flex: none; width: 84px; height: 84px; display: grid; place-items: center; }
  .dbh-fuel-pie::before {
    content: ""; position: absolute; inset: 0; border-radius: 50%;
    background: conic-gradient(var(--dbh-fuel-p) 0 var(--dbh-fuel-a), var(--dbh-fuel-c) 0 var(--dbh-fuel-b), var(--dbh-fuel-f) 0);
    mask: radial-gradient(circle, transparent 57%, #000 58%);
    transition: --dbh-fuel-a 900ms var(--dbh-fuel-spring), --dbh-fuel-b 900ms var(--dbh-fuel-spring);
    --dbh-fuel-a: var(--pa, 0%); --dbh-fuel-b: var(--pb, 0%);
  }
