const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const NF = new Intl.NumberFormat('en-US');
const EASE = 'cubic-bezier(0.22, 1, 0.36, 1)';
const BOUNCE = 'cubic-bezier(0.3, 1.3, 0.5, 1)';
const rng = seed => () => { seed |= 0; seed = seed + 0x6D2B79F5 | 0; let t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };
const pad = n => String(n).padStart(2, '0');
const hm = m => pad(Math.floor(m / 60) % 24) + ':' + pad(m % 60);
const fmtQ = q => q === 0.5 ? '½' : q % 1 ? Math.floor(q) + '½' : String(q);
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const after = fn => requestAnimationFrame(() => { if (!root.isConnected) return; requestAnimationFrame(() => { if (!root.isConnected) return; fn(); }); });

