  let left = dayAvg - fl.reduce((a, b) => a + b, 0);
  raw.map((v, j) => [v - fl[j], j]).sort((a, b) => b[0] - a[0]).forEach(([, j]) => { if (left > 0) { fl[j]++; left--; } });
  return { n, dayAvg, cols: CATS.map(([k, name], j) => { const a = acc[k], sh = shares(a); return { k, name, kcal: fl[j], seg: sh.map(v => v * fl[j]), g: [a.p / n, a.c / n, a.f / n], sh }; }) };
}
function renderMeals() {
  const W = mchart.clientWidth, H = mchart.clientHeight;
  if (W < 120 || H < 100) return;
  const D = mealData(), L = 40, Rr = 10, Tp = 22, B = 26;
  const yMax = Math.max(400, Math.ceil(Math.max(...D.cols.map(c => c.kcal)) * 1.12 / 200) * 200);
  const y = v => Tp + (1 - v / yMax) * (H - Tp - B), bw = (W - L - Rr) / CATS.length, cw = Math.min(64, bw * 0.56);
  const enter = !mMounted && !reduce;
  const sameBox = MG && MG.W === W && MG.H === H;
  let g = '';
  for (let v = 0; v <= yMax; v += 200) g += `<line class="dbh-fuel-grid" x1="${L}" x2="${W - Rr}" y1="${y(v).toFixed(1)}" y2="${y(v).toFixed(1)}"/><text x="${L - 7}" y="${(y(v) + 3.5).toFixed(1)}" text-anchor="end">${v}</text>`;
  if (!sameBox) {
    msvg.setAttribute('viewBox', `0 0 ${W} ${H}`);
    msvg.innerHTML = `<g data-mgrid></g><g class="dbh-fuel-mcols"${enter ? ' data-enter' : ''}>${D.cols.map((c, j) => {
      const x0 = L + bw * j + (bw - cw) / 2;
      return ['p', 'c', 'f'].map((m, q) => `<rect class="dbh-fuel-mseg" data-col="${j}" data-q="${q}" data-m="${m}" x="${x0.toFixed(1)}" width="${cw.toFixed(1)}" rx="2" style="fill:var(--m);--k:${j}"/>`).join('') +
        `<text class="dbh-fuel-mtot" data-tot="${j}" x="${(x0 + cw / 2).toFixed(1)}" text-anchor="middle" style="--k:${j}"></text><text class="dbh-fuel-mx" x="${(x0 + cw / 2).toFixed(1)}" y="${H - 7}" text-anchor="middle">${c.name}</text>`;
    }).join('')}</g>`;
  }
  $('[data-mgrid]', msvg).innerHTML = g;
  D.cols.forEach((c, j) => {
    let base = 0;
    c.seg.forEach((v, q) => {
      const r = $(`[data-col="${j}"][data-q="${q}"]`, msvg), y1 = y(base + v), hh = Math.max(0, y(base) - y1);
      r.setAttribute('y', y1.toFixed(1)); r.setAttribute('height', hh.toFixed(1));
      r.style.y = y1.toFixed(1) + 'px'; r.style.height = hh.toFixed(1) + 'px';
      base += v;
    });
    const t = $(`[data-tot="${j}"]`, msvg);
    t.setAttribute('y', (y(c.kcal) - 7).toFixed(1)); t.style.y = (y(c.kcal) - 7).toFixed(1) + 'px';
    t.textContent = NF.format(c.kcal);
  });
  if (enter) setTimeout(() => { if (!root.isConnected) return; const g2 = $('.dbh-fuel-mcols', msvg); if (g2) g2.removeAttribute('data-enter'); }, 1400);
  MG = { W, H, D };
  mMounted = true;
  $('[data-mealmeta]').textContent = `${D.n}-day average`;
  $('[data-mealsum]').innerHTML = `Average day <b>${NF.format(D.dayAvg)} kcal</b> = ${D.cols.map(c => `${c.name.toLowerCase()} ${NF.format(c.kcal)}`).join(' + ')}`;
}
msvg.addEventListener('pointermove', e => {
  const r = e.target.closest('.dbh-fuel-mseg');
  $$('.dbh-fuel-mseg[data-hot]', msvg).forEach(x => { if (x !== r) x.removeAttribute('data-hot'); });
  if (!r || !MG) { mtip.removeAttribute('data-on'); return; }
  r.setAttribute('data-hot', '');
  const c = MG.D.cols[+r.dataset.col], q = +r.dataset.q, m = ['p', 'c', 'f'][q];
  mtip.innerHTML = `<b>${c.name} · ${MN[m]}</b><span><i style="--m:var(--dbh-fuel-${m})"></i>${NF.format(Math.round(c.seg[q]))} kcal / day · ${Math.round(c.g[q])} g</span><span><em>${Math.round(c.sh[q] * 100)}% of ${c.name.toLowerCase()} · ${Math.round(c.seg[q] / MG.D.dayAvg * 100)}% of the day</em></span>`;
  const box = mchart.getBoundingClientRect();
  place(mtip, mchart, e.clientX - box.left, e.clientY - box.top);
});
msvg.addEventListener('pointerleave', () => { mtip.removeAttribute('data-on'); $$('.dbh-fuel-mseg[data-hot]', msvg).forEach(x => x.removeAttribute('data-hot')); });

/* ---------- wiring: views, day stepper, range, metric ---------- */
function selectDay(i) {
  st.sel = clamp(i, 0, N - 1);
  paintHead();
  if (st.view === 'day') { renderLog(); paintEnergy(); renderPace('swap'); }
  if (st.view === 'balance') { paintTern(); rows.forEach((tr, k) => tr.setAttribute('aria-current', String(k === st.sel))); }
}
function show(view) {
  if (view === st.view) return;
  st.view = view;
  navBtns.forEach(b => { if (b.dataset.view === view) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current'); });
  $$('.dbh-fuel-view').forEach(v => { v.hidden = v.dataset.view !== view; });
  hotTern(-1); clearPace();
  paintHead();
  if (view === 'day') { renderLog(); paintEnergy(); renderPace(pMounted ? 'swap' : 'enter'); }
  if (view === 'balance') { renderTable(false); renderTern(); }
  if (view === 'foods') { renderFoods(false); renderMeals(); }
}
$('.dbh-fuel-nav').addEventListener('click', e => { const b = e.target.closest('button'); if (b) show(b.dataset.view); });
$('.dbh-fuel-nav').addEventListener('keydown', e => {
  const n = navBtns.indexOf(e.target), d = { ArrowDown: 1, ArrowRight: 1, ArrowUp: -1, ArrowLeft: -1 }[e.key];
  if (n < 0 || !d) return;
  e.preventDefault();
  navBtns[(n + d + navBtns.length) % navBtns.length].focus();
});
$('.dbh-fuel-step').addEventListener('click', e => { const b = e.target.closest('[data-step]'); if (b && !b.disabled) selectDay(st.sel + +b.dataset.step); });
function radios(groupSel, onPick) {
  const group = $(groupSel), btns = $$('[role="radio"]', group);
  const pickB = b => {
    btns.forEach(x => { const on = x === b; x.setAttribute('aria-checked', String(on)); x.tabIndex = on ? 0 : -1; });
    onPick(b);
  };
  group.addEventListener('click', e => { const b = e.target.closest('[role="radio"]'); if (b && b.getAttribute('aria-checked') !== 'true') pickB(b); });
  group.addEventListener('keydown', e => {
    const n = btns.indexOf(e.target), d = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 }[e.key];
    if (n < 0 || !d) return;
    e.preventDefault();
    const b = btns[(n + d + btns.length) % btns.length];
    b.focus(); pickB(b);
  });
}
radios('.dbh-fuel-range', b => {
  st.range = +b.dataset.range;
  paintHead();
  if (st.view === 'balance') { paintTern(); renderTable(true); }
  if (st.view === 'foods') { renderFoods(true); renderMeals(); }
});
radios('.dbh-fuel-chips', b => { st.metric = b.dataset.metric; renderFoods(true); });

const ro = new ResizeObserver(entries => {
  if (!root.isConnected) { ro.disconnect(); return; }
  entries.forEach(en => {
    const el = en.target, w = Math.round(en.contentRect.width), h = Math.round(en.contentRect.height);
    if (!w || !h || (el._w === w && el._h === h)) return;
    el._w = w; el._h = h;
    if (el === pchart && st.view === 'day') renderPace(pMounted ? 'none' : 'enter');
    if (el === tchart && st.view === 'balance') renderTern();
    if (el === mchart && st.view === 'foods') renderMeals();
  });
});
[pchart, tchart, mchart].forEach(el => ro.observe(el));

paintHead();
renderLog();
paintEnergy();
